css:
@property --mnt-deck-tone {
  syntax: "<color>";
  inherits: true;
  initial-value: oklch(0.6 0 0);
}

/* Re-theme with --mnt-deck-bg, -paper, -ink and -accent. */
.mnt-deck {
  --mnt-deck-bg: oklch(0.215 0.009 65);
  --mnt-deck-paper: oklch(0.985 0.005 85);
  --mnt-deck-ink: oklch(0.24 0.014 60);
  --mnt-deck-accent: oklch(0.76 0.14 66);
  --mnt-deck-ok: oklch(0.6 0.14 152);
  --mnt-deck-bad: oklch(0.59 0.19 29);

  --mnt-deck-fg: color-mix(in oklch, var(--mnt-deck-paper) 93%, var(--mnt-deck-bg));
  --mnt-deck-dim: color-mix(in oklch, var(--mnt-deck-paper) 52%, var(--mnt-deck-bg));
  --mnt-deck-line: color-mix(in oklch, var(--mnt-deck-paper) 10%, transparent);
  --mnt-deck-raise: color-mix(in oklch, var(--mnt-deck-paper) 6%, var(--mnt-deck-bg));
  --mnt-deck-muted: color-mix(in oklch, var(--mnt-deck-ink) 60%, var(--mnt-deck-paper));
  --mnt-deck-r: 14px;
  --mnt-deck-ease: cubic-bezier(.22, 1, .36, 1);
  --mnt-deck-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  min-width: 0;
  width: 100%;
  min-height: 440px;
  padding: 16px;
  border-radius: 18px;
  overflow: hidden;
  overflow: clip;
  color: var(--mnt-deck-fg);
  background:
    radial-gradient(120% 55% at 50% 112%, color-mix(in oklch, var(--mnt-deck-accent) 13%, transparent), transparent 70%),
    var(--mnt-deck-bg);
  box-shadow: inset 0 0 0 1px var(--mnt-deck-line);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mnt-deck { --mnt-deck-spring: cubic-bezier(.3, 1.3, .5, 1); }
}
:where(.mnt-deck) *, :where(.mnt-deck) *::before, :where(.mnt-deck) *::after { box-sizing: border-box; }
:where(.mnt-deck) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnt-deck) :focus-visible { outline: 2px solid var(--mnt-deck-accent); outline-offset: 2px; }
.mnt-deck svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }

/* ---------- the page behind the toasts ---------- */
.mnt-deck__head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}
.mnt-deck__mark {
  display: grid; place-items: center;
  width: 34px; height: 34px; border-radius: 10px;
  color: var(--mnt-deck-bg);
  background: var(--mnt-deck-accent);
  & svg { width: 20px; height: 20px; stroke-width: 1.9; }
}
.mnt-deck__eyebrow {
  margin: 0; font-size: 10.5px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  color: var(--mnt-deck-dim);
}
.mnt-deck__name {
  margin: 1px 0 0; font: 650 clamp(15px, 4.6cqi, 17px)/1.2 ui-monospace, Menlo, monospace;
  letter-spacing: -.02em; text-wrap: balance; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.mnt-deck__health {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 9px 4px 8px; border-radius: 99px;
  font-size: 11.5px; font-weight: 550;
  color: color-mix(in oklch, var(--mnt-deck-ok) 70%, var(--mnt-deck-paper));
  background: color-mix(in oklch, var(--mnt-deck-ok) 16%, transparent);
  & i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; box-shadow: 0 0 0 3px color-mix(in oklch, currentColor 25%, transparent); }
}
.mnt-deck__stats {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 16px 0 0; border-radius: 12px; overflow: hidden;
  box-shadow: inset 0 0 0 1px var(--mnt-deck-line);
  & div { padding: 9px 11px; }
  & div + div { box-shadow: inset 1px 0 0 var(--mnt-deck-line); }
  & dt { font-size: 10.5px; color: var(--mnt-deck-dim); letter-spacing: .02em; }
  & dd { margin: 2px 0 0; font: 600 clamp(12.5px, 4.4cqi, 14px)/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; white-space: nowrap; }
}
.mnt-deck__fire {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: 14px;
  & button {
    display: flex; align-items: center; gap: 8px;
    padding: 9px 11px; border-radius: 10px;
    font-size: 12.5px; font-weight: 550;
    background: var(--mnt-deck-raise);
    box-shadow: inset 0 0 0 1px var(--mnt-deck-line), inset 0 1px 0 color-mix(in oklch, var(--mnt-deck-paper) 6%, transparent);
    transition: background-color .2s var(--mnt-deck-ease), translate .25s var(--mnt-deck-spring);
  }
  & button svg { width: 16px; height: 16px; color: var(--mnt-deck-accent); }
  & button:hover { background: color-mix(in oklch, var(--mnt-deck-paper) 11%, var(--mnt-deck-bg)); }
  & button:active { translate: 0 1px; }
  & button[aria-disabled="true"] { opacity: .45; cursor: progress; }
}
.mnt-deck__hint {
  margin: 12px 0 0; font-size: 11.5px; color: var(--mnt-deck-dim); text-wrap: pretty;
  & kbd {
    display: inline-block; margin-left: 3px; padding: 1px 5px; border-radius: 4px;
    font: 500 10.5px/1.4 ui-monospace, Menlo, monospace;
    color: var(--mnt-deck-fg); background: var(--mnt-deck-raise); box-shadow: inset 0 -1px 0 var(--mnt-deck-line), 0 0 0 1px var(--mnt-deck-line);
  }
}
@container (min-width: 400px) {
  .mnt-deck__fire { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .mnt-deck__fire button { justify-content: center; }
}

/* ---------- toast region ---------- */
.mnt-deck__region {
  position: absolute; left: 14px; right: 14px; bottom: 14px; height: 0;
  z-index: 2; pointer-events: none;
}
.mnt-deck__list { list-style: none; margin: 0; padding: 0; }
.mnt-deck__empty {
  position: absolute; left: 0; right: 0; bottom: 0; height: 58px; margin: 0;
  display: grid; place-items: center;
  border-radius: var(--mnt-deck-r); border: 1px dashed var(--mnt-deck-line);
  font-size: 12px; color: var(--mnt-deck-dim);
  opacity: 0; transition: opacity .4s var(--mnt-deck-ease) .25s;
}
.mnt-deck[data-empty] .mnt-deck__empty { opacity: 1; }

.mnt-deck__toast {
  --mnt-deck-tone: var(--mnt-deck-muted);
  position: absolute; left: 0; right: 0; bottom: 0;
  pointer-events: auto; touch-action: pan-y; cursor: grab;
  -webkit-user-select: none; user-select: none;
  border-radius: var(--mnt-deck-r);
  transform-origin: 50% 100%;
  transform: translateY(var(--ty, 0px)) scale(calc(1 - var(--i, 0) * .055));
  translate: var(--dx, 0px) var(--dy, 0px);
  opacity: calc(clamp(0, 3 - var(--i, 0), 1) * var(--fade, 1));
  transition:
    transform .6s var(--mnt-deck-spring),
    translate .45s var(--mnt-deck-ease),
    opacity .3s var(--mnt-deck-ease),
    --mnt-deck-tone .5s var(--mnt-deck-ease);
  &:focus-visible { outline: none; }
  &:focus-visible .mnt-deck__card { box-shadow: inset 0 0 0 2px var(--mnt-deck-accent); }
  /* bridges the gap to the toast above so hover survives the fan-out */
  &::before { content: ""; position: absolute; left: 0; right: 0; bottom: 100%; height: 12px; }
  &[data-state="success"] { --mnt-deck-tone: var(--mnt-deck-ok); }
  &[data-state="error"] { --mnt-deck-tone: var(--mnt-deck-bad); }
  &[data-state="info"] { --mnt-deck-tone: var(--mnt-deck-accent); }
}
@starting-style {
  .mnt-deck__toast { translate: 0 calc(100% + 24px); opacity: 0; }
}
.mnt-deck__region[data-open] .mnt-deck__toast {
  transform: translateY(var(--y, 0px)) scale(1);
  opacity: var(--fade, 1);
}
.mnt-deck__toast.is-drag {
  cursor: grabbing;
  transition: transform .6s var(--mnt-deck-spring), --mnt-deck-tone .5s var(--mnt-deck-ease);
}
.mnt-deck__toast.is-leaving {
  z-index: 60 !important;
  opacity: 0;
  pointer-events: none;
  transition:
    transform .6s var(--mnt-deck-spring),
    translate .42s cubic-bezier(.4, 0, .9, .5),
    opacity .32s var(--mnt-deck-ease) .06s;
}

.mnt-deck__card {
  position: relative; z-index: 1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  grid-template-areas: "ico copy act x";
  align-items: center;
  column-gap: 10px; row-gap: 8px;
  min-height: 58px;
  padding: 11px 8px 12px 11px;
  border-radius: var(--mnt-deck-r);
  color: var(--mnt-deck-ink);
  background:
    radial-gradient(70% 150% at 0% 50%, color-mix(in oklch, var(--mnt-deck-tone) 14%, transparent), transparent 70%),
    var(--mnt-deck-paper);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnt-deck-ink) 9%, transparent);
  clip-path: inset(var(--clip, 0px) 0 0 0 round var(--mnt-deck-r));
  transition: clip-path .5s var(--mnt-deck-ease), box-shadow .2s;
  & > * { transition: opacity .3s var(--mnt-deck-ease); }
  &:has(> .mnt-deck__act[hidden]) { grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "ico copy x"; }
}
.mnt-deck__region[data-open] .mnt-deck__card { clip-path: inset(0 0 0 0 round var(--mnt-deck-r)); }
.mnt-deck__region:not([data-open]) .mnt-deck__toast:not([data-front]) .mnt-deck__card > * { opacity: 0; }

.mnt-deck__ico {
  grid-area: ico; display: grid; place-items: center; width: 28px; height: 28px;
  & svg { width: 24px; height: 24px; overflow: visible; stroke: var(--mnt-deck-tone); stroke-width: 1.8; }
}
.mnt-deck__ring {
  stroke: color-mix(in oklch, var(--mnt-deck-tone) 28%, transparent);
  stroke-dasharray: 100 0;
  transform-box: fill-box; transform-origin: center;
  transition: stroke-dasharray .7s var(--mnt-deck-ease);
}
.mnt-deck__toast[data-state="loading"] .mnt-deck__ring {
  stroke: var(--mnt-deck-tone);
  stroke-dasharray: 26 74;
  animation: mnt-deck-spin .8s linear infinite;
}
.mnt-deck__g {
  stroke-dasharray: 1 1; stroke-dashoffset: 1;
  transition: stroke-dashoffset .18s var(--mnt-deck-ease);
}
.mnt-deck__dot {
  fill: var(--mnt-deck-tone); stroke: none; opacity: 0; scale: .2;
  transform-box: fill-box; transform-origin: center;
  transition: opacity .15s, scale .15s;
}
.mnt-deck__toast:is([data-glyph="check"]) .mnt-deck__g[data-k="check"],
.mnt-deck__toast:is([data-glyph="alert"]) .mnt-deck__g[data-k="alert"],
.mnt-deck__toast:is([data-glyph="person"]) .mnt-deck__g[data-k="person"],
.mnt-deck__toast:is([data-glyph="undo"]) .mnt-deck__g[data-k="undo"] {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset .5s var(--mnt-deck-ease) .18s;
}
.mnt-deck__toast[data-glyph="alert"] .mnt-deck__dot {
  opacity: 1; scale: 1;
  transition: opacity .2s .5s, scale .45s var(--mnt-deck-spring) .5s;
}

.mnt-deck__copy { grid-area: copy; min-width: 0; }
.mnt-deck__title {
  margin: 0; font-size: 13.5px; font-weight: 630; letter-spacing: -.006em; line-height: 1.3;
  text-wrap: balance; font-variant-numeric: tabular-nums;
}
.mnt-deck__desc {
  margin: 2px 0 0; font-size: 12px; line-height: 1.4; color: var(--mnt-deck-muted);
  text-wrap: pretty; font-variant-numeric: tabular-nums;
}
.mnt-deck__act {
  grid-area: act; justify-self: start;
  padding: 6px 10px; border-radius: 8px;
  font-size: 12px; font-weight: 620; white-space: nowrap;
  color: var(--mnt-deck-paper);
  background: var(--mnt-deck-ink);
  transition: background-color .2s, scale .25s var(--mnt-deck-spring);
  &:hover { background: color-mix(in oklch, var(--mnt-deck-ink) 82%, var(--mnt-deck-tone)); }
  &:active { scale: .96; }
  &[hidden] { display: none; }
}
.mnt-deck__x {
  grid-area: x; display: grid; place-items: center;
  width: 26px; height: 26px; border-radius: 8px;
  color: var(--mnt-deck-muted);
  transition: background-color .2s, color .2s;
  & svg { width: 15px; height: 15px; }
  &:hover { color: var(--mnt-deck-ink); background: color-mix(in oklch, var(--mnt-deck-ink) 7%, transparent); }
}
.mnt-deck__life {
  position: absolute; left: 12px; right: 12px; bottom: 4px; height: 2px; border-radius: 2px;
  background: color-mix(in oklch, var(--mnt-deck-tone) 75%, transparent);
  transform: scaleX(var(--life, 1)); transform-origin: left center;
  opacity: 0; transition: opacity .3s;
}
.mnt-deck__toast[data-timed] .mnt-deck__life { opacity: .5; }
.mnt-deck__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 280px) {
  .mnt-deck__health { padding: 6px; }
  .mnt-deck__health span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
@container (max-width: 330px) {
  .mnt-deck__card {
    grid-template-columns: auto minmax(0, 1fr) auto;
    grid-template-areas: "ico copy x" ". act act";
  }
  .mnt-deck__stats div { padding: 8px 9px; }
}

@keyframes mnt-deck-spin { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .mnt-deck__toast,
  .mnt-deck__toast.is-drag,
  .mnt-deck__toast.is-leaving { transition: opacity .2s linear, --mnt-deck-tone .2s linear; }
  @starting-style {
    .mnt-deck__toast { translate: 0 0; opacity: 0; }
  }
  .mnt-deck__card, .mnt-deck__card > * { transition: opacity .2s linear; }
  .mnt-deck__toast[data-state="loading"] .mnt-deck__ring { animation: none; stroke-dasharray: 3 5.33; }
  .mnt-deck__g, .mnt-deck__dot,
  .mnt-deck__toast[data-glyph] .mnt-deck__g, .mnt-deck__toast[data-glyph] .mnt-deck__dot { transition: none; }
  .mnt-deck__fire button { transition: none; }
}

