const $ = (s, el = root) => el.querySelector(s);
const list = $('.mnt-deck__list');
const region = $('.mnt-deck__region');
const live = $('.mnt-deck__sr');
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = Math.random().toString(36).slice(2, 7);
const GAP = 10, PEEK = 10, MAX = 5;
const items = [];
let seq = 0, raf = 0, last = 0, onscreen = true;
let open = false, hover = false, focused = false, drag = null, lastFire = null, quiet = false;
let build = 4181, version = 11, syncs = 0, deploying = false, asker = 0;

const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const say = (t) => { if (quiet) return; live.textContent = ''; later(40, () => { live.textContent = t; }); };
const stat = (k, v) => { const d = $('[data-stat="' + k + '"]'); if (d) d.textContent = v; };
const active = () => items.filter((i) => !i.leaving);

const GLYPH = '<svg viewBox="0 0 24 24" aria-hidden="true">' +
  '<circle class="mnt-deck__ring" cx="12" cy="12" r="9.25" pathLength="100"/>' +
  '<path class="mnt-deck__g" data-k="check" d="m8.3 12.3 2.6 2.6 4.9-5.2" pathLength="1"/>' +
  '<path class="mnt-deck__g" data-k="alert" d="M12 7.6v5.1" pathLength="1"/>' +
  '<circle class="mnt-deck__dot" cx="12" cy="15.9" r="1.05"/>' +
  '<path class="mnt-deck__g" data-k="person" d="M12 11.3a2.2 2.2 0 1 0 0-4.4 2.2 2.2 0 0 0 0 4.4ZM8.1 16.6c.7-1.8 2.1-2.8 3.9-2.8s3.2 1 3.9 2.8" pathLength="1"/>' +
  '<path class="mnt-deck__g" data-k="undo" d="M9.9 8.6 7.6 10.9l2.3 2.3M7.6 10.9h5.2a2.6 2.6 0 0 1 0 5.2h-1.6" pathLength="1"/>' +
  '</svg>';
const GLYPH_FOR = { success: 'check', error: 'alert', info: 'person', loading: '' };

/* ---------- model ---------- */
const apply = (it, o, swap) => {
  Object.assign(it, { action: null, dur: 0, glyph: null }, o);
  it.left = it.dur;
  const li = it.el;
  li.dataset.state = it.state;
  li.dataset.glyph = it.glyph || GLYPH_FOR[it.state] || '';
  li.toggleAttribute('data-timed', !!it.dur);
  li.style.setProperty('--life', 1);
  $('.mnt-deck__title', li).textContent = it.title;
  $('.mnt-deck__desc', li).textContent = it.desc;
  const b = $('.mnt-deck__act', li), lost = !it.action && b === document.activeElement;
  b.hidden = !it.action;
  if (it.action) b.textContent = it.action.label;
  if (lost) li.focus({ preventScroll: true });
  if (swap && !RM.matches) {
    $('.mnt-deck__copy', li).animate(
      [{ opacity: 0, transform: 'translateY(5px)', filter: 'blur(3px)' }, { opacity: 1, transform: 'none', filter: 'blur(0)' }],
      { duration: 380, easing: 'cubic-bezier(.22,1,.36,1)' });
  }
};

const make = (o) => {
  const it = { id: ++seq, leaving: false };
  const li = document.createElement('li');
  const tid = 'mnt-deck-' + UID + '-' + it.id;
  li.className = 'mnt-deck__toast';
  li.tabIndex = 0;
  li.setAttribute('aria-labelledby', tid + 't');
  li.setAttribute('aria-describedby', tid + 'd');
  li.innerHTML = '<div class="mnt-deck__card"><span class="mnt-deck__ico">' + GLYPH + '</span>' +
    '<div class="mnt-deck__copy"><p class="mnt-deck__title" id="' + tid + 't"></p><p class="mnt-deck__desc" id="' + tid + 'd"></p></div>' +
    '<button type="button" class="mnt-deck__act"></button>' +
    '<button type="button" class="mnt-deck__x" aria-label="Dismiss notification"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7.5 7.5 9 9m0-9-9 9"/></svg></button>' +
    '<i class="mnt-deck__life" aria-hidden="true"></i></div>';
  it.el = li;
  li._it = it;
  apply(it, o, false);
  return it;
};

/* Collapsed: every toast's visible top sits PEEK px above the one in front.
   Expanded: each toast rests on the measured heights of the ones in front of it. */
const layout = () => {
  const act = active();
  const hs = act.map((i) => i.el.offsetHeight);
  const front = hs[0] || 0;
  let acc = 0;
  act.forEach((it, i) => {
    const s = it.el.style, h = hs[i], sc = 1 - i * 0.055, v = Math.min(h, front);
    s.setProperty('--i', i);
    s.setProperty('--y', (-acc).toFixed(1) + 'px');
    s.setProperty('--ty', (v * sc - front - PEEK * i).toFixed(1) + 'px');
    s.setProperty('--clip', Math.max(0, h - front) + 'px');
    s.zIndex = String(50 - i);
    it.el.toggleAttribute('data-front', i === 0);
    acc += h + GAP;
  });
  root.toggleAttribute('data-empty', act.length === 0);
};

const push = (o) => {
  const it = make(o);
  items.unshift(it);
  list.prepend(it.el);
  const act = active();
  if (act.length > MAX) dismiss(act[act.length - 1], 'fade');
  layout();
  say(it.title + '. ' + it.desc);
  kick();
  return it;
};

const resolve = (it, o) => {
  if (it.leaving || !it.el.isConnected) { push(o); return; }
  apply(it, o, true);
  layout();
  say(o.title + '. ' + o.desc);
  kick();
};

const dismiss = (it, dir) => {
  if (!it || it.leaving) return;
  const act = active(), k = act.indexOf(it);
  const li = it.el, hadFocus = li.contains(document.activeElement);
  it.leaving = true;
  li.classList.add('is-leaving');
  if (!RM.matches) {
    if (dir === 'left' || dir === 'right') li.style.setProperty('--dx', (dir === 'left' ? -1 : 1) * (li.offsetWidth + 40) + 'px');
    else if (dir === 'down') li.style.setProperty('--dy', 'calc(100% + 24px)');
  }
  layout();
  if (hadFocus) {
    const rest = active();
    const next = rest[Math.min(k, rest.length - 1)];
    (next ? next.el : (lastFire || $('.mnt-deck__fire button'))).focus({ preventScroll: true });
  }
  later(RM.matches ? 220 : 480, () => {
    li.remove();
    const j = items.indexOf(it);
    if (j > -1) items.splice(j, 1);
  });
};

/* ---------- one clock for every timer; it idles when nothing is timed ---------- */
const loop = (t) => {
  if (!root.isConnected) return;
  raf = 0;
  const dt = last ? Math.min(64, t - last) : 0;
  last = t;
  const hold = open || drag || document.hidden;
  let timed = false;
  for (const it of active()) {
    if (!it.dur) continue;
    timed = true;
    if (hold) continue;
    it.left -= dt;
    it.el.style.setProperty('--life', Math.max(0, it.left / it.dur).toFixed(4));
    if (it.left <= 0) dismiss(it, it.el.hasAttribute('data-front') ? 'down' : 'fade');
  }
  if (timed && onscreen) raf = requestAnimationFrame(loop);
  else last = 0;
};
const kick = () => { if (!raf && onscreen) { last = 0; raf = requestAnimationFrame(loop); } };

const setOpen = () => {
  const o = hover || focused || !!drag;
  if (o !== open) { open = o; region.toggleAttribute('data-open', o); }
  kick();
};

/* ---------- scripted flows ---------- */
const rollback = (it, b) => {
  resolve(it, { state: 'loading', title: 'Rolling back to ' + (b - 1), desc: 'Draining build ' + b + ' from 14 regions' });
  later(2000, () => {
    build = b - 1; stat('build', build);
    resolve(it, { state: 'success', title: 'Back on build ' + (b - 1), desc: 'Build ' + b + ' drained from 14 regions in 21 s', dur: 5000 });
  });
};
const retry = (it) => {
  resolve(it, { state: 'loading', title: 'Retrying 2 variables', desc: 'QUEUE_DSN and SMTP_HOST → Preview' });
  later(1600, () => resolve(it, { state: 'success', title: 'All 23 variables synced', desc: 'Preview picks them up on its next deploy', dur: 5000 }));
};
const timeout = { state: 'error', title: 'Sync timed out', desc: '21 of 23 copied before the eu-central vault stopped responding', action: { label: 'Retry', run: retry } };
const ASKERS = [['Rosa Lindqvist', 'Rosa'], ['Kenji Abe', 'Kenji'], ['Ola Nwosu', 'Ola']];
const request = () => {
  const [full, first] = ASKERS[asker++ % ASKERS.length];
  push({ state: 'info', title: full + ' wants deploy access', desc: 'Developer role · web-storefront',
    action: { label: 'Approve', run: (it) => resolve(it, { state: 'success', title: first + ' can deploy now', desc: 'Developer role · expires in 30 days', dur: 5000 }) } });
};

const FIRE = {
  deploy(btn) {
    if (deploying) return;
    deploying = true;
    btn.setAttribute('aria-disabled', 'true');
    const b = build + 1;
    const it = push({ state: 'loading', title: 'Deploying build ' + b, desc: 'main@7f3c2e1 → 14 regions' });
    later(2600, () => {
      deploying = false;
      btn.removeAttribute('aria-disabled');
      build = b; stat('build', b); stat('deploy', 'just now');
      resolve(it, { state: 'success', title: 'Build ' + b + ' is live', desc: 'Rolled out to 14 regions in 38 s', dur: 6000,
        action: { label: 'Roll back', run: (t) => rollback(t, b) } });
    });
  },
  sync() {
    const n = ++syncs;
    const it = push({ state: 'loading', title: 'Syncing 23 variables', desc: 'Production → Preview' });
    later(2200, () => {
      if (n % 2) resolve(it, timeout);
      else resolve(it, { state: 'success', title: 'All 23 variables synced', desc: 'Preview picks them up on its next deploy', dur: 5000 });
    });
  },
  access: request,
  save() {
    const v = ++version;
    push({ state: 'success', title: 'Saved environment v' + v, desc: '3 variables changed · Production', dur: 5000,
      action: { label: 'Undo', run: (it) => { version = v - 1; resolve(it, { state: 'info', glyph: 'undo', title: 'Restored v' + (v - 1), desc: '3 variables reverted', dur: 4000 }); } } });
  },
};
const run = (it) => { if (it && it.action && !it.leaving) it.action.run(it); };

/* ---------- events ---------- */
root.addEventListener('click', (e) => {
  const f = e.target.closest('[data-fire]');
  if (f) { lastFire = f; FIRE[f.dataset.fire](f); return; }
  const li = e.target.closest('.mnt-deck__toast');
  if (!li || !li._it) return;
  if (e.target.closest('.mnt-deck__x')) dismiss(li._it, 'right');
  else if (e.target.closest('.mnt-deck__act')) run(li._it);
});

root.addEventListener('keydown', (e) => {
  if (e.altKey && e.code === 'KeyT') {
    e.preventDefault();
    const f = active()[0];
    if (f) f.el.focus();
    return;
  }
  const li = e.target.closest && e.target.closest('.mnt-deck__toast');
  if (!li || !li._it) return;
  const act = active(), k = act.indexOf(li._it);
  const go = (j) => { const t = act[Math.max(0, Math.min(act.length - 1, j))]; if (t) t.el.focus(); };
  switch (e.key) {
    case 'ArrowUp': e.preventDefault(); go(k + 1); break;
    case 'ArrowDown': e.preventDefault(); go(k - 1); break;
    case 'Home': e.preventDefault(); go(act.length - 1); break;
    case 'End': e.preventDefault(); go(0); break;
    case 'Delete':
    case 'Backspace':
      if (e.target === li) { e.preventDefault(); dismiss(li._it, 'right'); }
      break;
    case 'Enter':
      if (e.target === li && li._it.action) { e.preventDefault(); run(li._it); }
      break;
    case 'Escape':
      e.preventDefault();
      (lastFire || $('.mnt-deck__fire button')).focus();
      break;
  }
});

list.addEventListener('pointerover', () => { hover = true; setOpen(); });
list.addEventListener('pointerout', (e) => {
  const to = e.relatedTarget;
  if (to && to.closest && list.contains(to) && to.closest('.mnt-deck__toast')) return;
  hover = false; setOpen();
});
region.addEventListener('focusin', () => { focused = true; setOpen(); });
region.addEventListener('focusout', (e) => { if (!region.contains(e.relatedTarget)) { focused = false; setOpen(); } });

list.addEventListener('pointerdown', (e) => {
  const li = e.target.closest('.mnt-deck__toast');
  if (!li || e.button !== 0 || e.target.closest('button') || !li._it || li._it.leaving) return;
  drag = { it: li._it, x0: e.clientX, dx: 0, t: e.timeStamp, v: 0, w: li.offsetWidth, id: e.pointerId, moved: false };
  li.setPointerCapture(e.pointerId);
});
list.addEventListener('pointermove', (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  const dx = e.clientX - drag.x0;
  if (!drag.moved) {
    if (Math.abs(dx) < 4) return;
    drag.moved = true;
    drag.it.el.classList.add('is-drag');
    setOpen();
  }
  const dt = Math.max(1, e.timeStamp - drag.t);
  drag.v = 0.75 * ((dx - drag.dx) / dt) + 0.25 * drag.v;
  drag.dx = dx;
  drag.t = e.timeStamp;
  const s = drag.it.el.style;
  s.setProperty('--dx', dx.toFixed(1) + 'px');
  s.setProperty('--fade', Math.max(0, 1 - Math.abs(dx) / (drag.w * 0.85)).toFixed(3));
});
const endDrag = (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  const { it, dx, v, w, moved } = drag;
  drag = null;
  it.el.classList.remove('is-drag');
  if (moved) {
    if (Math.abs(dx) > w * 0.32 || Math.abs(v) > 0.55) dismiss(it, (Math.abs(v) > 0.55 ? v : dx) < 0 ? 'left' : 'right');
    else { it.el.style.setProperty('--dx', '0px'); it.el.style.setProperty('--fade', 1); }
  }
  hover = !!(e.type === 'pointerup' && root.contains(document.elementFromPoint(e.clientX, e.clientY)) &&
    document.elementFromPoint(e.clientX, e.clientY).closest('.mnt-deck__toast'));
  setOpen();
};
list.addEventListener('pointerup', endDrag);
list.addEventListener('pointercancel', endDrag);

/* ---------- lifecycle ---------- */
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  if (onscreen) kick();
});
io.observe(root);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  layout();
});
ro.observe(region);

/* seed: one sticky failure, one pending request, one deploy in flight */
quiet = true;
syncs = 1;
push(timeout);
asker = 1;
request();
FIRE.deploy($('[data-fire="deploy"]'));
quiet = false;

