@property --mnt-centre-n {
  syntax: "<integer>";
  inherits: false;
  initial-value: 0;
}

/* Re-theme with --mnt-centre-paper, -panel, -ink and -accent. */
.mnt-centre {
  --mnt-centre-paper: oklch(0.955 0.012 75);
  --mnt-centre-panel: oklch(0.995 0.004 80);
  --mnt-centre-ink: oklch(0.25 0.02 48);
  --mnt-centre-accent: oklch(0.6 0.15 38);

  --mnt-centre-line: color-mix(in oklch, var(--mnt-centre-ink) 10%, transparent);
  --mnt-centre-muted: color-mix(in oklch, var(--mnt-centre-ink) 62%, var(--mnt-centre-panel));
  --mnt-centre-faint: color-mix(in oklch, var(--mnt-centre-ink) 42%, var(--mnt-centre-panel));
  --mnt-centre-hover: color-mix(in oklch, var(--mnt-centre-ink) 4.5%, transparent);
  --mnt-centre-tint: color-mix(in oklch, var(--mnt-centre-accent) 7%, var(--mnt-centre-panel));
  --mnt-centre-ring: color-mix(in oklch, var(--mnt-centre-accent) 70%, transparent);
  --mnt-centre-ease: cubic-bezier(.22, 1, .36, 1);
  --mnt-centre-spring: linear(0, 0.06 3%, 0.24 7%, 0.6 14%, 0.86 21%, 1.01 29%, 1.06 35%, 1.05 42%, 1.01 55%, 0.995 70%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  min-width: 0;
  width: 100%;
  height: 520px;
  border-radius: 16px;
  overflow: hidden;
  overflow: clip;
  color: var(--mnt-centre-ink);
  background: var(--mnt-centre-paper);
  box-shadow: 0 0 0 1px var(--mnt-centre-line);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mnt-centre { --mnt-centre-spring: cubic-bezier(.3, 1.4, .5, 1); }
}
:where(.mnt-centre) *, :where(.mnt-centre) *::before, :where(.mnt-centre) *::after { box-sizing: border-box; }
:where(.mnt-centre) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnt-centre) :focus-visible { outline: 2px solid var(--mnt-centre-ring); outline-offset: 2px; }
.mnt-centre svg { fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.mnt-centre kbd {
  display: inline-block; min-width: 17px; padding: 1px 4px; border-radius: 4px; text-align: center;
  font: 500 10px/1.5 ui-monospace, Menlo, monospace; color: var(--mnt-centre-muted);
  background: var(--mnt-centre-panel); box-shadow: inset 0 -1px 0 var(--mnt-centre-line), 0 0 0 1px var(--mnt-centre-line);
}

/* ---------- app chrome ---------- */
.mnt-centre__top {
