  color: oklch(0.45 0.11 150); background: oklch(0.95 0.04 150);
  transition: opacity .35s var(--mnt-centre-ease), translate .45s var(--mnt-centre-spring);
  & svg { width: 14px; height: 14px; stroke-width: 2.2; }
  &[data-tone="muted"] { color: var(--mnt-centre-muted); background: var(--mnt-centre-hover); }
}
@starting-style {
  .mnt-centre__done { opacity: 0; translate: 0 4px; }
}
.mnt-centre__dot {
  grid-area: dot; align-self: start; margin-top: 13px;
  width: 8px; height: 8px; border-radius: 50%; background: var(--mnt-centre-accent);
  scale: 0; opacity: 0;
  transition: scale .3s var(--mnt-centre-ease) calc(var(--k, 0) * 45ms), opacity .25s calc(var(--k, 0) * 45ms);
}
.mnt-centre__row[data-unread="true"] .mnt-centre__dot {
  scale: 1; opacity: 1;
  transition: scale .45s var(--mnt-centre-spring), opacity .2s;
}
.mnt-centre__tools {
  position: absolute; right: 7px; bottom: 6px;
  display: flex; gap: 2px; padding: 2px; border-radius: 9px;
  background: var(--mnt-centre-panel);
  box-shadow: 0 0 0 1px var(--mnt-centre-line), 0 4px 12px -6px color-mix(in oklch, var(--mnt-centre-ink) 30%, transparent);
  opacity: 0; translate: 0 3px; pointer-events: none;
  transition: opacity .18s, translate .25s var(--mnt-centre-ease);
  & button { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 7px; color: var(--mnt-centre-muted); }
  & button:hover { color: var(--mnt-centre-ink); background: var(--mnt-centre-hover); }
  & svg { width: 15px; height: 15px; }
}
.mnt-centre__row:is(:hover, :focus-within) .mnt-centre__tools { opacity: 1; translate: 0 0; pointer-events: auto; }
.mnt-centre__row[data-unread="true"] .mnt-centre__tools [data-do="read"] svg .mnt-centre__fill { fill: currentColor; }

.mnt-centre__feed.is-stagger .mnt-centre__row { animation: mnt-centre-in .5s var(--mnt-centre-ease) both; animation-delay: calc(var(--i, 0) * 38ms + 120ms); }
.mnt-centre__row.is-new { animation: mnt-centre-grow .55s var(--mnt-centre-ease) both; }
.mnt-centre__row.is-new .mnt-centre__in { animation: mnt-centre-flash 2.2s var(--mnt-centre-ease) both; }

.mnt-centre__skel {
  & .mnt-centre__in { cursor: default; }
  & i { display: block; border-radius: 6px; background: linear-gradient(90deg, var(--mnt-centre-hover) 30%, color-mix(in oklch, var(--mnt-centre-ink) 9%, transparent) 50%, var(--mnt-centre-hover) 70%) 0 0 / 300% 100%; animation: mnt-centre-shimmer 1.3s linear infinite; }
  & .mnt-centre__av { background: none; }
  & .mnt-centre__av i { width: 34px; height: 34px; border-radius: 50%; }
  & .mnt-centre__body i { height: 10px; margin: 4px 0 8px; }
  & .mnt-centre__body i + i { width: 55%; }
}

.mnt-centre__empty {
  display: grid; justify-items: center; gap: 4px; padding: 34px 28px 20px; text-align: center;
  transition: opacity .4s var(--mnt-centre-ease), translate .5s var(--mnt-centre-ease);
  &[hidden] { display: none; }
  & svg { width: 64px; height: 64px; margin-bottom: 8px; color: var(--mnt-centre-faint); stroke-width: 1.6; }
  & .mnt-centre__tick { color: var(--mnt-centre-accent); stroke: var(--mnt-centre-accent); stroke-width: 2.4; stroke-dasharray: 22; stroke-dashoffset: 22; animation: mnt-centre-draw .6s var(--mnt-centre-ease) .25s forwards; }
}
@starting-style {
  .mnt-centre__empty { opacity: 0; translate: 0 8px; }
}
.mnt-centre__et { margin: 0; font-size: 14px; font-weight: 650; text-wrap: balance; }
.mnt-centre__ed { margin: 0; max-width: 30ch; font-size: 12.5px; color: var(--mnt-centre-muted); text-wrap: pretty; }
.mnt-centre__showall {
  margin-top: 10px; padding: 6px 12px; border-radius: 8px; font-size: 12px; font-weight: 600;
  box-shadow: inset 0 0 0 1px var(--mnt-centre-line);
  &:hover { background: var(--mnt-centre-hover); }
  &[hidden] { display: none; }
}
.mnt-centre__more {
  display: grid; padding: 8px 12px 4px;
  & button {
    padding: 8px; border-radius: 9px; font-size: 12px; font-weight: 600; color: var(--mnt-centre-muted);
    transition: background-color .2s, color .2s;
  }
  & button:hover:not(:disabled) { color: var(--mnt-centre-ink); background: var(--mnt-centre-hover); }
  & button:disabled { cursor: default; color: var(--mnt-centre-faint); font-weight: 500; }
  & button[aria-busy="true"] { cursor: progress; }
}
.mnt-centre__foot {
  display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 9px 16px;
  border-top: 1px solid var(--mnt-centre-line);
  font-size: 11px; color: var(--mnt-centre-faint);
  & span { display: inline-flex; align-items: center; gap: 3px; }
}
.mnt-centre__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 400px) {
  .mnt-centre__all span { display: none; }
  .mnt-centre__all { padding: 6px; }
}
@container (max-width: 340px) {
  .mnt-centre__crumb { display: none; }
  .mnt-centre__top { grid-template-columns: minmax(0, 1fr) auto auto; }
  .mnt-centre__foot span:nth-child(n + 3) { display: none; }
  .mnt-centre__in { column-gap: 10px; padding: 10px; }
  .mnt-centre__tabs [role="tab"] { padding-inline: 6px; }
}

@keyframes mnt-centre-swing {
  0% { rotate: 0deg; } 15% { rotate: 16deg; } 30% { rotate: -13deg; } 45% { rotate: 9deg; }
  60% { rotate: -6deg; } 75% { rotate: 3deg; } 100% { rotate: 0deg; }
}
@keyframes mnt-centre-in { from { opacity: 0; translate: 0 10px; } }
@keyframes mnt-centre-grow { from { grid-template-rows: 0fr; opacity: 0; } }
@keyframes mnt-centre-flash { 0%, 30% { background-color: color-mix(in oklch, var(--mnt-centre-accent) 20%, var(--mnt-centre-panel)); } }
@keyframes mnt-centre-shimmer { to { background-position: -150% 0; } }
@keyframes mnt-centre-draw { to { stroke-dashoffset: 0; } }
@keyframes mnt-centre-lift {
  from { box-shadow: 0 0 0 transparent; }
  to { box-shadow: 0 8px 14px -12px color-mix(in oklch, var(--mnt-centre-ink) 45%, transparent); }
