@media (prefers-reduced-motion: reduce) {
  .mnt-centre__panel, .mnt-centre[data-open="false"] .mnt-centre__panel { transition: opacity .2s linear, visibility 0s; clip-path: none; }
  .mnt-centre[data-open="false"] .mnt-centre__panel { transition: opacity .2s linear, visibility 0s .2s; }
  .mnt-centre__feed.is-stagger .mnt-centre__row,
  .mnt-centre__row.is-new,
  .mnt-centre__row.is-new .mnt-centre__in,
  .mnt-centre__bell.is-ring svg { animation: none; }
  .mnt-centre__row, .mnt-centre__in, .mnt-centre__dot, .mnt-centre__row[data-unread="true"] .mnt-centre__dot,
  .mnt-centre__ink, .mnt-centre__badge, .mnt-centre__n, .mnt-centre__tools { transition-duration: .01s; transition-delay: 0s; }
  .mnt-centre__row.is-gone .mnt-centre__in { translate: 0 0; }
  .mnt-centre__skel i { animation: none; }
  .mnt-centre__empty .mnt-centre__tick { animation: none; stroke-dashoffset: 0; }
}

