const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = Math.random().toString(36).slice(2, 7);
const bell = $('.mnt-centre__bell'), panel = $('.mnt-centre__panel'), feed = $('.mnt-centre__feed');
const scroller = $('.mnt-centre__scroll'), empty = $('.mnt-centre__empty'), more = $('.mnt-centre__more button');
const only = $('.mnt-centre__only input'), live = $('.mnt-centre__sr'), ink = $('.mnt-centre__ink');
const badge = $('.mnt-centre__badge'), allBtn = $('.mnt-centre__all'), showAll = $('.mnt-centre__showall');
const tabs = $$('[role="tab"]');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const say = (t) => { live.textContent = ''; later(40, () => { live.textContent = t; }); };
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

panel.id = 'mnt-centre-' + UID + '-panel';
scroller.id = 'mnt-centre-' + UID + '-list';
bell.setAttribute('aria-controls', panel.id);
tabs.forEach((t) => { t.id = 'mnt-centre-' + UID + '-' + t.dataset.tab; t.setAttribute('aria-controls', scroller.id); });
scroller.setAttribute('aria-labelledby', tabs[0].id);

const PEOPLE = {
  pr: ['Priya Raman', 'PR', 22], tv: ['Tomás Varga', 'TV', 150], jp: ['Joon Park', 'JP', 255],
  mh: ['Mira Holt', 'MH', 330], io: ['Ines Okafor', 'IO', 70], da: ['Dev Anand', 'DA', 195],
};
const KIND = {
  mention: [38, '<circle cx="12" cy="12" r="3.6"/><path d="M15.6 12v1.4a2.6 2.6 0 0 0 5.2 0V12a8.8 8.8 0 1 0-3.5 7"/>'],
  access: [70, '<circle cx="8" cy="15" r="4.2"/><path d="m11 12 8.5-8.5M16.6 6.4l2.6 2.6M14 9l2.2 2.2"/>'],
  assign: [250, '<path d="M4 12h11M11 6.5l5.5 5.5-5.5 5.5"/><path d="M20 4.5v15"/>'],
  check: [150, '<path d="m5 12.5 4.5 4.5L19 7.5"/>'],
  reply: [38, '<path d="M9.5 14.5 4.5 9.5l5-5"/><path d="M4.5 9.5h9a6 6 0 0 1 6 6v4"/>'],
  react: [5, '<path d="M12 19.5s-7.5-4.4-7.5-9.6A4.1 4.1 0 0 1 12 7.6a4.1 4.1 0 0 1 7.5 2.3c0 5.2-7.5 9.6-7.5 9.6Z"/>'],
  share: [195, '<path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1"/><path d="M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/>'],
  billing: [60, '<rect x="3.5" y="6" width="17" height="12" rx="2"/><path d="M3.5 10h17M7 14.5h3"/>'],
};
const LOGO = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21v-8"/><path d="M12 13c-3.5 0-6-2.4-6-6 3.6 0 6 2.5 6 6Z"/><path d="M12 13c0-3.6 2.4-6 6-6 0 3.6-2.5 6-6 6Z"/></svg>';
const ICON_READ = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle class="mnt-centre__fill" cx="12" cy="12" r="4"/></svg>';
const ICON_ARCH = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="4.5" width="17" height="4.5" rx="1"/><path d="M5.5 9v9a1.5 1.5 0 0 0 1.5 1.5h10a1.5 1.5 0 0 0 1.5-1.5V9M10 13h4"/></svg>';
const ICON_OK = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>';

let items = [
  { id: 1, g: 'Today', who: 'pr', kind: 'mention', tab: 'mentions', unread: true, t: '4 min ago', place: 'Design',
    html: '<b>Priya Raman</b> mentioned you in <b>Q4 onboarding flow</b>', quote: 'Can we keep the empty-state copy from v2? It tested 18% better with trial users.' },
  { id: 2, g: 'Today', who: 'tv', kind: 'access', tab: 'assigned', unread: true, t: '22 min ago', place: 'Brand', acts: true,
    html: '<b>Tomás Varga</b> requested edit access to <b>Brand refresh</b>' },
  { id: 3, g: 'Today', who: 'jp', kind: 'assign', tab: 'assigned', unread: true, t: '1 h ago', place: 'Engineering',
    html: '<b>Joon Park</b> assigned you <b>LRK-482</b>', quote: 'Tab focus ring is clipped inside the side panel.' },
  { id: 4, g: 'Today', who: 'sys', kind: 'check', tab: 'all', unread: true, t: '2 h ago', place: 'Releases',
    html: 'Release <b>3.14</b> passed all <b>212</b> checks' },
  { id: 5, g: 'Yesterday', who: 'mh', kind: 'reply', tab: 'mentions', unread: true, t: '16:42', place: 'Marketing',
    html: '<b>Mira Holt</b> replied to your comment on <b>Pricing page v4</b>', quote: 'Agreed — dropping the annual toggle as the default.' },
  { id: 6, g: 'Yesterday', who: 'io', kind: 'react', tab: 'all', unread: false, t: '11:05', place: 'Design',
    html: '<b>Ines Okafor</b> and 2 others reacted to <b>Weekly crit notes</b>' },
  { id: 7, g: 'Yesterday', who: 'da', kind: 'share', tab: 'all', unread: true, t: '09:30', place: 'Design system',
    html: '<b>Dev Anand</b> shared <b>Icon grid 24px</b> with you' },
  { id: 8, g: 'Earlier this week', who: 'jp', kind: 'mention', tab: 'mentions', unread: false, t: 'Tue', place: 'Engineering',
    html: '<b>Joon Park</b> mentioned you in <b>Sprint 41 retro</b>', quote: 'Shout-out for landing the tokens migration two days early.' },
  { id: 9, g: 'Earlier this week', who: 'sys', kind: 'billing', tab: 'all', unread: false, t: 'Mon', place: 'Billing',
    html: 'Your <b>12 editor seats</b> renew on <b>Oct 9</b>' },
];
const OLDER = [
  { id: 10, g: 'Last week', who: 'mh', kind: 'assign', tab: 'assigned', unread: false, t: 'Sep 24', place: 'Marketing',
    html: '<b>Mira Holt</b> assigned you <b>LRK-455</b>', quote: 'Hero illustration exports at 2x are blurry.' },
  { id: 11, g: 'Last week', who: 'sys', kind: 'check', tab: 'all', unread: false, t: 'Sep 23', place: 'Releases',
    html: 'Release <b>3.13</b> passed all <b>209</b> checks' },
  { id: 12, g: 'Last week', who: 'pr', kind: 'mention', tab: 'mentions', unread: false, t: 'Sep 22', place: 'Research',
    html: '<b>Priya Raman</b> mentioned you in <b>Trial interviews synthesis</b>' },
];
const ARRIVALS = [
  { id: 13, g: 'Today', who: 'io', kind: 'mention', tab: 'mentions', unread: true, t: 'just now', place: 'Brand',
    html: '<b>Ines Okafor</b> mentioned you in <b>Brand refresh</b>', quote: 'Type scale v3 is ready for your pass — mostly the H3 and H4 steps.' },
  { id: 14, g: 'Today', who: 'da', kind: 'assign', tab: 'assigned', unread: true, t: 'just now', place: 'Engineering',
    html: '<b>Dev Anand</b> assigned you <b>LRK-490</b>', quote: 'Badge count overflows past 99 in the tab bar.' },
];
const EMPTY = {
  all: ["You're all caught up", 'New mentions, assignments and reviews land here.'],
  mentions: ['No mentions yet', 'When someone @mentions you in a file or comment, it shows up here.'],
  assigned: ['Nothing needs you', 'Issues and access requests assigned to you will appear here.'],
  unread: ['No unread notifications', 'Everything in this tab has been read.'],
};
const TAB_NAME = { all: 'All', mentions: 'Mentions', assigned: 'Assigned' };

let tab = 'all', unreadOnly = false, focusId = 0, currentId = 0, loading = false, loadedOlder = false, lastAll = -1;
let onscreen = true, arrivalIx = 0;

const visible = () => items.filter((it) => !it.gone && (tab === 'all' || it.tab === tab) && (!unreadOnly || it.unread));

const rowHTML = (it, i) => {
  const p = PEOPLE[it.who], k = KIND[it.kind];
  const av = it.who === 'sys'
    ? '<span class="mnt-centre__av" data-sys>' + LOGO
    : '<span class="mnt-centre__av" style="--h:' + p[2] + '">' + p[1];
  let acts = '';
  if (it.acts && !it.resolved) acts = '<div class="mnt-centre__acts"><button type="button" data-act="approve">Approve</button><button type="button" data-act="deny">Deny</button></div>';
  else if (it.resolved === 'approved') acts = '<p class="mnt-centre__done">' + ICON_OK + 'Approved · Tomás can edit</p>';
  else if (it.resolved === 'denied') acts = '<p class="mnt-centre__done" data-tone="muted">Denied · Tomás was notified</p>';
  return '<li class="mnt-centre__row' + (it.fresh ? ' is-new' : '') + '" data-id="' + it.id + '" data-unread="' + it.unread + '"' +
    (it.id === currentId ? ' aria-current="true"' : '') + ' tabindex="-1" style="--i:' + i + '">' +
    '<div class="mnt-centre__in">' + av + '<i class="mnt-centre__kind" style="--kh:' + k[0] + '"><svg viewBox="0 0 24 24" aria-hidden="true">' + k[1] + '</svg></i></span>' +
    '<div class="mnt-centre__body"><p class="mnt-centre__line">' + it.html + '</p>' +
    (it.quote ? '<p class="mnt-centre__quote">' + esc(it.quote) + '</p>' : '') + acts +
    '<p class="mnt-centre__meta"><time>' + it.t + '</time><span>' + it.place + '</span></p></div>' +
    '<span class="mnt-centre__dot" aria-hidden="true"></span>' +
    '<div class="mnt-centre__tools"><button type="button" data-do="read" aria-label="' + (it.unread ? 'Mark as read' : 'Mark as unread') + '">' + ICON_READ + '</button>' +
    '<button type="button" data-do="archive" aria-label="Archive">' + ICON_ARCH + '</button></div>' +
    '</div></li>';
};

const counts = () => {
  const u = items.filter((i) => !i.gone && i.unread);
  const n = { all: u.length, mentions: u.filter((i) => i.tab === 'mentions').length, assigned: u.filter((i) => i.tab === 'assigned').length };
  tabs.forEach((t) => {
    const c = t.querySelector('.mnt-centre__n'), v = n[t.dataset.tab];
    c.style.setProperty('--mnt-centre-n', v);
    c.toggleAttribute('data-zero', !v);
    t.setAttribute('aria-label', TAB_NAME[t.dataset.tab] + ', ' + v + ' unread');
  });
  badge.style.setProperty('--mnt-centre-n', n.all);
  badge.toggleAttribute('data-zero', !n.all);
  bell.setAttribute('aria-label', 'Notifications, ' + n.all + ' unread');
  allBtn.disabled = !n.all;
  if (lastAll > -1 && n.all > lastAll && !RM.matches) badge.animate([{ scale: 1 }, { scale: 1.35 }, { scale: 1 }], { duration: 420, easing: 'cubic-bezier(.3,1.6,.5,1)' });
  lastAll = n.all;
};

const syncEmpty = () => {
  const has = visible().length > 0;
  empty.hidden = has;
  if (!has) {
    const [t, d] = unreadOnly && items.some((i) => !i.gone && (tab === 'all' || i.tab === tab)) ? EMPTY.unread : EMPTY[tab];
    $('.mnt-centre__et').textContent = t;
    $('.mnt-centre__ed').textContent = d;
    showAll.hidden = !unreadOnly;
  }
};

const render = (stagger) => {
  const hadFocus = feed.contains(document.activeElement) ? +((document.activeElement.closest('.mnt-centre__row') || {}).dataset || {}).id : 0;
  const vis = visible(), groups = [];
  for (const it of vis) {
    let g = groups.find((x) => x.name === it.g);
    if (!g) groups.push(g = { name: it.g, rows: [] });
    g.rows.push(it);
  }
  let i = 0;
  feed.innerHTML = groups.map((g) => '<section class="mnt-centre__group" aria-label="' + g.name + '"><h4 class="mnt-centre__gh" aria-hidden="true">' + g.name + '</h4>' +
    '<ul class="mnt-centre__list" role="list">' + g.rows.map((it) => rowHTML(it, i++)).join('') + '</ul></section>').join('');
  vis.forEach((it) => { it.fresh = false; });
  feed.classList.toggle('is-stagger', !!stagger && !RM.matches);
  const rows = $$('.mnt-centre__row', feed);
  const keep = rows.find((r) => +r.dataset.id === focusId) || rows[0];
  if (keep) keep.tabIndex = 0;
  if (hadFocus) { const r = rows.find((x) => +x.dataset.id === hadFocus) || keep; if (r) r.focus({ preventScroll: true }); }
  syncEmpty();
  counts();
};

const moveInk = () => {
  const t = tabs.find((x) => x.getAttribute('aria-selected') === 'true');
  ink.style.setProperty('--x', t.offsetLeft + 8 + 'px');
  ink.style.setProperty('--w', ((t.offsetWidth - 16) / 100).toFixed(4));
};

/* A View Transition for the list; the snapshots are animated from JS so the
   direction can follow the tab order without any global ::view-transition CSS. */
const swap = (fn, dir) => {
  if (!document.startViewTransition || RM.matches) {
    fn();
    if (dir && !RM.matches) feed.animate([{ opacity: 0, transform: 'translateX(' + dir * 22 + 'px)' }, { opacity: 1, transform: 'none' }], { duration: 300, easing: 'cubic-bezier(.22,1,.36,1)' });
    return;
  }
  const name = 'mnt-centre-' + UID + '-list';
  scroller.style.viewTransitionName = name;
  let vt;
  try { vt = document.startViewTransition(fn); } catch (err) { scroller.style.viewTransitionName = ''; fn(); return; }
  vt.ready.then(() => {
    if (!dir) return;
    const de = document.documentElement;
    de.animate({ transform: ['translateX(' + dir * 26 + 'px)', 'none'], opacity: [0, 1] },
      { duration: 340, easing: 'cubic-bezier(.22,1,.36,1)', pseudoElement: '::view-transition-new(' + name + ')' });
    de.animate({ transform: ['none', 'translateX(' + -dir * 26 + 'px)'], opacity: [1, 0] },
      { duration: 200, easing: 'cubic-bezier(.4,0,1,1)', pseudoElement: '::view-transition-old(' + name + ')' });
  }).catch(() => {});
  vt.finished.finally(() => { scroller.style.viewTransitionName = ''; });
};

const selectTab = (t, focus) => {
  const from = tabs.findIndex((x) => x.getAttribute('aria-selected') === 'true'), to = tabs.indexOf(t);
  if (focus) t.focus();
  if (from === to) return;
  tabs.forEach((x) => { const on = x === t; x.setAttribute('aria-selected', on); x.tabIndex = on ? 0 : -1; });
  scroller.setAttribute('aria-labelledby', t.id);
  tab = t.dataset.tab;
  moveInk();
  swap(() => { render(false); scroller.scrollTop = 0; }, to > from ? 1 : -1);
};

const item = (id) => items.find((i) => i.id === +id);
const rowOf = (id) => feed.querySelector('.mnt-centre__row[data-id="' + id + '"]');

const setRead = (id, unread) => {
  const it = item(id), r = rowOf(id);
  if (!it || it.unread === unread) return;
  it.unread = unread;
  if (r) {
    r.style.removeProperty('--k');
    r.dataset.unread = unread;
    r.querySelector('[data-do="read"]').setAttribute('aria-label', unread ? 'Mark as read' : 'Mark as unread');
  }
  counts();
};

const open = (r) => {
  const prev = currentId && rowOf(currentId);
  if (prev) prev.removeAttribute('aria-current');
  currentId = +r.dataset.id;
  r.setAttribute('aria-current', 'true');
  setRead(currentId, false);
};

const archive = (id) => {
  const it = item(id), r = rowOf(id);
  if (!it || it.gone) return;
  it.gone = true;
  if (r) {
    const rows = $$('.mnt-centre__row:not(.is-gone)', feed), k = rows.indexOf(r);
    const next = rows[k + 1] || rows[k - 1];
    const had = r.contains(document.activeElement);
    r.classList.add('is-gone');
    if (next) { next.tabIndex = 0; focusId = +next.dataset.id; if (had) next.focus({ preventScroll: true }); }
    later(RM.matches ? 0 : 400, () => {
      const ul = r.parentElement;
      r.remove();
      if (ul && !ul.children.length) ul.closest('.mnt-centre__group').remove();
      syncEmpty();
      if (had && !next) (empty.hidden ? scroller : (showAll.hidden ? scroller : showAll)).focus();
    });
  }
  counts();
  say('Archived');
};

const markAll = () => {
  const wasOnAll = document.activeElement === allBtn;
  const rows = $$('.mnt-centre__row[data-unread="true"]', feed);
  rows.forEach((r, k) => { r.style.setProperty('--k', k); r.dataset.unread = 'false'; r.querySelector('[data-do="read"]').setAttribute('aria-label', 'Mark as unread'); });
  items.forEach((i) => { if (!i.gone) i.unread = false; });
  counts();
  say('All notifications marked as read');
  later(rows.length * 45 + 450, () => {
    rows.forEach((r) => r.style.removeProperty('--k'));
    if (unreadOnly) swap(() => render(false), 0);
  });
  if (wasOnAll) {
    const r = $('.mnt-centre__row[tabindex="0"]', feed) || tabs.find((t) => t.tabIndex === 0);
    if (r) r.focus({ preventScroll: true });
  }
};

const setOpen = (o, focusBell) => {
  root.dataset.open = o;
  bell.setAttribute('aria-expanded', o);
  panel.inert = !o;
  if (o) { render(true); moveInk(); }
  else if (focusBell) bell.focus();
};

const loadOlder = () => {
  if (loading || loadedOlder) return;
  loading = true;
  more.setAttribute('aria-busy', 'true');
  more.textContent = 'Loading…';
  const sk = document.createElement('section');
  sk.className = 'mnt-centre__group mnt-centre__skel';
  sk.setAttribute('aria-hidden', 'true');
  sk.innerHTML = '<h4 class="mnt-centre__gh">Last week</h4><ul class="mnt-centre__list">' +
    '<li class="mnt-centre__row"><div class="mnt-centre__in"><span class="mnt-centre__av"><i></i></span><div class="mnt-centre__body"><i></i><i></i></div></div></li>'.repeat(3) + '</ul>';
  feed.append(sk);
  empty.hidden = true;
  scroller.scrollTo({ top: scroller.scrollHeight, behavior: RM.matches ? 'auto' : 'smooth' });
  later(1100, () => {
    OLDER.forEach((o) => items.push(Object.assign({ fresh: true }, o)));
    loading = false;
    loadedOlder = true;
    more.removeAttribute('aria-busy');
    more.disabled = true;
    more.textContent = 'Nothing older in the last 30 days';
    render(false);
    say('Loaded 3 earlier notifications');
  });
};

/* live arrivals, held back while the component is off screen or the tab is hidden */
const arrive = () => {
  if (arrivalIx >= ARRIVALS.length) return;
  if (!onscreen || document.hidden || loading) { later(3000, arrive); return; }
  const it = Object.assign({ fresh: true }, ARRIVALS[arrivalIx++]);
  items.unshift(it);
  if (root.dataset.open === 'true') render(false); else counts();
  if (!RM.matches) { bell.classList.remove('is-ring'); void bell.offsetWidth; bell.classList.add('is-ring'); }
  say('New notification: ' + it.html.replace(/<[^>]+>/g, ''));
  later(16000, arrive);
};

/* ---------- events ---------- */
bell.addEventListener('click', () => setOpen(root.dataset.open !== 'true', false));
bell.addEventListener('animationend', () => bell.classList.remove('is-ring'), true);
allBtn.addEventListener('click', markAll);
more.addEventListener('click', loadOlder);
only.addEventListener('change', () => { unreadOnly = only.checked; swap(() => render(false), 0); });
showAll.addEventListener('click', () => { only.checked = false; unreadOnly = false; swap(() => render(false), 0); });

tabs.forEach((t) => t.addEventListener('click', () => selectTab(t, false)));
$('.mnt-centre__tabs').addEventListener('keydown', (e) => {
  const k = tabs.indexOf(e.target);
  if (k < 0) return;
  const to = { ArrowRight: k + 1, ArrowLeft: k - 1, Home: 0, End: tabs.length - 1 }[e.key];
  if (to === undefined) return;
  e.preventDefault();
  selectTab(tabs[(to + tabs.length) % tabs.length], true);
});

feed.addEventListener('click', (e) => {
  const r = e.target.closest('.mnt-centre__row');
  if (!r || !r.dataset.id) return;
  const id = +r.dataset.id;
  const act = e.target.closest('[data-act]'), tool = e.target.closest('[data-do]');
  if (act) {
    const it = item(id);
    it.resolved = act.dataset.act === 'approve' ? 'approved' : 'denied';
    const box = act.parentElement;
    box.outerHTML = it.resolved === 'approved'
      ? '<p class="mnt-centre__done">' + ICON_OK + 'Approved · Tomás can edit</p>'
      : '<p class="mnt-centre__done" data-tone="muted">Denied · Tomás was notified</p>';
    setRead(id, false);
    r.focus({ preventScroll: true });
    say(it.resolved === 'approved' ? 'Access approved' : 'Access denied');
    return;
  }
  if (tool) {
    if (tool.dataset.do === 'archive') archive(id);
    else setRead(id, !item(id).unread);
    return;
  }
  $$('.mnt-centre__row[tabindex="0"]', feed).forEach((x) => { x.tabIndex = -1; });
  r.tabIndex = 0;
  focusId = id;
  open(r);
});

feed.addEventListener('keydown', (e) => {
  const r = e.target.closest('.mnt-centre__row');
  if (!r || !r.dataset.id) return;
  const rows = $$('.mnt-centre__row:not(.is-gone)', feed), k = rows.indexOf(r);
  const go = (x) => {
    if (!x) return;
    rows.forEach((y) => { y.tabIndex = -1; });
    x.tabIndex = 0;
    focusId = +x.dataset.id;
    x.focus();
  };
  const onRow = e.target === r, key = e.key.length === 1 ? e.key.toLowerCase() : e.key;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (key === 'ArrowDown') { e.preventDefault(); go(rows[k + 1]); }
  else if (key === 'ArrowUp') { e.preventDefault(); go(rows[k - 1]); }
  else if (key === 'Home' && onRow) { e.preventDefault(); go(rows[0]); }
  else if (key === 'End' && onRow) { e.preventDefault(); go(rows[rows.length - 1]); }
  else if (key === 'Enter' && onRow) { e.preventDefault(); open(r); }
  else if (key === 'u' && onRow) { e.preventDefault(); setRead(+r.dataset.id, !item(r.dataset.id).unread); }
  else if ((key === 'e' || key === 'Delete') && onRow) { e.preventDefault(); archive(+r.dataset.id); }
});

root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && root.dataset.open === 'true') { e.preventDefault(); setOpen(false, true); }
});
root.addEventListener('click', (e) => {
  /* a target that was swapped out mid-click (Approve, Deny) is no longer in the panel: not an outside click */
  if (!e.target.isConnected) return;
  if (root.dataset.open === 'true' && !e.target.closest('.mnt-centre__panel, .mnt-centre__bell')) setOpen(false, false);
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
});
io.observe(root);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  moveInk();
});
ro.observe($('.mnt-centre__tabs'));

setOpen(true, false);
later(9000, arrive);

css:
/* Re-theme with --mnt-feed-bg, -ink, -accent (and -warn / -bad). */
.mnt-feed {
  --mnt-feed-bg: oklch(0.968 0.006 240);
  --mnt-feed-card: oklch(0.997 0.002 240);
  --mnt-feed-ink: oklch(0.24 0.022 255);
  --mnt-feed-accent: oklch(0.58 0.125 162);
  --mnt-feed-warn: oklch(0.7 0.14 68);
  --mnt-feed-bad: oklch(0.58 0.19 26);

  --mnt-feed-line: color-mix(in oklch, var(--mnt-feed-ink) 11%, transparent);
  --mnt-feed-muted: color-mix(in oklch, var(--mnt-feed-ink) 64%, var(--mnt-feed-card));
  --mnt-feed-faint: color-mix(in oklch, var(--mnt-feed-ink) 44%, var(--mnt-feed-card));
  --mnt-feed-hover: color-mix(in oklch, var(--mnt-feed-ink) 4%, var(--mnt-feed-card));
  --mnt-feed-ring: color-mix(in oklch, var(--mnt-feed-accent) 75%, transparent);
  --mnt-feed-ease: cubic-bezier(.22, 1, .36, 1);
  --mnt-feed-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  min-width: 0;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  width: 100%;
  height: 500px;
  border-radius: 16px;
  overflow: hidden;
  overflow: clip;
  color: var(--mnt-feed-ink);
  background: var(--mnt-feed-bg);
  box-shadow: 0 0 0 1px var(--mnt-feed-line);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mnt-feed { --mnt-feed-spring: cubic-bezier(.3, 1.3, .5, 1); }
}
:where(.mnt-feed) *, :where(.mnt-feed) *::before, :where(.mnt-feed) *::after { box-sizing: border-box; }
:where(.mnt-feed) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnt-feed) :focus-visible { outline: 2px solid var(--mnt-feed-ring); outline-offset: 2px; }
.mnt-feed svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mnt-feed__head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 12px;
  padding: 16px 16px 10px;
}
.mnt-feed__repo {
  display: flex; align-items: center; gap: 6px; margin: 0;
  font: 500 11.5px/1.3 ui-monospace, Menlo, monospace; color: var(--mnt-feed-faint);
  & b { color: var(--mnt-feed-muted); font-weight: 600; }
  & svg { width: 14px; height: 14px; }
}
.mnt-feed__h { margin: 3px 0 0; font-size: clamp(17px, 5.4cqi, 21px); font-weight: 720; letter-spacing: -.025em; line-height: 1.1; text-wrap: balance; }
.mnt-feed__live {
  display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px 5px 9px; border-radius: 99px;
  font-size: 11.5px; font-weight: 650; letter-spacing: .02em;
  color: color-mix(in oklch, var(--mnt-feed-accent) 80%, var(--mnt-feed-ink));
  background: color-mix(in oklch, var(--mnt-feed-accent) 13%, transparent);
  transition: background-color .25s, color .25s;
  & i { position: relative; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
  & i::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: currentColor; animation: mnt-feed-ping 1.8s cubic-bezier(0, 0, .2, 1) infinite; }
  &[aria-pressed="false"] { color: var(--mnt-feed-muted); background: color-mix(in oklch, var(--mnt-feed-ink) 7%, transparent); }
  &[aria-pressed="false"] i::after, &:disabled i::after { animation: none; opacity: 0; }
  &:disabled { cursor: default; color: var(--mnt-feed-faint); background: color-mix(in oklch, var(--mnt-feed-ink) 5%, transparent); }
}
.mnt-feed__tools {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 0 12px 10px 14px;
  border-bottom: 1px solid var(--mnt-feed-line);
}
.mnt-feed__chips {
  display: flex; gap: 2px; padding: 2px; border-radius: 10px; min-width: 0; overflow-x: auto; scrollbar-width: none;
  background: color-mix(in oklch, var(--mnt-feed-ink) 6%, transparent);
  & button {
    padding: 5px 9px; border-radius: 8px; font-size: 12px; font-weight: 560; white-space: nowrap; color: var(--mnt-feed-muted);
    transition: background-color .25s var(--mnt-feed-ease), color .2s, box-shadow .25s;
  }
  & button:hover { color: var(--mnt-feed-ink); }
  & button[aria-checked="true"] { color: var(--mnt-feed-ink); background: var(--mnt-feed-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--mnt-feed-ink) 14%, transparent), 0 0 0 1px var(--mnt-feed-line); }
}
.mnt-feed__switch {
  display: inline-flex; align-items: center; gap: 7px; flex: none; font-size: 12px; font-weight: 560; color: var(--mnt-feed-muted);
}
.mnt-feed__track {
  position: relative; width: 30px; height: 18px; border-radius: 9px;
  background: color-mix(in oklch, var(--mnt-feed-ink) 18%, transparent);
  transition: background-color .25s var(--mnt-feed-ease);
  & i {
    position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%;
    background: var(--mnt-feed-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--mnt-feed-ink) 30%, transparent);
    transition: translate .35s var(--mnt-feed-spring);
  }
}
.mnt-feed__switch[aria-checked="true"] .mnt-feed__track { background: var(--mnt-feed-accent); }
.mnt-feed__switch[aria-checked="true"] .mnt-feed__track i { translate: 12px 0; }

/* ---------- scroller + rail ---------- */
.mnt-feed__body { position: relative; min-height: 0; display: grid; }
.mnt-feed__scroll {
  min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--mnt-feed-ink) 18%, transparent) transparent;
  padding: 12px 12px 16px 10px;
  &:focus-visible { outline-offset: -2px; }
}
.mnt-feed__list {
  position: relative; list-style: none; margin: 0; padding: 0;
  display: grid; gap: 8px;
  &::before {
    content: ""; position: absolute; left: 14px; top: 14px; bottom: 14px; width: 1.5px; border-radius: 1px;
    background: linear-gradient(var(--mnt-feed-line), var(--mnt-feed-line) 85%, transparent);
  }
}
.mnt-feed__item {
  position: relative; z-index: 1;
  display: grid; grid-template-columns: 30px minmax(0, 1fr); column-gap: 8px; align-items: start;
}
@supports (animation-timeline: view()) {
  .mnt-feed__item {
    animation: mnt-feed-rise linear both;
    animation-timeline: view();
    animation-range: entry 0% entry 70%;
  }
}
.mnt-feed__node {
  --mnt-feed-tone: var(--mnt-feed-muted);
  position: relative; z-index: 1; display: grid; place-items: center;
  width: 30px; height: 30px; margin-top: 7px; border-radius: 50%;
  color: var(--mnt-feed-tone);
  background: var(--mnt-feed-card);
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--mnt-feed-tone) 35%, transparent), 0 0 0 4px var(--mnt-feed-bg);
  & svg { width: 15px; height: 15px; stroke-width: 2; }
  &[data-tone="ok"] { --mnt-feed-tone: var(--mnt-feed-accent); }
  &[data-tone="warn"] { --mnt-feed-tone: var(--mnt-feed-warn); }
  &[data-tone="bad"] { --mnt-feed-tone: var(--mnt-feed-bad); }
  &[data-tone="ink"] { --mnt-feed-tone: var(--mnt-feed-ink); }
}
.mnt-feed__count {
  position: absolute; right: -5px; top: -4px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px;
  display: grid; place-items: center;
  font: 700 9.5px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums;
  color: var(--mnt-feed-card); background: var(--mnt-feed-ink);
  box-shadow: 0 0 0 2px var(--mnt-feed-bg);
}
.mnt-feed__item.is-bump .mnt-feed__count { animation: mnt-feed-pop .5s var(--mnt-feed-spring); }

.mnt-feed__card {
  display: grid; grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "line side" "sub sub" "meta meta" "kids kids";
  column-gap: 10px;
  padding: 10px 12px; border-radius: 12px;
  background: var(--mnt-feed-card);
  box-shadow: 0 0 0 1px var(--mnt-feed-line), 0 1px 2px color-mix(in oklch, var(--mnt-feed-ink) 6%, transparent);
  transition: box-shadow .2s, background-color .2s;
  outline: none;
  &:focus-visible { box-shadow: 0 0 0 2px var(--mnt-feed-ring); }
}
.mnt-feed__item.is-ghost { position: absolute; left: 0; right: 0; z-index: 0; pointer-events: none; animation: none; filter: saturate(.6); }
.mnt-feed__item.is-group .mnt-feed__card { cursor: pointer; }
.mnt-feed__item.is-group .mnt-feed__card:hover { background: var(--mnt-feed-hover); }
.mnt-feed__item.is-new .mnt-feed__card { animation: mnt-feed-drop .6s var(--mnt-feed-ease) both, mnt-feed-glow 2.4s var(--mnt-feed-ease) both; }
.mnt-feed__item.is-new .mnt-feed__node { animation: mnt-feed-pop .5s var(--mnt-feed-spring) both; }
.mnt-feed__item.is-bump .mnt-feed__card { animation: mnt-feed-glow 2s var(--mnt-feed-ease) both; }

.mnt-feed__line {
  grid-area: line; min-width: 0; margin: 0; font-size: 13px; line-height: 1.4; color: var(--mnt-feed-muted); text-wrap: pretty;
  & b { color: var(--mnt-feed-ink); font-weight: 620; }
  & code { font: 600 11.5px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; border-radius: 4px; color: var(--mnt-feed-ink); background: color-mix(in oklch, var(--mnt-feed-ink) 7%, transparent); }
}
.mnt-feed__quote { grid-area: sub; margin: 4px 0 0; font-size: 12.5px; line-height: 1.45; color: var(--mnt-feed-ink); text-wrap: pretty; }
.mnt-feed__meta {
  grid-area: meta; min-width: 0;
  display: flex; align-items: center; gap: 6px; margin: 5px 0 0; white-space: nowrap;
  font-size: 11.5px; color: var(--mnt-feed-faint); font-variant-numeric: tabular-nums;
  & > span:last-of-type { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
  & .mnt-feed__chev { width: 15px; height: 15px; margin-left: auto; transition: rotate .35s var(--mnt-feed-spring); }
  & .mnt-feed__badge { padding: 1px 6px; border-radius: 5px; font-weight: 650; font-size: 10.5px; letter-spacing: .02em; }
  & .mnt-feed__badge[data-tone="ok"] { color: color-mix(in oklch, var(--mnt-feed-accent) 75%, var(--mnt-feed-ink)); background: color-mix(in oklch, var(--mnt-feed-accent) 14%, transparent); }
  & .mnt-feed__badge[data-tone="bad"] { color: var(--mnt-feed-bad); background: color-mix(in oklch, var(--mnt-feed-bad) 12%, transparent); }
  & .mnt-feed__badge[data-tone="warn"] { color: color-mix(in oklab, var(--mnt-feed-warn) 62%, var(--mnt-feed-ink)); background: color-mix(in oklch, var(--mnt-feed-warn) 16%, transparent); }
}
.mnt-feed__card[aria-expanded="true"] .mnt-feed__chev { rotate: 180deg; }

.mnt-feed__side { grid-area: side; display: flex; align-self: start; padding-top: 1px; }
.mnt-feed__av {
  position: relative; display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%;
  font-size: 9.5px; font-weight: 700; letter-spacing: .02em;
  color: oklch(0.36 0.09 var(--h, 200)); background: oklch(0.9 0.06 var(--h, 200));
  box-shadow: 0 0 0 2px var(--mnt-feed-card);
}
.mnt-feed__pile { display: flex; gap: 3px; }
.mnt-feed__pile .mnt-feed__av {
  z-index: calc(10 - var(--j, 0));
  translate: calc((var(--n, 1) - 1 - var(--j, 0)) * 15px) 0;
  transition: translate .5s var(--mnt-feed-spring);
}
.mnt-feed__card[aria-expanded="true"] + .mnt-feed__x,
.mnt-feed__card[aria-expanded="true"] .mnt-feed__pile .mnt-feed__av { translate: 0 0; transition-delay: calc((var(--n, 1) - 1 - var(--j, 0)) * 35ms); }
.mnt-feed__av.is-pop { animation: mnt-feed-pop .55s var(--mnt-feed-spring); }

.mnt-feed__kids {
  grid-area: kids; display: grid; grid-template-rows: 0fr;
  transition: grid-template-rows .45s var(--mnt-feed-ease);
  & > ol { min-height: 0; overflow: hidden; list-style: none; margin: 0; padding: 0; }
}
.mnt-feed__card[aria-expanded="true"] .mnt-feed__kids { grid-template-rows: 1fr; }
.mnt-feed__kid {
  display: grid; grid-template-columns: 24px minmax(0, 1fr) auto; column-gap: 9px; align-items: start;
  padding: 9px 0 1px; margin-top: 8px;
  border-top: 1px solid var(--mnt-feed-line);
  opacity: 0; translate: 0 -6px;
  transition: opacity .25s var(--mnt-feed-ease), translate .4s var(--mnt-feed-ease);
  & p { margin: 0; font-size: 12.5px; line-height: 1.4; color: var(--mnt-feed-ink); text-wrap: pretty; }
  & p b { font-weight: 620; }
  & p span { display: block; color: var(--mnt-feed-muted); }
  & time { font-size: 11px; color: var(--mnt-feed-faint); font-variant-numeric: tabular-nums; padding-top: 2px; }
}
.mnt-feed__card[aria-expanded="true"] .mnt-feed__kid {
  opacity: 1; translate: 0 0;
  transition-delay: calc(var(--j, 0) * 45ms + 80ms);
}

.mnt-feed__pill {
  position: absolute; z-index: 5; top: 10px; left: 50%; translate: -50% 0;
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px 6px 10px; border-radius: 99px;
  font-size: 12px; font-weight: 650; white-space: nowrap; font-variant-numeric: tabular-nums;
  color: var(--mnt-feed-card); background: var(--mnt-feed-ink);
  box-shadow: 0 8px 20px -8px color-mix(in oklch, var(--mnt-feed-ink) 60%, transparent);
  transition: opacity .3s var(--mnt-feed-ease), translate .45s var(--mnt-feed-spring);
  & svg { width: 14px; height: 14px; stroke-width: 2.2; }
  &[hidden] { display: none; }
}
@starting-style {
  .mnt-feed__pill { opacity: 0; translate: -50% -12px; }
}

.mnt-feed__skel {
  & .mnt-feed__card { box-shadow: 0 0 0 1px var(--mnt-feed-line); }
  & i { display: block; height: 10px; margin: 3px 0 9px; border-radius: 5px; background: linear-gradient(90deg, color-mix(in oklch, var(--mnt-feed-ink) 6%, transparent) 30%, color-mix(in oklch, var(--mnt-feed-ink) 11%, transparent) 50%, color-mix(in oklch, var(--mnt-feed-ink) 6%, transparent) 70%) 0 0 / 300% 100%; animation: mnt-feed-shimmer 1.2s linear infinite; }
  & i + i { width: 60%; margin-bottom: 2px; }
}
.mnt-feed__empty {
  display: grid; justify-items: center; gap: 4px; padding: 40px 24px; text-align: center;
  transition: opacity .4s var(--mnt-feed-ease), translate .5s var(--mnt-feed-ease);
  &[hidden] { display: none; }
  & svg { width: 44px; height: 44px; margin-bottom: 8px; color: var(--mnt-feed-faint); stroke-width: 1.5; }
  & button { margin-top: 10px; padding: 6px 12px; border-radius: 8px; font-size: 12px; font-weight: 600; background: var(--mnt-feed-card); box-shadow: 0 0 0 1px var(--mnt-feed-line); }
  & button:hover { background: var(--mnt-feed-hover); }
}
@starting-style {
  .mnt-feed__empty { opacity: 0; translate: 0 8px; }
}
.mnt-feed__et { margin: 0; font-size: 14px; font-weight: 650; text-wrap: balance; }
.mnt-feed__ed { margin: 0; max-width: 32ch; font-size: 12.5px; color: var(--mnt-feed-muted); text-wrap: pretty; }
.mnt-feed__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 330px) {
  .mnt-feed__switch { font-size: 0; gap: 0; }
  .mnt-feed__av { width: 21px; height: 21px; font-size: 8.5px; }
  .mnt-feed__pile { gap: 2px; }
  .mnt-feed__pile .mnt-feed__av { translate: calc((var(--n, 1) - 1 - var(--j, 0)) * 14px) 0; }
  .mnt-feed__card { padding: 10px; grid-template-areas: "line line" "sub sub" "meta side" "kids kids"; }
  .mnt-feed__side { align-self: center; padding-top: 4px; }
  .mnt-feed__chips button { padding-inline: 7px; }
}

@keyframes mnt-feed-ping { 0% { scale: 1; opacity: .7; } 80%, 100% { scale: 2.8; opacity: 0; } }
@keyframes mnt-feed-rise { from { opacity: 0; translate: 0 18px; } }
@keyframes mnt-feed-pop { 0% { scale: .4; } 60% { scale: 1.18; } 100% { scale: 1; } }
@keyframes mnt-feed-drop { from { opacity: 0; translate: 0 -10px; scale: .98; } }
@keyframes mnt-feed-glow {
  0%, 25% { box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--mnt-feed-accent) 60%, transparent), 0 6px 18px -8px color-mix(in oklch, var(--mnt-feed-accent) 55%, transparent); }
}
@keyframes mnt-feed-shimmer { to { background-position: -150% 0; } }

@media (prefers-reduced-motion: reduce) {
  .mnt-feed__item, .mnt-feed__item.is-new .mnt-feed__card, .mnt-feed__item.is-new .mnt-feed__node,
  .mnt-feed__item.is-bump .mnt-feed__card, .mnt-feed__item.is-bump .mnt-feed__count, .mnt-feed__av.is-pop { animation: none; }
  .mnt-feed__live i::after { animation: none; opacity: 0; }
  .mnt-feed__skel i { animation: none; }
  .mnt-feed__pile .mnt-feed__av, .mnt-feed__kid, .mnt-feed__kids, .mnt-feed__track i, .mnt-feed__meta .mnt-feed__chev { transition-duration: .01s; transition-delay: 0s; }
