const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = Math.random().toString(36).slice(2, 7);
const SPRING = CSS.supports('transition-timing-function', 'linear(0, 1)')
  ? 'linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1)'
  : 'cubic-bezier(.3,1.3,.5,1)';
const list = $('.mnt-feed__list'), scroller = $('.mnt-feed__scroll'), pill = $('.mnt-feed__pill');
const empty = $('.mnt-feed__empty'), liveBtn = $('.mnt-feed__live'), sw = $('.mnt-feed__switch'), sr = $('.mnt-feed__sr');
const chips = $$('[role="radio"]');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const say = (t) => { sr.textContent = ''; later(40, () => { sr.textContent = t; }); };
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const P = {
  ana: ['Ana Ruiz', 'AR', 28], leo: ['Leo Brandt', 'LB', 215], kofi: ['Kofi Mensah', 'KM', 145],
  mei: ['Mei Tanaka', 'MT', 330], sami: ['Sami Haddad', 'SH', 75],
};
const IC = {
  comment: '<path d="M5 5.5h14a1.5 1.5 0 0 1 1.5 1.5v8.5a1.5 1.5 0 0 1-1.5 1.5h-7l-4.5 3.5V17H5a1.5 1.5 0 0 1-1.5-1.5V7A1.5 1.5 0 0 1 5 5.5Z"/>',
  commit: '<circle cx="12" cy="12" r="3.5"/><path d="M3 12h5.5M15.5 12H21"/>',
  deploy: '<path d="M12 19V6"/><path d="m6.5 11.5 5.5-5.5 5.5 5.5"/><path d="M5 20h14"/>',
  fail: '<path d="m7 7 10 10M17 7 7 17"/>',
  approved: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  changes: '<path d="M12 5v14M5 12h14" transform="rotate(45 12 12)"/><circle cx="12" cy="12" r="8.5" stroke-dasharray="2 3"/>',
  issue: '<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="1.6" fill="currentColor"/>',
  chev: '<path d="m6 9 6 6 6-6"/>',
};
const svg = (k, cls) => '<svg viewBox="0 0 24 24"' + (cls ? ' class="' + cls + '"' : '') + ' aria-hidden="true">' + IC[k] + '</svg>';

const T0 = Date.now();
const ago = (m) => T0 - m * 60000;
let EVENTS = [
  { id: 'e1', type: 'comment', who: 'leo', target: '#418', title: 'Add idempotency keys to /charges', text: 'Nit: the TTL should come from config, not a constant.', at: ago(3) },
  { id: 'e2', type: 'comment', who: 'ana', target: '#418', title: 'Add idempotency keys to /charges', text: 'Pushed a fix for the retry path in a91f3c0.', at: ago(7) },
  { id: 'e3', type: 'comment', who: 'kofi', target: '#418', title: 'Add idempotency keys to /charges', text: 'LGTM once CI is green.', at: ago(11) },
  { id: 'e4', type: 'commit', who: 'ana', target: 'main', sha: 'a91f3c0', text: 'Retry idempotent writes on 409', at: ago(26) },
  { id: 'e5', type: 'commit', who: 'ana', target: 'main', sha: '5d02e7b', text: 'Store the key hash, not the raw key', at: ago(29) },
  { id: 'e6', type: 'commit', who: 'ana', target: 'main', sha: 'c7e19aa', text: 'Add idempotency_keys migration', at: ago(31) },
  { id: 'e7', type: 'review', who: 'mei', target: '#415', title: 'Rate-limit webhook retries', verdict: 'approved', at: ago(44) },
  { id: 'e8', type: 'review', who: 'kofi', target: '#415', title: 'Rate-limit webhook retries', verdict: 'changes', text: 'Cap the backoff at 10 minutes, not 60.', at: ago(52) },
  { id: 'e9', type: 'issue', who: 'sami', target: '#421', title: 'Ledger export drops cents for JPY', at: ago(63) },
];
const POOL = [
  { type: 'comment', who: 'mei', target: '#418', title: 'Add idempotency keys to /charges', text: 'Can we add a test for two concurrent retries?' },
  { type: 'deploy', who: 'ana', target: 'production', ver: 'v2.41.0', text: '12 services in 4 min 06 s', status: 'ok' },
  { type: 'commit', who: 'leo', target: 'fix/jpy-export', sha: 'e41b9d2', text: 'Use minor units from the currency table' },
  { type: 'commit', who: 'leo', target: 'fix/jpy-export', sha: '0c7a5f1', text: 'Add JPY and KRW fixtures' },
  { type: 'deploy', who: 'kofi', target: 'staging', ver: 'v2.42.0-rc.1', text: 'Health checks failed on 2 of 12 services', status: 'fail' },
  { type: 'review', who: 'ana', target: '#422', title: 'Fix minor-unit rounding in exports', verdict: 'approved' },
  { type: 'deploy', who: 'kofi', target: 'staging', ver: 'v2.42.0-rc.2', text: '12 services in 3 min 51 s', status: 'ok' },
];
const FILTER = { all: () => true, code: (e) => e.type === 'commit' || e.type === 'issue', review: (e) => e.type === 'review' || e.type === 'comment', deploy: (e) => e.type === 'deploy' };
const EMPTY = {
  code: ['No code activity', 'Commits and new issues on ledger-api will show up here.'],
  review: ['No reviews yet', 'Comments and review verdicts on open pull requests land here.'],
  deploy: ['No deploys yet today', 'Production last shipped v2.40.3 yesterday at 17:20.'],
  all: ['Nothing yet', 'Activity on ledger-api will appear here as it happens.'],
};

let filter = 'all', grouping = true, paused = false, onscreen = true, poolIx = 0, fresh = 0, focusKey = '', ready = false;
const expanded = new Set();
let seq = 100;

const when = (at) => {
  const m = Math.floor((Date.now() - at) / 60000);
  return m < 1 ? 'now' : m < 60 ? m + 'm' : Math.floor(m / 60) + 'h';
};
const same = (a, b) => a.type === b.type && a.target === b.target && (a.type !== 'commit' || a.who === b.who);
const names = (ws) => {
  const n = ws.map((w) => '<b>' + P[w][0] + '</b>');
  if (n.length === 1) return n[0];
  if (n.length === 2) return n[0] + ' and ' + n[1];
  if (n.length === 3) return n[0] + ', ' + n[1] + ' and ' + n[2];
  return n[0] + ', ' + n[1] + ' and ' + (n.length - 2) + ' others';
};
const uniq = (evs) => evs.map((e) => e.who).filter((w, i, a) => a.indexOf(w) === i);

const node = (e) => {
  if (e.type === 'deploy') return e.status === 'fail' ? ['bad', 'fail'] : ['ok', 'deploy'];
  if (e.type === 'review') return e.verdict === 'approved' ? ['ok', 'approved'] : ['warn', 'changes'];
  if (e.type === 'commit') return ['ink', 'commit'];
  if (e.type === 'issue') return ['ok', 'issue'];
  return ['', 'comment'];
};

const single = (e) => {
  const who = '<b>' + P[e.who][0] + '</b>';
  let line = '', sub = '', meta = '';
  if (e.type === 'comment') { line = who + ' commented on <b>' + e.target + '</b>'; sub = e.text; meta = e.title; }
  if (e.type === 'commit') { line = who + ' pushed <code>' + e.sha + '</code> to <b>' + e.target + '</b>'; sub = e.text; }
  if (e.type === 'deploy') { line = '<b>' + e.ver + '</b> → <b>' + e.target + '</b>'; sub = e.text; meta = '<span class="mnt-feed__badge" data-tone="' + (e.status === 'fail' ? 'bad' : 'ok') + '">' + (e.status === 'fail' ? 'Failed' : 'Live') + '</span> by ' + P[e.who][0]; }
  if (e.type === 'review') { line = who + (e.verdict === 'approved' ? ' approved ' : ' requested changes on ') + '<b>' + e.target + '</b>'; sub = e.text || e.title; meta = e.text ? e.title : ''; }
  if (e.type === 'issue') { line = who + ' opened <b>' + e.target + '</b>'; sub = e.title; }
  return { line, sub, meta };
};

const summary = (evs) => {
  const e = evs[0], n = evs.length, ws = uniq(evs);
  if (e.type === 'comment') return { line: names(ws) + ' commented on <b>' + e.target + '</b>', meta: n + ' comments · ' + e.title };
  if (e.type === 'commit') return { line: '<b>' + P[e.who][0] + '</b> pushed ' + n + ' commits to <b>' + e.target + '</b>', meta: evs.map((x) => x.sha).slice(0, 2).join(', ') + (n > 2 ? ' +' + (n - 2) : '') };
  if (e.type === 'review') {
    const ok = evs.filter((x) => x.verdict === 'approved').length;
    return { line: names(ws) + ' reviewed <b>' + e.target + '</b>', meta: ok + ' approved · ' + (n - ok) + (n - ok === 1 ? ' change requested' : ' changes requested') };
  }
  if (e.type === 'deploy') {
    const bad = evs.filter((x) => x.status === 'fail').length;
    return { line: n + ' deploys to <b>' + e.target + '</b>', meta: (n - bad) + ' live · ' + bad + ' failed' };
  }
  return { line: n + ' issues opened', meta: '' };
};

const rowsFor = () => {
  const rows = [];
  for (const e of EVENTS.filter(FILTER[filter])) {
    const prev = rows[rows.length - 1];
    if (grouping && prev && same(prev.evs[0], e)) prev.evs.push(e);
    else rows.push({ evs: [e] });
  }
  rows.forEach((r) => { r.key = r.evs[r.evs.length - 1].id; });
  return rows;
};

const rowHTML = (r, i) => {
  const e = r.evs[0], [tone, icon] = node(e), n = r.evs.length;
  const ids = ' data-ids="' + r.evs.map((x) => x.id).join(' ') + '"';
  if (n === 1) {
    const s = single(e);
    return '<li class="mnt-feed__item is-single" data-key="' + r.key + '"' + ids + ' style="--i:' + i + '">' +
      '<span class="mnt-feed__node" data-tone="' + tone + '">' + svg(icon) + '</span>' +
      '<div class="mnt-feed__card" tabindex="-1"><p class="mnt-feed__line">' + s.line + '</p>' +
      '<span class="mnt-feed__side"><span class="mnt-feed__av" style="--h:' + P[e.who][2] + '" title="' + P[e.who][0] + '">' + P[e.who][1] + '</span></span>' +
      (s.sub ? '<p class="mnt-feed__quote">' + esc(s.sub) + '</p>' : '') +
      '<p class="mnt-feed__meta"><time data-at="' + e.at + '">' + when(e.at) + '</time>' + (s.meta ? '<span>·</span><span>' + s.meta + '</span>' : '') + '</p></div></li>';
  }
  const s = summary(r.evs), ws = uniq(r.evs).slice(0, 4), open = expanded.has(r.key);
  const kid = 'mnt-feed-' + UID + '-k-' + r.key;
  const kids = r.evs.map((x, j) => {
    const body = x.type === 'commit' ? '<code>' + x.sha + '</code> ' + esc(x.text)
      : x.type === 'deploy' ? x.ver + ' · ' + esc(x.text)
      : x.type === 'review' ? (x.verdict === 'approved' ? 'Approved' : 'Requested changes') + (x.text ? ' — ' + esc(x.text) : '')
      : esc(x.text || x.title);
    return '<li class="mnt-feed__kid" style="--j:' + j + '"><span class="mnt-feed__av" style="--h:' + P[x.who][2] + '">' + P[x.who][1] + '</span>' +
      '<p><b>' + P[x.who][0] + '</b><span>' + body + '</span></p><time data-at="' + x.at + '">' + when(x.at) + '</time></li>';
  }).join('');
  return '<li class="mnt-feed__item is-group" data-key="' + r.key + '" data-n="' + n + '"' + ids + ' style="--i:' + i + '">' +
    '<span class="mnt-feed__node" data-tone="' + tone + '">' + svg(icon) + '<b class="mnt-feed__count">' + n + '</b></span>' +
    '<div class="mnt-feed__card" role="button" tabindex="-1" aria-expanded="' + open + '" aria-controls="' + kid + '">' +
    '<p class="mnt-feed__line">' + s.line + '</p>' +
    '<span class="mnt-feed__side"><span class="mnt-feed__pile" style="--n:' + ws.length + '">' +
    ws.map((w, j) => '<span class="mnt-feed__av" data-who="' + w + '" style="--h:' + P[w][2] + ';--j:' + j + '" title="' + P[w][0] + '">' + P[w][1] + '</span>').join('') + '</span></span>' +
    '<p class="mnt-feed__meta"><time data-at="' + e.at + '">' + when(e.at) + '</time><span>·</span><span>' + s.meta + '</span>' + svg('chev', 'mnt-feed__chev') + '</p>' +
    '<div class="mnt-feed__kids" id="' + kid + '"><ol>' + kids + '</ol></div></div></li>';
};

const render = () => {
  const had = list.contains(document.activeElement);
  const rows = rowsFor();
  list.innerHTML = rows.map(rowHTML).join('');
  const cards = $$('.mnt-feed__card', list);
  const keep = cards.find((c) => c.parentElement.dataset.key === focusKey) || cards[0];
  if (keep) { keep.tabIndex = 0; focusKey = keep.parentElement.dataset.key; if (had) keep.focus({ preventScroll: true }); }
  empty.hidden = rows.length > 0;
  if (!rows.length) {
    const [t, d] = EMPTY[filter];
    $('.mnt-feed__et').textContent = t;
    $('.mnt-feed__ed').textContent = d;
    $('.mnt-feed__reset').hidden = filter === 'all';
  }
  return rows;
};

/* Keyed FLIP across re-renders. Every row carries the ids of the events it holds, so a row
   can be matched to whichever old row held its newest event: grouping folds rows into their
   group (old rows leave as ghosts that slide into it), ungrouping spills them back out, and a
   live event either drops in or bumps the group it merged into. Everything stays inside the
   component's own scroller, so nothing escapes its clipping mid-animation. */
const snap = () => $$('.mnt-feed__item', list).filter((li) => li.dataset.ids)
  .map((li) => ({ li, top: li.getBoundingClientRect().top, ids: li.dataset.ids.split(' ') }));

const flip = (change, live) => {
  const before = snap(), oldOf = new Map();
  before.forEach((o) => o.ids.forEach((id) => oldOf.set(id, o)));
  const sTop = scroller.getBoundingClientRect().top;
  const anchor = live && scroller.scrollTop >= 8 ? before.find((o) => o.top - sTop >= -4) : null;
  change();
  if (anchor) {
    const li = list.querySelector('[data-key="' + anchor.li.dataset.key + '"]');
    if (li) scroller.scrollTop += li.getBoundingClientRect().top - sTop - (anchor.top - sTop);
    return 'held';
  }
  if (RM.matches) return 'moved';
  const after = snap(), newOf = new Map();
  after.forEach((n) => n.ids.forEach((id) => newOf.set(id, n)));
  after.forEach((n) => {
    const o = oldOf.get(n.ids[0]) || n.ids.map((id) => oldOf.get(id)).find(Boolean);
    if (!o) {
      if (live) n.li.classList.add('is-new');
      else n.li.animate([{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.22,1,.36,1)' });
      return;
    }
    const dy = o.top - n.top, lead = o.ids[0] === n.ids[0] || live;
    if (live && n.ids.length > o.ids.length) {
      n.li.classList.add('is-bump');
      const av = n.li.querySelector('.mnt-feed__pile [data-who="' + live.who + '"]');
      if (av) av.classList.add('is-pop');
    }
    if (Math.abs(dy) < 0.5 && lead) return;
    n.li.animate([{ transform: 'translateY(' + dy + 'px)', opacity: lead ? 1 : 0 }, { transform: 'none', opacity: 1 }],
      { duration: lead ? 560 : 480, easing: lead ? SPRING : 'cubic-bezier(.22,1,.36,1)' });
  });
  if (!live) {
    const lTop = list.getBoundingClientRect().top;
    before.forEach((o) => {
      if (after.some((n) => n.ids[0] === o.ids[0])) return;
      const target = newOf.get(o.ids[0]);
      const g = o.li.cloneNode(true);
      g.classList.add('is-ghost');
      g.removeAttribute('data-ids');
      g.setAttribute('aria-hidden', 'true');
      g.style.top = (o.top - lTop) + 'px';
      list.append(g);
      const dy = target ? target.top - o.top : 0;
      g.animate([{ transform: 'none', opacity: 1 }, { opacity: 0.35, offset: 0.4 }, { transform: 'translateY(' + dy + 'px) scale(.94)', opacity: 0 }],
        { duration: target ? 440 : 260, easing: 'cubic-bezier(.45,0,.2,1)', fill: 'forwards' }).finished.then(() => g.remove(), () => g.remove());
    });
  }
  return 'moved';
};

const add = (ev) => {
  EVENTS.unshift(ev);
  if (!FILTER[filter](ev)) return;
  if (flip(render, ev) === 'held') {
    fresh++;
    pill.querySelector('span').textContent = fresh + (fresh === 1 ? ' new event' : ' new events');
    pill.hidden = false;
  }
};

const stream = () => {
  if (poolIx >= POOL.length) {
    liveBtn.disabled = true;
    liveBtn.setAttribute('aria-pressed', 'false');
    liveBtn.querySelector('span').textContent = 'Caught up';
    return;
  }
  if (paused || !onscreen || document.hidden || !ready) { later(1200, stream); return; }
  const ev = Object.assign({ id: 'e' + (++seq), at: Date.now() }, POOL[poolIx++]);
  add(ev);
  const s = ev.type === 'commit' ? P[ev.who][0] + ' pushed ' + ev.sha : ev.type === 'deploy' ? ev.ver + ' to ' + ev.target + (ev.status === 'fail' ? ' failed' : ' is live') : P[ev.who][0] + ' on ' + ev.target;
  say('New activity: ' + s);
  later(5200, stream);
};

const toggle = (card, force) => {
  const li = card.parentElement;
  if (!li.classList.contains('is-group')) return;
  const open = force === undefined ? card.getAttribute('aria-expanded') !== 'true' : force;
  card.setAttribute('aria-expanded', open);
  if (open) expanded.add(li.dataset.key); else expanded.delete(li.dataset.key);
};

/* ---------- events ---------- */
list.addEventListener('click', (e) => {
  const card = e.target.closest('.mnt-feed__card');
  if (!card) return;
  $$('.mnt-feed__card[tabindex="0"]', list).forEach((c) => { c.tabIndex = -1; });
  card.tabIndex = 0;
  focusKey = card.parentElement.dataset.key;
  toggle(card);
});
list.addEventListener('keydown', (e) => {
  const card = e.target.closest('.mnt-feed__card');
  if (!card || e.target !== card) return;
  const cards = $$('.mnt-feed__card', list), k = cards.indexOf(card);
  const go = (c) => { if (!c) return; cards.forEach((x) => { x.tabIndex = -1; }); c.tabIndex = 0; focusKey = c.parentElement.dataset.key; c.focus(); };
  switch (e.key) {
    case 'ArrowDown': e.preventDefault(); go(cards[k + 1]); break;
    case 'ArrowUp': e.preventDefault(); go(cards[k - 1]); break;
    case 'Home': e.preventDefault(); go(cards[0]); break;
    case 'End': e.preventDefault(); go(cards[cards.length - 1]); break;
    case 'ArrowRight': e.preventDefault(); toggle(card, true); break;
    case 'ArrowLeft': e.preventDefault(); toggle(card, false); break;
    case 'Enter': case ' ': e.preventDefault(); toggle(card); break;
  }
});

const pick = (c, focus) => {
  if (c.getAttribute('aria-checked') === 'true') { if (focus) c.focus(); return; }
  chips.forEach((x) => { const on = x === c; x.setAttribute('aria-checked', on); x.tabIndex = on ? 0 : -1; });
  if (focus) c.focus();
  filter = c.dataset.f;
  scroller.scrollTop = 0;
  flip(render, null);
  pill.hidden = true; fresh = 0;
};
chips.forEach((c) => c.addEventListener('click', () => pick(c, false)));
$('.mnt-feed__chips').addEventListener('keydown', (e) => {
  const k = chips.indexOf(e.target);
  if (k < 0) return;
  const to = { ArrowRight: k + 1, ArrowDown: k + 1, ArrowLeft: k - 1, ArrowUp: k - 1, Home: 0, End: chips.length - 1 }[e.key];
  if (to === undefined) return;
  e.preventDefault();
  pick(chips[(to + chips.length) % chips.length], true);
});
$('.mnt-feed__reset').addEventListener('click', () => pick(chips[0], true));

sw.addEventListener('click', () => {
  grouping = !grouping;
  sw.setAttribute('aria-checked', grouping);
  flip(render, null);
  say(grouping ? 'Similar events grouped' : 'Showing every event');
});
liveBtn.addEventListener('click', () => {
  paused = !paused;
  liveBtn.setAttribute('aria-pressed', !paused);
  liveBtn.querySelector('span').textContent = paused ? 'Paused' : 'Live';
});
pill.addEventListener('click', () => {
  scroller.scrollTo({ top: 0, behavior: RM.matches ? 'auto' : 'smooth' });
  pill.hidden = true; fresh = 0;
  const c = $('.mnt-feed__card', list);
  if (c) { $$('.mnt-feed__card[tabindex="0"]', list).forEach((x) => { x.tabIndex = -1; }); c.tabIndex = 0; focusKey = c.parentElement.dataset.key; c.focus({ preventScroll: true }); }
});
scroller.addEventListener('scroll', () => {
  if (scroller.scrollTop < 8 && !pill.hidden) { pill.hidden = true; fresh = 0; }
}, { passive: true });

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
});
io.observe(root);
const tick = setInterval(() => {
  if (!root.isConnected) { clearInterval(tick); return; }
  if (!onscreen || document.hidden) return;
  $$('time[data-at]', list).forEach((t) => { t.textContent = when(+t.dataset.at); });
}, 20000);

/* loading state first, then the real rows on a stagger */
list.innerHTML = '<li class="mnt-feed__item mnt-feed__skel"><span class="mnt-feed__node"></span><div class="mnt-feed__card"><p class="mnt-feed__line"><i></i><i></i></p></div></li>'.repeat(4);
list.setAttribute('aria-busy', 'true');
later(650, () => {
  list.removeAttribute('aria-busy');
  render();
  if (!RM.matches) $$('.mnt-feed__item', list).forEach((li, i) => li.animate([{ opacity: 0, transform: 'translateY(10px)' }, { opacity: 1, transform: 'none' }], { duration: 480, delay: i * 55, easing: 'cubic-bezier(.22,1,.36,1)', fill: 'backwards' }));
  ready = true;
  later(4200, stream);
});

css:
@property --mnt-status-tone {
  syntax: "<color>";
  inherits: true;
  initial-value: oklch(0.6 0.19 27);
}
@property --mnt-status-p {
  syntax: "<percentage>";
  inherits: true;
  initial-value: 0%;
}

/* Re-theme with --mnt-status-paper, -ink, -ok and the stage tones -s0..-s2. Tone tints mix in oklab so
   a warm severity never swings through an unrelated hue on its way to a neutral surface. */
.mnt-status {
  --mnt-status-paper: oklch(0.985 0.003 250);
  --mnt-status-ink: oklch(0.23 0.016 255);
  --mnt-status-ok: oklch(0.6 0.14 152);
  --mnt-status-s0: oklch(0.6 0.19 27);
  --mnt-status-s1: oklch(0.69 0.15 62);
  --mnt-status-s2: oklch(0.57 0.15 252);
  --mnt-status-tone: var(--mnt-status-s0);
  --mnt-status-p: 0%;

  --mnt-status-line: color-mix(in oklch, var(--mnt-status-ink) 10%, transparent);
  --mnt-status-muted: color-mix(in oklch, var(--mnt-status-ink) 62%, var(--mnt-status-paper));
  --mnt-status-faint: color-mix(in oklch, var(--mnt-status-ink) 42%, var(--mnt-status-paper));
  --mnt-status-soft: color-mix(in oklab, var(--mnt-status-tone) 10%, var(--mnt-status-paper));
  --mnt-status-edge: color-mix(in oklab, var(--mnt-status-tone) 30%, transparent);
  --mnt-status-deep: color-mix(in oklab, var(--mnt-status-tone) 66%, var(--mnt-status-ink));
  --mnt-status-ease: cubic-bezier(.22, 1, .36, 1);
  --mnt-status-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  min-width: 0;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  width: 100%;
  height: 470px;
  border-radius: 16px;
  overflow: hidden;
  overflow: clip;
  color: var(--mnt-status-ink);
  background: var(--mnt-status-paper);
  box-shadow: 0 0 0 1px var(--mnt-status-line);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  transition: --mnt-status-tone 1.3s var(--mnt-status-ease), --mnt-status-p 1.3s var(--mnt-status-ease);
}
.mnt-status[data-stage="1"] { --mnt-status-tone: var(--mnt-status-s1); --mnt-status-p: 33.333%; }
.mnt-status[data-stage="2"] { --mnt-status-tone: var(--mnt-status-s2); --mnt-status-p: 66.667%; }
.mnt-status[data-stage="3"] { --mnt-status-tone: var(--mnt-status-ok); --mnt-status-p: 100%; }
@supports not (transition-timing-function: linear(0, 1)) {
  .mnt-status { --mnt-status-spring: cubic-bezier(.3, 1.3, .5, 1); }
}
:where(.mnt-status) *, :where(.mnt-status) *::before, :where(.mnt-status) *::after { box-sizing: border-box; }
:where(.mnt-status) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnt-status) :focus-visible { outline: 2px solid var(--mnt-status-deep); outline-offset: 2px; }
.mnt-status svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

/* ---------- app chrome ---------- */
.mnt-status__top {
  display: flex; align-items: center; gap: 14px; height: 50px; padding: 0 12px 0 16px;
  border-bottom: 1px solid var(--mnt-status-line);
}
.mnt-status__logo {
  display: inline-flex; align-items: center; gap: 7px; font-weight: 700; letter-spacing: -.01em;
  & svg { width: 20px; height: 20px; color: oklch(0.5 0.1 220); }
}
.mnt-status__nav {
  display: flex; gap: 12px; font-size: 12.5px; color: var(--mnt-status-faint); white-space: nowrap; overflow: hidden;
  & b { color: var(--mnt-status-ink); font-weight: 600; }
}
.mnt-status__chip {
  margin-left: auto; display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px 5px 8px; border-radius: 99px;
  font-size: 11.5px; font-weight: 650; white-space: nowrap;
  color: var(--mnt-status-deep); background: var(--mnt-status-soft); box-shadow: inset 0 0 0 1px var(--mnt-status-edge);
  transition: opacity .35s var(--mnt-status-ease), scale .45s var(--mnt-status-spring);
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--mnt-status-tone); box-shadow: 0 0 0 3px color-mix(in oklab, var(--mnt-status-tone) 22%, transparent); }
  &[hidden] { display: none; }
}
@starting-style {
  .mnt-status__chip { opacity: 0; scale: .8; }
}

/* ---------- banner ---------- */
.mnt-status__slot {
  display: grid; grid-template-rows: 1fr;
  transition: grid-template-rows .55s var(--mnt-status-ease), opacity .4s var(--mnt-status-ease);
}
.mnt-status[data-banner="off"] .mnt-status__slot { grid-template-rows: 0fr; opacity: 0; }
.mnt-status__banner {
  position: relative; min-height: 0; overflow: hidden;
  margin: 12px 12px 0; border-radius: 14px;
  color: var(--mnt-status-ink);
  background: linear-gradient(180deg, color-mix(in oklab, var(--mnt-status-tone) 13%, var(--mnt-status-paper)), var(--mnt-status-soft));
  box-shadow: inset 0 0 0 1px var(--mnt-status-edge), 0 10px 24px -18px var(--mnt-status-tone);
}
.mnt-status[data-banner="off"] .mnt-status__banner { margin-top: 0; }
.mnt-status__row {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center; column-gap: 10px;
  grid-template-areas: "beacon stage more x" "beacon title title title";
  padding: 10px 8px 12px 12px;
}
.mnt-status__beacon { grid-area: beacon; align-self: start; margin-top: 4px; }
.mnt-status__stage { grid-area: stage; }
.mnt-status__title { grid-area: title; }
.mnt-status__more { grid-area: more; }
.mnt-status__x { grid-area: x; }
.mnt-status__beacon {
  position: relative; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%;
  background: color-mix(in oklab, var(--mnt-status-tone) 16%, transparent);
  & i { width: 10px; height: 10px; border-radius: 50%; background: var(--mnt-status-tone); transition: scale .4s var(--mnt-status-ease); }
  &::before, &::after {
    content: ""; position: absolute; inset: 10px; border-radius: 50%;
    border: 1.5px solid var(--mnt-status-tone);
    animation: mnt-status-ping 2s cubic-bezier(0, 0, .2, 1) infinite;
  }
  &::after { animation-delay: 1s; }
  & svg { position: absolute; width: 16px; height: 16px; stroke-width: 2.4; color: var(--mnt-status-tone); stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .5s var(--mnt-status-ease) .2s; }
}
.mnt-status[data-stage="2"] .mnt-status__beacon::before,
.mnt-status[data-stage="2"] .mnt-status__beacon::after { animation-duration: 3.2s; }
.mnt-status[data-stage="2"] .mnt-status__beacon::after { animation-delay: 1.6s; }
.mnt-status[data-stage="3"] .mnt-status__beacon {
  &::before, &::after { animation: none; opacity: 0; }
  & i { scale: 0; }
  & svg { stroke-dashoffset: 0; }
}
.mnt-status__stage {
  display: flex; align-items: baseline; gap: 6px; margin: 0;
  font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase;
  color: var(--mnt-status-deep);
  & .mnt-status__sname { display: inline-block; }
  & .mnt-status__stime { display: inline-block; font: 500 11px/1 ui-monospace, Menlo, monospace; letter-spacing: 0; text-transform: none; color: var(--mnt-status-faint); font-variant-numeric: tabular-nums; }
}
.mnt-status__title { margin: 0; padding-right: 6px; font-size: 13.5px; font-weight: 620; line-height: 1.35; letter-spacing: -.005em; text-wrap: balance; }
.mnt-status__more {
  display: inline-flex; align-items: center; gap: 4px; padding: 6px 8px 6px 10px; border-radius: 8px;
  font-size: 12px; font-weight: 620; color: var(--mnt-status-deep);
  transition: background-color .2s;
  & svg { width: 15px; height: 15px; transition: rotate .4s var(--mnt-status-spring); }
  &:hover { background: color-mix(in oklab, var(--mnt-status-tone) 12%, transparent); }
  &[aria-expanded="true"] svg { rotate: 180deg; }
}
.mnt-status__x {
  display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--mnt-status-muted);
  transition: background-color .2s, color .2s;
  & svg { width: 15px; height: 15px; }
  &:hover { color: var(--mnt-status-ink); background: color-mix(in oklch, var(--mnt-status-ink) 7%, transparent); }
}
.mnt-status__sheen {
  position: absolute; inset: 0; pointer-events: none; overflow: hidden; border-radius: inherit;
  &::before {
    content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 40%;
    background: linear-gradient(100deg, transparent, color-mix(in oklch, var(--mnt-status-paper) 55%, transparent), transparent);
    translate: -110% 0;
    animation: mnt-status-sheen 4.8s var(--mnt-status-ease) infinite;
  }
}
.mnt-status[data-stage="3"] .mnt-status__sheen::before,
.mnt-status[data-offscreen] .mnt-status__sheen::before { animation-play-state: paused; }
.mnt-status[data-offscreen] .mnt-status__beacon::before,
.mnt-status[data-offscreen] .mnt-status__beacon::after { animation-play-state: paused; }

.mnt-status__drawer {
  display: grid; grid-template-rows: 0fr;
  transition: grid-template-rows .5s var(--mnt-status-ease);
}
.mnt-status__banner:has(.mnt-status__more[aria-expanded="true"]) .mnt-status__drawer { grid-template-rows: 1fr; }
.mnt-status__inner {
  min-height: 0; overflow: hidden;
  & > * { margin-inline: 12px; }
}
.mnt-status__banner:has(.mnt-status__more[aria-expanded="true"]) .mnt-status__inner {
  overflow-y: auto; max-height: 268px; scrollbar-width: thin; overscroll-behavior: contain;
}

/* stage track */
.mnt-status__steps {
  position: relative; list-style: none; padding: 4px 0 0; margin-top: 0; margin-bottom: 0;
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  &::before, &::after {
    content: ""; position: absolute; top: 10px; left: 12.5%; right: 12.5%; height: 2px; border-radius: 2px;
  }
  &::before { background: color-mix(in oklch, var(--mnt-status-ink) 12%, transparent); }
  &::after { background: linear-gradient(90deg, var(--mnt-status-tone) var(--mnt-status-p), transparent var(--mnt-status-p)); }
  & li { position: relative; z-index: 1; display: grid; justify-items: center; gap: 2px; text-align: center; }
  & li i {
    width: 14px; height: 14px; border-radius: 50%; margin-bottom: 4px;
    background: var(--mnt-status-paper); box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--mnt-status-ink) 18%, transparent);
    transition: background-color .5s, box-shadow .5s, scale .45s var(--mnt-status-spring);
  }
  & li[data-s="done"] i { background: var(--mnt-status-tone); box-shadow: 0 0 0 3px var(--mnt-status-soft); }
  & li[data-s="now"] i { background: var(--mnt-status-paper); box-shadow: inset 0 0 0 4px var(--mnt-status-tone), 0 0 0 4px color-mix(in oklab, var(--mnt-status-tone) 18%, transparent); scale: 1.12; }
  & b { font-size: 11px; font-weight: 650; color: var(--mnt-status-faint); }
  & li:is([data-s="done"], [data-s="now"]) b { color: var(--mnt-status-ink); }
  & time { font: 500 10.5px/1.2 ui-monospace, Menlo, monospace; color: var(--mnt-status-faint); font-variant-numeric: tabular-nums; }
}

/* chart */
.mnt-status__chart { margin-top: 12px; margin-bottom: 0; }
.mnt-status__chart figcaption {
  display: flex; justify-content: space-between; align-items: baseline; gap: 8px;
  font-size: 11px; color: var(--mnt-status-muted);
  & b { font: 650 11.5px/1 ui-monospace, Menlo, monospace; color: var(--mnt-status-deep); font-variant-numeric: tabular-nums; }
}
.mnt-status__plot {
  position: relative; height: 96px; margin-top: 6px; container-type: inline-size;
  & svg { display: block; width: 100%; height: 96px; overflow: visible; }
}
.mnt-status__grid { stroke: color-mix(in oklch, var(--mnt-status-ink) 9%, transparent); stroke-width: 1; stroke-dasharray: 2 4; vector-effect: non-scaling-stroke; }
.mnt-status__series {
  clip-path: inset(-4px calc(100% - var(--mnt-status-reveal, 0%)) -4px 0);
  transition: clip-path 1.3s var(--mnt-status-ease);
}
.mnt-status__line { stroke: var(--mnt-status-tone); stroke-width: 2; vector-effect: non-scaling-stroke; }
.mnt-status__area { fill: color-mix(in oklab, var(--mnt-status-tone) 16%, transparent); stroke: none; }
.mnt-status__now {
  position: absolute; left: 0; top: 0; width: 9px; height: 9px; border-radius: 50%;
  background: var(--mnt-status-tone); box-shadow: 0 0 0 3px var(--mnt-status-paper), 0 0 0 5px color-mix(in oklab, var(--mnt-status-tone) 30%, transparent);
  translate: calc(var(--x, 0) * 100cqi - 4.5px) calc(var(--y, 88) * 1px - 4.5px);
  transition: translate 1.3s var(--mnt-status-ease);
}
.mnt-status__axis {
  display: flex; justify-content: space-between; margin: 4px 0 0;
  font: 500 10px/1 ui-monospace, Menlo, monospace; color: var(--mnt-status-faint); font-variant-numeric: tabular-nums;
}

/* update log */
.mnt-status__log {
  list-style: none; padding: 0; margin-top: 12px; margin-bottom: 0;
  & li {
    position: relative; padding: 0 0 10px 14px;
    transition: opacity .5s var(--mnt-status-ease), translate .6s var(--mnt-status-ease);
  }
  & li::before { content: ""; position: absolute; left: 0; top: 6px; width: 6px; height: 6px; border-radius: 50%; background: color-mix(in oklch, var(--mnt-status-ink) 25%, transparent); }
  & li:first-child::before { background: var(--mnt-status-tone); box-shadow: 0 0 0 3px color-mix(in oklab, var(--mnt-status-tone) 20%, transparent); }
  & li + li { color: var(--mnt-status-muted); }
  & p { margin: 0; font-size: 12.5px; line-height: 1.45; text-wrap: pretty; }
  & .mnt-status__when { font-size: 11px; font-weight: 650; color: var(--mnt-status-ink); margin-bottom: 1px; }
  & .mnt-status__when time { font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: var(--mnt-status-faint); margin-left: 4px; }
}
@starting-style {
  .mnt-status__log li { opacity: 0; translate: 0 -6px; }
}
.mnt-status__foot {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  margin-top: 2px; padding: 10px 0 12px; border-top: 1px solid var(--mnt-status-edge);
}
.mnt-status__sub {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px 6px 9px; border-radius: 8px;
  font-size: 12px; font-weight: 640; color: var(--mnt-status-paper); background: var(--mnt-status-ink);
  transition: background-color .25s, color .25s, scale .25s var(--mnt-status-spring);
  & svg { width: 15px; height: 15px; }
  & .mnt-status__ok { stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .4s var(--mnt-status-ease) .1s; }
  & .mnt-status__bell { transition: opacity .2s; }
  &:active { scale: .96; }
  &[aria-pressed="true"] { color: var(--mnt-status-deep); background: color-mix(in oklab, var(--mnt-status-tone) 14%, transparent); }
  &[aria-pressed="true"] .mnt-status__bell { opacity: 0; }
  &[aria-pressed="true"] .mnt-status__ok { stroke-dashoffset: 0; }
}
.mnt-status__dur { font-size: 11.5px; color: var(--mnt-status-muted); font-variant-numeric: tabular-nums; text-align: right; }

/* ---------- page ---------- */
.mnt-status__page { min-height: 0; overflow-y: auto; padding: 14px 12px 12px; scrollbar-width: thin; }
.mnt-status__ph { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 0 4px 8px; }
.mnt-status__h { margin: 0; font-size: 14px; font-weight: 700; letter-spacing: -.01em; }
.mnt-status__overall {
  display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 620; color: var(--mnt-status-deep);
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--mnt-status-tone); }
}
.mnt-status[data-calm] .mnt-status__overall { color: color-mix(in oklab, var(--mnt-status-ok) 70%, var(--mnt-status-ink)); }
.mnt-status[data-calm] .mnt-status__overall i { background: var(--mnt-status-ok); }
.mnt-status__svc {
  list-style: none; margin: 0; padding: 0; border-radius: 12px; overflow: hidden;
  box-shadow: 0 0 0 1px var(--mnt-status-line);
  & li { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 10px 12px; background: oklch(1 0 0 / .6); }
  & li + li { border-top: 1px solid var(--mnt-status-line); }
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--mnt-status-ok); transition: background-color .4s; }
  & li[data-hit] i { background: var(--mnt-status-tone); box-shadow: 0 0 0 3px color-mix(in oklab, var(--mnt-status-tone) 18%, transparent); }
  & p { margin: 0; font-size: 12.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & p span { font-weight: 400; color: var(--mnt-status-faint); }
  & em { font-style: normal; font-size: 11.5px; color: var(--mnt-status-muted); white-space: nowrap; }
  & li[data-hit] em { color: var(--mnt-status-deep); font-weight: 620; }
}
.mnt-status__up {
  margin-top: 14px; padding: 0 4px;
  & p { display: flex; justify-content: space-between; gap: 8px; margin: 0; font-size: 11.5px; color: var(--mnt-status-muted); }
  & b { font-weight: 650; color: var(--mnt-status-ink); font-variant-numeric: tabular-nums; }
  & .mnt-status__upaxis { margin-top: 5px; font-size: 10px; color: var(--mnt-status-faint); }
}
.mnt-status__bars {
  display: grid; grid-template-columns: repeat(30, minmax(0, 1fr)); gap: 2px; height: 26px; margin: 7px 0 0; padding: 0; list-style: none;
  & li { border-radius: 2px; background: color-mix(in oklab, var(--mnt-status-ok) 75%, var(--mnt-status-paper)); transform-origin: bottom; }
  & li[data-k="minor"] { background: oklch(0.78 0.13 75); }
  & li[data-k="today"] { background: var(--mnt-status-tone); }
}
.mnt-status__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 340px) {
  .mnt-status__nav { display: none; }
  .mnt-status__more span { display: none; }
  .mnt-status__more { padding: 6px; }
  .mnt-status__steps b { font-size: 10px; }
  .mnt-status__steps time { display: none; }
}

@keyframes mnt-status-ping { 0% { scale: 1; opacity: .8; } 100% { scale: 2.6; opacity: 0; } }
@keyframes mnt-status-sheen { 0%, 55% { translate: -110% 0; } 100% { translate: 260% 0; } }

@media (prefers-reduced-motion: reduce) {
  .mnt-status { transition: --mnt-status-tone .2s linear, --mnt-status-p .2s linear; }
  .mnt-status__beacon::before, .mnt-status__beacon::after { animation: none; opacity: 0; }
  .mnt-status__beacon i { box-shadow: 0 0 0 4px color-mix(in oklab, var(--mnt-status-tone) 25%, transparent); }
  .mnt-status__sheen::before { animation: none; opacity: 0; }
  .mnt-status__slot, .mnt-status__drawer, .mnt-status__series, .mnt-status__now, .mnt-status__more svg, .mnt-status__log li { transition-duration: .01s; }
  @starting-style {
    .mnt-status__log li { opacity: 1; translate: 0 0; }
  }
}

js:
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = Math.random().toString(36).slice(2, 7);
const banner = $('.mnt-status__banner'), more = $('.mnt-status__more'), chip = $('.mnt-status__chip');
const drawer = $('.mnt-status__drawer'), sub = $('.mnt-status__sub'), sr = $('.mnt-status__sr');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const say = (t) => { sr.textContent = ''; later(40, () => { sr.textContent = t; }); };
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const STAGES = ['Investigating', 'Identified', 'Monitoring', 'Resolved'];
const rep = (v, n) => Array(n).fill(v);
const INCIDENTS = [
  {
    title: 'Elevated error rates on the Payments API in eu-west-2',
    metric: 'Payments API error rate', unit: '%', max: 5, t0: '13:55', t1: '14:40', start: 13 * 60 + 55,
    series: [...rep(0.02, 5), 0.6, 2.4, 4.1, 4.2, 4.3, 4.2, 4.3, 4.1, 4.2, 4.0, 4.1, 3.9, 3.6, 2.8, 1.9, 1.2, 0.8, 0.6, 0.5, 0.4, 0.35, 0.3, 0.14, ...rep(0.02, 18)],
    updates: [
      ['14:02', 'We’re seeing 5xx responses on 4.1% of Payments API requests in eu-west-2. Card authorisations may fail; client retries succeed.'],
      ['14:09', 'This morning’s config push lowered a connection-pool limit on the ledger write path. Rolling it back now.'],
      ['14:21', 'Rollback complete. Errors are down to 0.3% and falling while queued retries drain.'],
      ['14:38', 'Error rate has held at the 0.02% baseline for 15 minutes. 1,284 failed authorisations were retried automatically.'],
    ],
    took: '36 min', minor: 16,
    services: [['Payments API', 'eu-west-2', 1, '99.91%'], ['Ledger writes', 'eu-west-2', 1, '99.94%'], ['Webhooks', 'all regions', 0, '99.99%'], ['Dashboard', 'global', 0, '100%']],
    hit: ['Partial outage', 'Partial outage', 'Recovering', 'Operational'],
  },
  {
    title: 'Webhook deliveries delayed in us-east-1',
    metric: 'p95 delivery delay', unit: ' min', max: 7, t0: '09:35', t1: '10:05', start: 9 * 60 + 35,
    series: [...rep(0.03, 4), 0.8, 2.6, 3.9, 4.6, 5.2, 5.6, 5.9, 6.1, 6.0, 6.1, 6.0, 5.4, 4.5, 3.6, 2.8, 2.1, 1.6, 1.2, 0.8, 0.5, 0.25, 0.08, ...rep(0.03, 5)],
    updates: [
      ['09:41', 'Webhook deliveries in us-east-1 are arriving up to 4 minutes late. No events have been lost.'],
      ['09:48', 'A queue consumer group stalled after a node replacement. Restarting it now.'],
      ['09:55', 'Consumers are healthy and draining the backlog: 18,400 events left, about 6 minutes at the current rate.'],
      ['10:03', 'Backlog cleared at 10:01. Median delivery delay is back under 2 seconds.'],
    ],
    took: '22 min', minor: 8,
    services: [['Webhooks', 'us-east-1', 1, '99.97%'], ['Event queue', 'us-east-1', 1, '99.98%'], ['Payments API', 'all regions', 0, '99.99%'], ['Dashboard', 'global', 0, '100%']],
    hit: ['Degraded', 'Degraded', 'Recovering', 'Operational'],
  },
];
const HOLD = [7000, 7000, 7000, 7500, 5000];

let ix = 0, stage = 0, phase = 0, acc = 0, hidden = false, onscreen = true;

const toMin = (hhmm) => { const [h, m] = hhmm.split(':').map(Number); return h * 60 + m; };
const fmt = (v, inc) => (inc.unit === '%' ? (v < 0.1 ? v.toFixed(2) : v.toFixed(1)) + '%' : (v < 0.1 ? Math.round(v * 60) + ' s' : v.toFixed(1) + ' min'));

const ids = (k) => 'mnt-status-' + UID + '-' + k;
$('.mnt-status__title').id = ids('title');
banner.setAttribute('aria-labelledby', ids('title'));
drawer.id = ids('drawer');
more.setAttribute('aria-controls', drawer.id);

const draw = (inc) => {
  const n = inc.series.length;
  const pts = inc.series.map((v, i) => [(i / (n - 1)) * 320, 88 - (v / inc.max) * 80]);
  const d = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('');
  $('.mnt-status__line').setAttribute('d', d);
  $('.mnt-status__area').setAttribute('d', d + 'L320 96L0 96Z');
  $('.mnt-status__metric').textContent = inc.metric;
  $('.mnt-status__t0').textContent = inc.t0;
  $('.mnt-status__t1').textContent = inc.t1;
  $('.mnt-status__max').textContent = 'max ' + inc.max + (inc.unit === '%' ? '%' : ' min');
  $('.mnt-status__title').textContent = inc.title;
  $('.mnt-status__steps').innerHTML = STAGES.map((s, i) => '<li data-s="todo"><i></i><b>' + s + '</b><time>' + inc.updates[i][0] + '</time></li>').join('');
  $('.mnt-status__log').innerHTML = '';
  const hit = inc.services.find((x) => x[2]);
  $('.mnt-status__upname').textContent = hit[0] + ' · ' + hit[1];
  $('.mnt-status__uppct').textContent = hit[3] + ' uptime, 30 days';
  $('.mnt-status__bars').innerHTML = Array.from({ length: 30 }, (_, i) => '<li' + (i === 29 ? ' data-k="today"' : i === inc.minor ? ' data-k="minor"' : '') + '></li>').join('');
  $('.mnt-status__svc').innerHTML = inc.services.map((s) => '<li' + (s[2] ? ' data-hit' : '') + '><i aria-hidden="true"></i><p>' + s[0] + ' <span>· ' + s[1] + '</span></p><em>' + (s[2] ? '' : 'Operational') + '</em></li>').join('');
};

const swapText = (el, text) => {
  if (el.textContent === text) return;
  el.textContent = text;
  if (!RM.matches) el.animate([{ opacity: 0, filter: 'blur(4px)', transform: 'translateY(4px)' }, { opacity: 1, filter: 'blur(0)', transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.22,1,.36,1)' });
};

const apply = (announce) => {
  const inc = INCIDENTS[ix], [time, text] = inc.updates[stage];
  root.dataset.stage = stage;
  swapText($('.mnt-status__sname'), STAGES[stage]);
  swapText($('.mnt-status__stime'), time);
  $$('.mnt-status__steps li').forEach((li, i) => { li.dataset.s = i < stage ? 'done' : i === stage ? (stage === 3 ? 'done' : 'now') : 'todo'; });
  const k = toMin(time) - inc.start, n = inc.series.length, v = inc.series[Math.min(n - 1, k)];
  const x = k / (n - 1);
  root.style.setProperty('--mnt-status-reveal', (x * 100).toFixed(2) + '%');
  const now = $('.mnt-status__now');
  now.style.setProperty('--x', x.toFixed(4));
  now.style.setProperty('--y', (88 - (v / inc.max) * 80).toFixed(1));
  $('.mnt-status__reading').textContent = fmt(v, inc) + ' at ' + time;
  const log = $('.mnt-status__log');
  const li = document.createElement('li');
  li.innerHTML = '<p class="mnt-status__when">' + STAGES[stage] + '<time>' + time + '</time></p><p>' + esc(text) + '</p>';
  log.prepend(li);
  $('.mnt-status__dur').textContent = stage === 3 ? 'Resolved in ' + inc.took : 'Updated at ' + time;
  $$('.mnt-status__svc li[data-hit] em').forEach((em) => { em.textContent = inc.hit[stage]; });
  $$('.mnt-status__svc li[data-hit]').forEach((r) => r.toggleAttribute('data-hit', stage < 3));
  root.toggleAttribute('data-calm', stage === 3);
  $('.mnt-status__overall span').textContent = stage === 3 ? 'All systems operational' : stage === 2 ? 'Recovering' : inc.hit[0];
  chip.querySelector('span').textContent = stage === 3 ? 'Incident resolved' : '1 active incident';
  if (announce) say('Incident update, ' + STAGES[stage] + ' at ' + time + '. ' + text);
};

const showBanner = (on) => {
  root.dataset.banner = on ? 'on' : 'off';
  banner.inert = !on;
  chip.hidden = on || phase === 4;
};

const startIncident = (announce) => {
  const inc = INCIDENTS[ix];
  stage = 0;
  root.style.setProperty('--mnt-status-reveal', '0%');
  draw(inc);
  apply(announce);
  if (!hidden) showBanner(true); else chip.hidden = false;
};

/* the incident feed: advances only while the component is visible and the tab is in front */
const advance = () => {
  if (phase < 3) { phase++; stage = phase; apply(true); return; }
  if (phase === 3) {
    phase = 4;
    showBanner(false);
    chip.hidden = true;
    root.toggleAttribute('data-calm', true);
    $('.mnt-status__overall span').textContent = 'All systems operational';
    return;
  }
  phase = 0;
  hidden = false;
  ix = (ix + 1) % INCIDENTS.length;
  more.setAttribute('aria-expanded', 'false');
  root.dataset.stage = 0;
  startIncident(true);
};
const iv = setInterval(() => {
  if (!root.isConnected) { clearInterval(iv); return; }
  if (!onscreen || document.hidden) return;
  acc += 250;
  if (acc >= HOLD[phase]) { acc = 0; advance(); }
}, 250);

more.addEventListener('click', () => {
  const open = more.getAttribute('aria-expanded') !== 'true';
  more.setAttribute('aria-expanded', open);
});
$('.mnt-status__x').addEventListener('click', () => {
  hidden = true;
  showBanner(false);
  chip.focus();
  say('Incident banner hidden. Use the incident button in the header to show it again.');
});
chip.addEventListener('click', () => {
  hidden = false;
  showBanner(true);
  more.focus();
});
sub.addEventListener('click', () => {
  const on = sub.getAttribute('aria-pressed') !== 'true';
  sub.setAttribute('aria-pressed', on);
  sub.querySelector('span').textContent = on ? 'Subscribed' : 'Get updates';
  say(on ? 'You will get an email for each update on this incident' : 'Unsubscribed from incident updates');
});
banner.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    e.preventDefault();
    if (more.getAttribute('aria-expanded') === 'true') { more.setAttribute('aria-expanded', 'false'); more.focus(); }
    else $('.mnt-status__x').click();
  }
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  root.toggleAttribute('data-offscreen', !onscreen);
});
io.observe(root);

startIncident(false);

css:
/* Re-theme with --mnt-island-bg, -pill, -fg and -accent (plus -ok / -rec). */
.mnt-island {
  --mnt-island-bg: oklch(0.205 0.012 55);
  --mnt-island-pill: oklch(0.11 0.003 60);
  --mnt-island-fg: oklch(0.96 0.006 80);
  --mnt-island-accent: oklch(0.83 0.14 78);
  --mnt-island-ok: oklch(0.8 0.16 150);
  --mnt-island-rec: oklch(0.66 0.21 27);

  --mnt-island-dim: color-mix(in oklch, var(--mnt-island-fg) 58%, var(--mnt-island-pill));
  --mnt-island-faint: color-mix(in oklch, var(--mnt-island-fg) 34%, var(--mnt-island-pill));
  --mnt-island-line: color-mix(in oklch, var(--mnt-island-fg) 11%, transparent);
  --mnt-island-raise: color-mix(in oklch, var(--mnt-island-fg) 9%, var(--mnt-island-pill));
  --mnt-island-ease: cubic-bezier(.22, 1, .36, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  min-width: 0;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  width: 100%;
  height: 340px;
  border-radius: 18px;
  overflow: hidden;
  overflow: clip;
  color: var(--mnt-island-fg);
  background:
    radial-gradient(90% 60% at 50% -10%, color-mix(in oklch, var(--mnt-island-accent) 10%, transparent), transparent 70%),
    var(--mnt-island-bg);
  box-shadow: inset 0 0 0 1px var(--mnt-island-line);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
:where(.mnt-island) *, :where(.mnt-island) *::before, :where(.mnt-island) *::after { box-sizing: border-box; }
:where(.mnt-island) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnt-island) :focus-visible { outline: 2px solid var(--mnt-island-accent); outline-offset: 2px; }
.mnt-island svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mnt-island__stage { position: relative; min-height: 0; }

/* ---------- the editor behind ---------- */
.mnt-island__editor {
  position: absolute; left: 14px; right: 14px; top: 62px; bottom: 10px;
  display: grid; grid-template-rows: minmax(0, 1fr) auto; gap: 8px;
  opacity: .9;
}
.mnt-island__viewer {
  position: relative; overflow: hidden; border-radius: 10px;
  background: linear-gradient(180deg, oklch(0.42 0.06 250) 0%, oklch(0.62 0.1 50) 58%, oklch(0.3 0.05 220) 58.5%, oklch(0.2 0.04 230) 100%);
  & .mnt-island__sun { position: absolute; left: 62%; top: 34%; width: 38px; height: 38px; border-radius: 50%; background: radial-gradient(circle, oklch(0.92 0.1 85), oklch(0.8 0.15 55) 60%, transparent 72%); }
  & .mnt-island__sea { position: absolute; left: 0; right: 0; top: 58.5%; bottom: 0; background: repeating-linear-gradient(180deg, transparent 0 5px, oklch(0.75 0.12 60 / .18) 5px 6px); }
  & span { position: absolute; right: 8px; bottom: 6px; font: 500 10px/1 ui-monospace, Menlo, monospace; color: oklch(0.95 0 0 / .8); font-variant-numeric: tabular-nums; }
}
.mnt-island__tracks {
  display: grid; gap: 4px;
  & p { position: relative; height: 13px; margin: 0; border-radius: 4px; background: color-mix(in oklch, var(--mnt-island-fg) 5%, transparent); }
  & i { position: absolute; top: 0; bottom: 0; left: calc(var(--a) * 1%); width: calc((var(--b) - var(--a)) * 1% - 2px); border-radius: 3px; background: oklch(0.55 0.08 var(--h)); }
}
.mnt-island__head { position: absolute; left: 46%; top: 0; bottom: 0; width: 1.5px; background: var(--mnt-island-accent); opacity: .8; }

/* ---------- the shape and its layers ---------- */
.mnt-island__shape { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; z-index: 2; }
.mnt-island__pill, .mnt-island__bub { fill: var(--mnt-island-pill); stroke: color-mix(in oklch, var(--mnt-island-fg) 9%, transparent); stroke-width: 1; }
.mnt-island__compact, .mnt-island__full, .mnt-island__bubble { position: absolute; left: 0; top: 0; z-index: 3; }
.mnt-island__compact {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px;
  height: 36px; padding: 0 14px 0 8px; border-radius: 18px;
  white-space: nowrap;
  &:focus-visible { outline-offset: 3px; }
}
.mnt-island__lead { position: relative; display: grid; place-items: center; width: 22px; height: 22px; }
.mnt-island__lead > * { grid-area: 1 / 1; transition: opacity .25s, scale .4s cubic-bezier(.3, 1.5, .5, 1); }
.mnt-island__lead svg { width: 22px; height: 22px; }
.mnt-island__track { stroke: color-mix(in oklch, var(--mnt-island-accent) 25%, transparent); stroke-width: 2.4; }
.mnt-island__arc { stroke: var(--mnt-island-accent); stroke-width: 2.4; stroke-dasharray: var(--mnt-island-p, 0) 100; rotate: -90deg; transform-origin: 12px 12px; }
.mnt-island__arrow, .mnt-island__pause { stroke: var(--mnt-island-fg); stroke-width: 1.9; transition: opacity .2s; }
.mnt-island__pause { opacity: 0; }
.mnt-island__done { color: var(--mnt-island-ok); }
.mnt-island__done path { stroke-dasharray: 14; stroke-dashoffset: 14; transition: stroke-dashoffset .5s var(--mnt-island-ease) .15s; }
.mnt-island__warn { color: var(--mnt-island-rec); }
.mnt-island__dots { display: flex; gap: 3px; }
.mnt-island__dots b { width: 4px; height: 4px; border-radius: 50%; background: var(--mnt-island-faint); }
.mnt-island__lead > :not(.mnt-island__dots) { opacity: 0; scale: .6; }
.mnt-island:is([data-mode="export"], [data-mode="paused"]) .mnt-island__ring,
.mnt-island[data-mode="done"] .mnt-island__done,
.mnt-island[data-mode="saved"] .mnt-island__done,
.mnt-island[data-mode="error"] .mnt-island__warn { opacity: 1; scale: 1; }
.mnt-island:not([data-mode="idle"]) .mnt-island__dots { opacity: 0; scale: .6; }
.mnt-island:is([data-mode="done"], [data-mode="saved"]) .mnt-island__done path { stroke-dashoffset: 0; }
.mnt-island[data-mode="paused"] .mnt-island__arrow { opacity: 0; }
.mnt-island[data-mode="paused"] .mnt-island__pause { opacity: 1; }
.mnt-island[data-mode="paused"] .mnt-island__arc { stroke: var(--mnt-island-dim); }
.mnt-island__label { font-size: 12.5px; font-weight: 600; letter-spacing: -.005em; overflow: hidden; text-overflow: ellipsis; }
.mnt-island__val { font: 600 12.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mnt-island-accent); }
.mnt-island:is([data-mode="done"], [data-mode="saved"]) .mnt-island__val { color: var(--mnt-island-ok); }
.mnt-island[data-mode="error"] .mnt-island__val { color: var(--mnt-island-rec); }
.mnt-island[data-mode="idle"] .mnt-island__label { color: var(--mnt-island-faint); font-weight: 500; }

.mnt-island__bubble {
  display: flex; align-items: center; justify-content: center; gap: 6px; width: 76px; height: 36px; border-radius: 18px;
  font: 600 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--mnt-island-rec); animation: mnt-island-blink 1.2s steps(2, jump-none) infinite; }
}

.mnt-island__full { overflow: hidden; }
.mnt-island__fin { padding: 14px 14px 14px; }
.mnt-island__fh {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
}
.mnt-island__thumb {
  display: grid; place-items: center; width: 40px; height: 40px; border-radius: 10px;
  color: var(--mnt-island-pill);
  background: linear-gradient(160deg, oklch(0.82 0.12 60), oklch(0.55 0.1 240));
  & svg { width: 20px; height: 20px; stroke-width: 1.6; }
}
.mnt-island__ft { margin: 0; font-size: 14px; font-weight: 650; letter-spacing: -.01em; line-height: 1.25; text-wrap: balance; }
.mnt-island__fs { margin: 2px 0 0; font-size: 11.5px; color: var(--mnt-island-dim); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnt-island__close {
  display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: var(--mnt-island-raise); color: var(--mnt-island-dim);
  & svg { width: 16px; height: 16px; }
  &:hover { color: var(--mnt-island-fg); }
}
.mnt-island__body { margin-top: 12px; }
.mnt-island__bar {
  height: 6px; border-radius: 3px; overflow: hidden; background: color-mix(in oklch, var(--mnt-island-fg) 12%, transparent);
  & i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, color-mix(in oklch, var(--mnt-island-accent) 70%, var(--mnt-island-pill)), var(--mnt-island-accent)); transform-origin: left; transform: scaleX(var(--mnt-island-q, 0)); }
}
.mnt-island[data-mode="paused"] .mnt-island__bar i { background: var(--mnt-island-dim); }
.mnt-island[data-mode="error"] .mnt-island__bar i { background: var(--mnt-island-rec); }
.mnt-island__stats {
  display: flex; justify-content: space-between; gap: 8px; margin: 7px 0 0;
  font-size: 11.5px; color: var(--mnt-island-dim); font-variant-numeric: tabular-nums;
  & b { font: 600 12px/1.3 ui-monospace, Menlo, monospace; color: var(--mnt-island-fg); }
}
.mnt-island__msg { margin: 0; font-size: 12.5px; color: var(--mnt-island-dim); text-wrap: pretty; font-variant-numeric: tabular-nums; }
.mnt-island__msg b { color: var(--mnt-island-fg); font-weight: 600; }
.mnt-island__acts {
  display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px;
  & button {
    padding: 7px 12px; border-radius: 99px; font-size: 12px; font-weight: 620;
    background: var(--mnt-island-raise);
    transition: background-color .2s, scale .25s cubic-bezier(.3, 1.5, .5, 1);
  }
  & button:hover { background: color-mix(in oklch, var(--mnt-island-fg) 16%, var(--mnt-island-pill)); }
  & button:active { scale: .95; }
  & button.is-main { color: var(--mnt-island-pill); background: var(--mnt-island-accent); }
  & button.is-main:hover { background: color-mix(in oklch, var(--mnt-island-accent) 85%, var(--mnt-island-fg)); }
}
.mnt-island__rec {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center; gap: 8px;
  margin-top: 12px; padding: 8px 8px 8px 12px; border-radius: 12px; background: color-mix(in oklch, var(--mnt-island-rec) 16%, var(--mnt-island-pill));
  font-size: 12px; font-weight: 600;
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--mnt-island-rec); animation: mnt-island-blink 1.2s steps(2, jump-none) infinite; }
  & time { font: 600 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & button { padding: 5px 10px; border-radius: 99px; font-size: 11.5px; font-weight: 650; background: var(--mnt-island-rec); color: var(--mnt-island-fg); }
  &[hidden] { display: none; }
}

/* ---------- dock ---------- */
.mnt-island__dock {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px;
  padding: 10px 12px 12px;
  border-top: 1px solid var(--mnt-island-line);
  background: color-mix(in oklch, var(--mnt-island-bg) 70%, var(--mnt-island-pill));
}
.mnt-island__go, .mnt-island__recbtn {
  display: inline-flex; align-items: center; gap: 6px; padding: 8px 12px 8px 10px; border-radius: 10px;
  font-size: 12.5px; font-weight: 620; white-space: nowrap;
  transition: background-color .2s, opacity .2s, scale .25s cubic-bezier(.3, 1.5, .5, 1);
  & svg { width: 16px; height: 16px; }
  &:active { scale: .96; }
  &[aria-disabled="true"] { opacity: .4; cursor: default; scale: 1; }
}
.mnt-island__go { color: var(--mnt-island-pill); background: var(--mnt-island-accent); }
.mnt-island__recbtn {
  background: var(--mnt-island-raise); box-shadow: inset 0 0 0 1px var(--mnt-island-line);
  & i { width: 9px; height: 9px; border-radius: 50%; background: var(--mnt-island-rec); transition: border-radius .3s, scale .3s; }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--mnt-island-rec) 22%, var(--mnt-island-pill)); }
  &[aria-pressed="true"] i { border-radius: 2px; scale: .9; }
}
.mnt-island__dest {
  display: grid; grid-template-columns: 1fr 1fr; gap: 2px; padding: 2px; border-radius: 10px; min-width: 0;
  background: color-mix(in oklch, var(--mnt-island-fg) 7%, transparent);
  & button {
    display: grid; padding: 4px 8px; border-radius: 8px; text-align: left; min-width: 0;
    font-size: 11.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--mnt-island-dim);
    transition: background-color .2s, color .2s;
  }
  & small { font-size: 10px; font-weight: 500; color: var(--mnt-island-faint); font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; }
  & button[aria-checked="true"] { color: var(--mnt-island-fg); background: var(--mnt-island-raise); box-shadow: 0 1px 0 color-mix(in oklch, var(--mnt-island-fg) 8%, transparent) inset; }
  &[aria-disabled="true"] { opacity: .5; }
  &[aria-disabled="true"] button { cursor: default; }
}
.mnt-island__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 340px) {
  .mnt-island__dock { grid-template-columns: 1fr 1fr; }
  .mnt-island__dest { grid-column: 1 / -1; grid-row: 1; }
  .mnt-island__go, .mnt-island__recbtn { justify-content: center; }
  .mnt-island__viewer span { display: none; }
}

@keyframes mnt-island-blink { 0% { opacity: 1; } 50% { opacity: .25; } }

@media (prefers-reduced-motion: reduce) {
  .mnt-island__bubble i, .mnt-island__rec i { animation: none; }
  .mnt-island__lead > *, .mnt-island__done path, .mnt-island__go, .mnt-island__recbtn, .mnt-island__acts button { transition: opacity .15s linear; }
  .mnt-island__lead > :not(.mnt-island__dots) { scale: 1; }
}

js:
const $ = (s, el = root) => el.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = Math.random().toString(36).slice(2, 7);
const stage = $('.mnt-island__stage'), pill = $('.mnt-island__pill'), bub = $('.mnt-island__bub');
const compact = $('.mnt-island__compact'), full = $('.mnt-island__full'), fin = $('.mnt-island__fin'), bubble = $('.mnt-island__bubble');
const body = $('.mnt-island__body'), recRow = $('.mnt-island__rec'), sr = $('.mnt-island__sr');
const goBtn = $('[data-do="export"]'), recBtn = $('[data-do="record"]'), dest = $('.mnt-island__dest');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const say = (t) => { sr.textContent = ''; later(40, () => { sr.textContent = t; }); };
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));

const fid = 'mnt-island-goo-' + UID;
$('.mnt-island__goo').id = fid;
$('.mnt-island__blob').setAttribute('filter', 'url(#' + fid + ')');
full.id = 'mnt-island-' + UID + '-full';
compact.setAttribute('aria-controls', full.id);

/* ---------- springs ---------- */
const S = (v, k, c) => ({ v, vel: 0, to: v, k, c });
const sp = {
  w: S(112, 380, 30), h: S(32, 380, 30), r: S(16, 380, 30),
  sx: S(0, 900, 13),
  g: S(-40, 240, 17), s: S(0, 300, 22),
};
const TOTAL = 4.8, SECS = 24, SSD_FREE = 1.2;
const COMPACT = { idle: [136, 32], export: [228, 36], paused: [228, 36], done: [204, 36], error: [212, 36], saved: [200, 36] };

let W = 320, WE = 300, HE = 170, WC = 112, HC = 32;
let mode = 'idle', expanded = false, raf = 0, last = 0, onscreen = true;
let job = null;            // { p, dest, active, stamp } — progress is wall-clock, so it keeps going off screen
let rec = null;            // { t, t0 }
let target = 'nas';
let shownPct = -1, shownRec = -1, shownSecs = -1;

const fmtT = (t) => Math.floor(t / 60) + ':' + String(Math.floor(t % 60)).padStart(2, '0');
const gb = (v) => v.toFixed(2) + ' GB';

/* ---------- content ---------- */
const HEAD = {
  export: ['Harbor Lights — final cut', 'Mezzanine 10-bit · 3840×2160 · 2:41'],
  paused: ['Harbor Lights — final cut', 'Mezzanine 10-bit · 3840×2160 · 2:41'],
  done: ['Harbor Lights exported', 'Mezzanine 10-bit · 3840×2160 · 2:41'],
  error: ['Studio SSD is full', 'Harbor Lights — final cut'],
  idle: ['Nothing running', 'Kestrel Cut · Live activity'],
  saved: ['Screen recording saved', 'Kestrel Cut · Desktop'],
};
const destName = (d) => (d === 'ssd' ? 'Studio SSD' : 'Archive NAS');

const fillBody = () => {
  let h = '';
  if (mode === 'export' || mode === 'paused') {
    h = '<div class="mnt-island__bar"><i></i></div>' +
      '<p class="mnt-island__stats"><span class="mnt-island__amt"></span><b class="mnt-island__pct"></b></p>' +
      '<div class="mnt-island__acts"><button type="button" class="is-main" data-do="pause">' + (mode === 'paused' ? 'Resume' : 'Pause') + '</button>' +
      '<button type="button" data-do="cancel">Cancel</button></div>';
  } else if (mode === 'done') {
    h = '<p class="mnt-island__msg"><b>4.80 GB</b> in ' + SECS + ' s to ' + destName(job ? job.dest : 'nas') + '</p>' +
      '<div class="mnt-island__acts"><button type="button" class="is-main" data-do="again">Export again</button><button type="button" data-do="dismiss">Done</button></div>';
  } else if (mode === 'error') {
    h = '<p class="mnt-island__msg">Stopped at <b>1.20 of 4.80 GB</b>. Studio SSD has 1.2 GB free; this export needs 4.80 GB.</p>' +
      '<div class="mnt-island__acts"><button type="button" class="is-main" data-do="retry">Retry on Archive NAS</button><button type="button" data-do="dismiss">Dismiss</button></div>';
  } else if (mode === 'saved') {
    h = '<p class="mnt-island__msg"><b>' + fmtT(lastClip) + '</b> clip saved to Desktop as Kestrel capture 14.mov</p>' +
      '<div class="mnt-island__acts"><button type="button" class="is-main" data-do="dismiss">Done</button></div>';
  } else {
    h = '<p class="mnt-island__msg">Exports and recordings show up here while they run, and stay put when you switch projects.</p>' +
      '<div class="mnt-island__acts"><button type="button" class="is-main" data-do="export">Start export</button></div>';
  }
  body.innerHTML = h;
  $('.mnt-island__ft').textContent = HEAD[mode][0];
  $('.mnt-island__fs').textContent = HEAD[mode][1];
  shownPct = -1; shownSecs = -1;
};
let lastClip = 0;

const labels = () => {
  const L = { idle: 'No activity', export: 'Exporting', paused: 'Paused', done: 'Exported', error: 'Disk full', saved: 'Clip saved' };
  $('.mnt-island__label').textContent = L[mode];
  const v = mode === 'done' ? '4.80 GB' : mode === 'error' ? '25%' : mode === 'saved' ? fmtT(lastClip) : '';
  $('.mnt-island__val').textContent = v;
  compact.setAttribute('aria-label', mode === 'idle' ? 'Live activity, nothing running' : L[mode] + (job && (mode === 'export' || mode === 'paused') ? ' ' + Math.round(job.p * 100) + ' percent' : ''));
};

const measure = () => {
  W = stage.clientWidth;
  WE = Math.min(W - 24, 372);
  full.style.width = WE + 'px';
  full.style.height = 'auto';
  HE = fin.offsetHeight;
  full.style.height = HE + 'px';
  [WC, HC] = COMPACT[mode];
  WC = Math.min(WC, W - 24);
  compact.style.width = WC + 'px';
  compact.style.height = HC + 'px';
};

const retarget = () => {
  if (expanded) { sp.w.to = WE; sp.h.to = HE; sp.r.to = 26; }
  else { sp.w.to = WC; sp.h.to = HC; sp.r.to = HC / 2; }
  if (rec && !expanded) { sp.g.to = 8; sp.s.to = 1; }
  else if (rec) { sp.g.to = -70; sp.s.to = 0.5; }
  else { sp.g.to = -70; sp.s.to = 0; }
  kick();
};

const setMode = (m) => {
  mode = m;
  root.dataset.mode = m;
  labels();
  fillBody();
  measure();
  retarget();
  syncDock();
};

const setExpanded = (on, focus) => {
  expanded = on;
  compact.setAttribute('aria-expanded', on);
  full.inert = !on;
  compact.tabIndex = on ? -1 : 0;
  retarget();
  if (on && focus) later(RM.matches ? 0 : 160, () => { const b = $('.mnt-island__acts button', full) || $('.mnt-island__close'); if (b) b.focus({ preventScroll: true }); });
  if (!on && focus) compact.focus({ preventScroll: true });
};

const syncDock = () => {
  const busy = mode === 'export' || mode === 'paused';
  goBtn.setAttribute('aria-disabled', busy);
  dest.setAttribute('aria-disabled', busy);
  recBtn.setAttribute('aria-pressed', !!rec);
  recBtn.querySelector('span').textContent = rec ? 'Stop' : 'Record';
  recRow.hidden = !rec;
  bubble.tabIndex = rec && !expanded ? 0 : -1;
};

/* ---------- jobs ---------- */
const startExport = (d, p0, quiet) => {
  job = { p: p0 || 0, dest: d, active: true, stamp: performance.now() };
  setMode('export');
  if (!quiet) say('Exporting Harbor Lights to ' + destName(d));
};
const finish = () => {
  job.active = false;
  setMode('done');
  say('Export finished: 4.80 GB to ' + destName(job.dest));
  if (!RM.matches) { sp.h.vel -= 140; }
  later(5000, () => { if (mode === 'done' && !expanded) setMode('idle'); });
};
const fail = () => {
  job.active = false;
  job.p = SSD_FREE / TOTAL;
  setMode('error');
  say('Export failed. Studio SSD ran out of space at 1.20 of 4.80 gigabytes.');
  if (!RM.matches) sp.sx.vel = -700;
};

const ACT = {
  export() { if (mode === 'export' || mode === 'paused') return; startExport(target, 0); },
  again() { startExport(target, 0); },
  retry() { pickDest('nas'); startExport('nas', 0); },
  pause() {
    if (!job) return;
    if (job.active) work();
    job.active = !job.active;
    job.stamp = performance.now();
    setMode(job.active ? 'export' : 'paused');
    say(job.active ? 'Export resumed' : 'Export paused');
    const b = $('[data-do="pause"]', full);
    if (b && expanded) b.focus({ preventScroll: true });
  },
  cancel() {
    job = null;
    if (!RM.matches) sp.sx.vel = -900;
    setExpanded(false, true);
    setMode('idle');
    say('Export cancelled');
  },
  dismiss() { setExpanded(false, true); setMode('idle'); },
  record() {
    if (rec) return ACT.stoprec();
    rec = { t: 0, t0: performance.now() };
    shownRec = -1;
    syncDock();
    measure();
    retarget();
    say('Recording started');
  },
  stoprec() {
    if (!rec) return;
    work();
    lastClip = rec.t;
    rec = null;
    syncDock();
    measure();
    retarget();
    say('Recording saved, ' + Math.round(lastClip) + ' seconds');
    if (mode === 'idle') {
      later(RM.matches ? 0 : 380, () => {
        if (mode !== 'idle') return;
        setMode('saved');
        later(3200, () => { if (mode === 'saved' && !expanded) setMode('idle'); });
      });
    }
  },
};

const pickDest = (d) => {
  target = d;
  dest.querySelectorAll('[role="radio"]').forEach((b) => { const on = b.dataset.dest === d; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
};

/* ---------- frame ---------- */
const step = (o, dt) => {
  const a = -o.k * (o.v - o.to) - o.c * o.vel;
  o.vel += a * dt;
  o.v += o.vel * dt;
};
const simulate = (dt) => {
  const all = Object.values(sp);
  if (RM.matches) { all.forEach((o) => { o.v = o.to; o.vel = 0; }); return false; }
  const n = Math.max(1, Math.ceil(dt / 0.004));
  for (let i = 0; i < n; i++) all.forEach((o) => step(o, dt / n));
  let moving = false;
  all.forEach((o) => {
    if (Math.abs(o.v - o.to) < 0.05 && Math.abs(o.vel) < 0.5) { o.v = o.to; o.vel = 0; } else moving = true;
  });
  return moving;
};

const work = () => {
  let running = false;
  const now = performance.now();
  if (job && job.active) {
    running = true;
    job.p = Math.min(1, job.p + (now - job.stamp) / 1000 / SECS);
    job.stamp = now;
    if (job.dest === 'ssd' && job.p * TOTAL >= SSD_FREE) fail();
    else if (job.p >= 1) finish();
  }
  if (rec) { running = true; rec.t = (now - rec.t0) / 1000; }
  return running;
};

const paint = () => {
  const cx = W / 2 + sp.sx.v, top = 12;
  const w = Math.max(0, sp.w.v), h = Math.max(0, sp.h.v), r = Math.max(0, Math.min(sp.r.v, h / 2, w / 2));
  pill.setAttribute('x', (cx - w / 2).toFixed(2));
  pill.setAttribute('y', top);
  pill.setAttribute('width', w.toFixed(2));
  pill.setAttribute('height', h.toFixed(2));
  pill.setAttribute('rx', r.toFixed(2));

  const s = Math.max(0, sp.s.v), bw = 76 * s, bh = 36 * s;
  const bcx = cx + w / 2 + sp.g.v + bw / 2, bcy = top + 18;
  bub.setAttribute('x', (bcx - bw / 2).toFixed(2));
  bub.setAttribute('y', (bcy - bh / 2).toFixed(2));
  bub.setAttribute('width', bw.toFixed(2));
  bub.setAttribute('height', bh.toFixed(2));
  bub.setAttribute('rx', (bh / 2).toFixed(2));
  bubble.style.transform = 'translate(' + (bcx - 38).toFixed(2) + 'px,' + (bcy - 18) + 'px) scale(' + Math.max(0.01, s).toFixed(3) + ')';
  bubble.style.opacity = clamp((s - 0.7) / 0.3) * clamp((sp.g.v + 10) / 18);
  bubble.style.pointerEvents = rec && !expanded ? 'auto' : 'none';

  const p = clamp((h - HC) / Math.max(1, HE - HC));
  compact.style.transform = 'translate(' + (cx - WC / 2).toFixed(2) + 'px,' + top + 'px)';
  const ix = Math.max(0, (WC - w) / 2), ib = Math.max(0, HC - h);
  compact.style.clipPath = 'inset(0 ' + ix.toFixed(1) + 'px ' + ib.toFixed(1) + 'px ' + ix.toFixed(1) + 'px round ' + r.toFixed(1) + 'px)';
  compact.style.opacity = clamp(1 - p * 2.4);
  compact.style.pointerEvents = p > 0.4 ? 'none' : 'auto';

  full.style.transform = 'translate(' + (cx - WE / 2).toFixed(2) + 'px,' + top + 'px)';
  const fx = Math.max(0, (WE - w) / 2), fb = Math.max(0, HE - h);
  full.style.clipPath = 'inset(0 ' + fx.toFixed(1) + 'px ' + fb.toFixed(1) + 'px ' + fx.toFixed(1) + 'px round ' + r.toFixed(1) + 'px)';
  const q = clamp((p - 0.3) / 0.7);
  full.style.opacity = q;
  fin.style.filter = q > 0.98 || q < 0.02 ? 'none' : 'blur(' + ((1 - q) * 5).toFixed(2) + 'px)';
  full.style.pointerEvents = p > 0.6 ? 'auto' : 'none';

  if (job && (mode === 'export' || mode === 'paused' || mode === 'error')) {
    const pct = Math.floor(job.p * 100);
    compact.style.setProperty('--mnt-island-p', (job.p * 100).toFixed(2));
    full.style.setProperty('--mnt-island-q', job.p.toFixed(4));
    if (pct !== shownPct) {
      shownPct = pct;
      if (mode !== 'error') {
        $('.mnt-island__val').textContent = pct + '%';
        compact.setAttribute('aria-label', (mode === 'paused' ? 'Export paused at ' : 'Exporting, ') + pct + ' percent. Show details');
      }
      const pe = $('.mnt-island__pct', full);
      if (pe) pe.textContent = pct + '%';
    }
    const secs = Math.ceil((1 - job.p) * SECS);
    const amt = secs !== shownSecs && $('.mnt-island__amt', full);
    if (amt) {
      shownSecs = secs;
      amt.textContent = gb(job.p * TOTAL) + ' of 4.80 GB · ' + (mode === 'paused' ? 'paused' : secs + ' s left');
    }
  }
  if (rec) {
    const t = Math.floor(rec.t);
    if (t !== shownRec) {
      shownRec = t;
      bubble.querySelector('time').textContent = fmtT(t);
      recRow.querySelector('time').textContent = fmtT(t);
    }
  }
};

const loop = (t) => {
  if (!root.isConnected) return;
  raf = 0;
  const dt = last ? Math.min(0.05, (t - last) / 1000) : 1 / 60;
  last = t;
  const moving = simulate(dt);
  const running = work();
  paint();
  if ((moving || running) && onscreen && !document.hidden) raf = requestAnimationFrame(loop);
  else last = 0;
};
const kick = () => { if (!raf && onscreen) { last = 0; raf = requestAnimationFrame(loop); } };

/* ---------- events ---------- */
root.addEventListener('click', (e) => {
  const b = e.target.closest('[data-do]');
  if (b) {
    if (b.getAttribute('aria-disabled') === 'true') return;
    ACT[b.dataset.do]();
    return;
  }
  const r = e.target.closest('[role="radio"]');
  if (r) { if (dest.getAttribute('aria-disabled') !== 'true') pickDest(r.dataset.dest); return; }
  if (e.target.closest('.mnt-island__compact')) { setExpanded(true, e.detail === 0); return; }
  if (e.target.closest('.mnt-island__close')) { setExpanded(false, true); return; }
  if (e.target.closest('.mnt-island__bubble')) { ACT.stoprec(); return; }
  if (expanded && e.target.isConnected && !e.target.closest('.mnt-island__full, .mnt-island__dock')) setExpanded(false, false);
});
root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && expanded) { e.preventDefault(); setExpanded(false, true); }
});
dest.addEventListener('keydown', (e) => {
  if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key) || dest.getAttribute('aria-disabled') === 'true') return;
  e.preventDefault();
  pickDest(target === 'nas' ? 'ssd' : 'nas');
  dest.querySelector('[aria-checked="true"]').focus();
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  if (onscreen) kick();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) kick();
};
document.addEventListener('visibilitychange', onVis);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  measure();
  retarget();
});
ro.observe(stage);

/* mount mid-export so the pill is alive at rest */
measure();
startExport('nas', 0.38, true);
sp.w.v = WC; sp.h.v = HC; sp.r.v = HC / 2;
paint();
kick();

