const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = CSS.supports('transition-timing-function', 'linear(0, 1)')
  ? 'linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1)'
  : 'cubic-bezier(.3,1.3,.5,1)';
const list = $('.mnt-undo__list'), fx = $('.mnt-undo__fx'), toast = $('.mnt-undo__toast'), tray = $('.mnt-undo__tray');
const empty = $('.mnt-undo__empty'), sr = $('.mnt-undo__sr'), timerEl = $('.mnt-undo__timer');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const say = (t) => { sr.textContent = ''; later(40, () => { sr.textContent = t; }); };
const MAC = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
$('.mnt-undo__kbd').textContent = MAC ? '⌘Z' : 'Ctrl Z';

const JOBS = [
  { id: 'j1', at: '09:30', t: 'Replace filter cartridge', where: 'Halvorsen Bakery · Unit 4B', min: 45 },
  { id: 'j2', at: '11:00', t: 'Compressor swap', where: 'Marlow Deli · walk-in cooler', min: 30, tag: 'quote' },
  { id: 'j3', at: '13:15', t: 'Inspect rooftop condenser', where: '18 Quay Street', min: 60, tag: 'urgent' },
  { id: 'j4', at: '14:40', t: 'Recharge refrigerant', where: 'Brightwater Café', min: 75 },
  { id: 'j5', at: '16:00', t: 'Annual service', where: 'Saltmarsh Brewery · 3 units', min: 120 },
];
const ARCH = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="4.5" width="17" height="4.5" rx="1"/><path d="M5.5 9v9a1.5 1.5 0 0 0 1.5 1.5h10a1.5 1.5 0 0 0 1.5-1.5V9M10 13h4"/></svg>';
const dur = (m) => (m >= 60 ? Math.floor(m / 60) + ' h' + (m % 60 ? ' ' + (m % 60) + ' m' : '') : m + ' m');

list.innerHTML = JOBS.map((j) => '<li class="mnt-undo__row" data-id="' + j.id + '">' +
  '<input class="mnt-undo__check" type="checkbox" aria-label="Select ' + j.t + '">' +
  '<div class="mnt-undo__txt"><p class="mnt-undo__t"><span>' + j.t + '</span>' + (j.tag ? '<b class="mnt-undo__tag" data-k="' + j.tag + '">' + (j.tag === 'urgent' ? 'Urgent' : 'Quote') + '</b>' : '') + '</p>' +
  '<p class="mnt-undo__m"><time>' + j.at + '</time> · ' + j.where + ' · ' + dur(j.min) + '</p></div>' +
  '<button class="mnt-undo__arch" type="button" data-do="archive" aria-label="Archive ' + j.t + '">' + ARCH + '</button></li>').join('');

let batch = null, timer = null, onscreen = true, hovering = false, focusIn = false;

const rowOf = (id) => list.querySelector('[data-id="' + id + '"]');
const rows = () => $$('.mnt-undo__row:not([hidden])', list);
const box = (el) => { const a = el.getBoundingClientRect(), b = root.getBoundingClientRect(); return { x: a.left - b.left, y: a.top - b.top, w: a.width, h: a.height }; };
