const trayPoint = () => ({ x: toast.offsetLeft + tray.offsetLeft + tray.offsetWidth / 2, y: toast.offsetTop + tray.offsetTop + tray.offsetHeight / 2 });

const counts = () => {
  const vis = rows(), mins = vis.reduce((s, r) => s + JOBS.find((j) => j.id === r.dataset.id).min, 0);
  $('.mnt-undo__open').textContent = vis.length;
  $('.mnt-undo__hrs').textContent = dur(mins) + ' booked';
  empty.hidden = vis.length > 0;
  syncBulk();
};
const syncBulk = () => {
  const n = $$('.mnt-undo__check:checked', list).length;
  $('.mnt-undo__sel').textContent = n + ' selected';
  $('.mnt-undo__bulkin').inert = n === 0;
};
const setNum = (n) => {
  const el = $('.mnt-undo__num');
  if (el.textContent === String(n)) return;
  el.textContent = n;
  $('.mnt-undo__noun').textContent = n === 1 ? 'job' : 'jobs';
  if (!RM.matches) el.animate([{ transform: 'translateY(55%)', opacity: 0, filter: 'blur(2px)' }, { transform: 'none', opacity: 1, filter: 'blur(0)' }], { duration: 320, easing: 'cubic-bezier(.22,1,.36,1)' });
};

const ghost = (r) => {
