  g.removeAttribute('data-id');
  g.hidden = false;
  g.style.visibility = 'visible';
  g.inert = true;
  Object.assign(g.style, { left: b.x + 'px', top: b.y + 'px', width: b.w + 'px', height: b.h + 'px' });
