  if (RM.matches) return;
  rows().forEach((r) => {
    const f = first.get(r);
    if (!f) return;
    const dy = f.top - r.getBoundingClientRect().top;
    if (Math.abs(dy) > 0.5) r.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 480, easing: SPRING });
  });
