/* ---------- the commit timer ---------- */
const syncTimer = () => {
  if (!timer) return;
  const hold = hovering || focusIn || !onscreen || document.hidden;
  if (hold && timer.playState === 'running') timer.pause();
  else if (!hold && timer.playState === 'paused') timer.play();
};
const restartTimer = () => {
  if (timer) timer.cancel();
  timer = timerEl.animate([{ transform: 'scaleX(1)' }, { transform: 'scaleX(0)' }], { duration: 6000, easing: 'linear', fill: 'forwards' });
  timer.onfinish = commit;
  syncTimer();
};

const showToast = () => {
  toast.classList.remove('is-out');
  toast.hidden = false;
};
const hideToast = () => {
  toast.classList.add('is-out');
  later(RM.matches ? 200 : 360, () => { if (!batch) { toast.hidden = true; toast.classList.remove('is-out'); } });
};

/* ---------- archive: rows arc into the tray ---------- */
const archive = (ids) => {
  ids = ids.filter((id) => { const r = rowOf(id); return r && !r.hidden; });
  if (!ids.length) return;
  const vis = rows();
  const first = new Map(vis.map((r) => [r, r.getBoundingClientRect()]));
  const focusWas = list.contains(document.activeElement);
  const lastIx = Math.max(...ids.map((id) => vis.indexOf(rowOf(id))));
  const after = vis.slice(lastIx + 1).find((r) => !ids.includes(r.dataset.id)) || vis.slice(0, lastIx).reverse().find((r) => !ids.includes(r.dataset.id));
  const ghosts = RM.matches ? [] : ids.map((id) => ghost(rowOf(id)));
  ids.forEach((id) => { const r = rowOf(id); r.hidden = true; r.querySelector('.mnt-undo__check').checked = false; });
  const fresh = !batch;
  if (fresh) batch = { ids: [], landed: 0 };
  batch.ids.push(...ids);
  if (fresh) setNum(0);
  showToast();
  counts();
  flipFrom(first);
  if (focusWas) (after ? after.querySelector('.mnt-undo__check') : $('.mnt-undo__btn')).focus({ preventScroll: true });
  const t = trayPoint();
  if (RM.matches) { batch.landed = batch.ids.length; setNum(batch.landed); }
  else toast.classList.add('is-catching');
  ghosts.forEach((g, k) => {
    const dx = t.x - (g._b.x + g._b.w / 2), dy = t.y - (g._b.y + g._b.h / 2);
    const a = g.animate([
      { transform: 'translate(0,0) scale(1)', opacity: 1 },
      { transform: 'translate(' + dx * 0.25 + 'px,' + (dy * 0.12 - 14) + 'px) scale(.9)', opacity: 1, offset: 0.32 },
      { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(.08)', opacity: 0.15 },
    ], { duration: 640, delay: k * 70, easing: 'cubic-bezier(.5,0,.8,.4)', fill: 'both' });
    a.onfinish = () => {
      g.remove();
      if (!batch) return;
      batch.landed = Math.min(batch.ids.length, batch.landed + 1);
      setNum(batch.landed);
      tray.animate([{ scale: 1 }, { scale: 1.22 }, { scale: 1 }], { duration: 340, easing: 'cubic-bezier(.3,1.6,.5,1)' });
