  say(batch.ids.length + (batch.ids.length === 1 ? ' job' : ' jobs') + ' archived. Press ' + (MAC ? 'Command' : 'Control') + ' Z to undo.');
};

/* ---------- undo: rows fly back out to their slots ---------- */
const undo = () => {
  if (!batch) return;
  const ids = batch.ids.slice();
  batch = null;
  if (timer) { timer.cancel(); timer = null; }
  fx.replaceChildren();
  toast.classList.remove('is-catching');
  const first = new Map(rows().map((r) => [r, r.getBoundingClientRect()]));
  const t = trayPoint();
  ids.forEach((id) => { const r = rowOf(id); r.hidden = false; if (!RM.matches) r.style.visibility = 'hidden'; });
  counts();
  flipFrom(first);
  if (!RM.matches) {
    ids.forEach((id, k) => {
      const r = rowOf(id), g = ghost(r);
      const dx = t.x - (g._b.x + g._b.w / 2), dy = t.y - (g._b.y + g._b.h / 2);
      const a = g.animate([
        { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(.08)', opacity: 0.15 },
        { transform: 'translate(0,0) scale(1)', opacity: 1 },
      ], { duration: 620, delay: k * 60, easing: SPRING, fill: 'both' });
      a.onfinish = () => { g.remove(); r.style.visibility = ''; };
    });
  }
  hideToast();
  const r0 = rowOf(ids[0]);
  if (r0) r0.querySelector('.mnt-undo__check').focus({ preventScroll: true });
  say('Restored ' + ids.length + (ids.length === 1 ? ' job' : ' jobs'));
};

const commit = () => {
  if (!batch) return;
  const n = batch.ids.length;
  batch.ids.forEach((id) => { rowOf(id).dataset.archived = ''; });
  batch = null;
  if (timer) { timer.cancel(); timer = null; }
  const had = toast.contains(document.activeElement);
  hideToast();
  if (had) { const vis = rows(); (vis.length ? vis[0].querySelector('.mnt-undo__check') : $('[data-do="restore"]')).focus({ preventScroll: true }); }
  say(n + (n === 1 ? ' job' : ' jobs') + ' archived for good');
};

const restoreAll = () => {
  if (batch) undo();
  const back = $$('.mnt-undo__row[hidden]', list);
  back.forEach((r, k) => {
    r.hidden = false;
    delete r.dataset.archived;
    if (!RM.matches) r.animate([{ opacity: 0, transform: 'translateY(10px)' }, { opacity: 1, transform: 'none' }], { duration: 420, delay: k * 50, easing: 'cubic-bezier(.22,1,.36,1)', fill: 'backwards' });
  });
  counts();
  const c = $('.mnt-undo__check', list);
  if (c) c.focus({ preventScroll: true });
  say('Restored all ' + JOBS.length + ' jobs');
};

/* ---------- events ---------- */
root.addEventListener('click', (e) => {
  const b = e.target.closest('[data-do]');
  if (!b) return;
  const act = b.dataset.do;
  if (act === 'archive') archive([b.closest('.mnt-undo__row').dataset.id]);
  else if (act === 'archive-sel') archive($$('.mnt-undo__check:checked', list).map((c) => c.closest('.mnt-undo__row').dataset.id));
  else if (act === 'clear') { $$('.mnt-undo__check:checked', list).forEach((c) => { c.checked = false; }); syncBulk(); const c = $('.mnt-undo__check', list); if (c) c.focus(); }
  else if (act === 'undo') undo();
  else if (act === 'commit') commit();
  else if (act === 'restore') restoreAll();
});
list.addEventListener('change', syncBulk);
root.addEventListener('keydown', (e) => {
  if ((e.metaKey || e.ctrlKey) && !e.shiftKey && !e.altKey && e.key.toLowerCase() === 'z') {
    if (batch) { e.preventDefault(); undo(); }
    return;
  }
  if (e.key === 'Escape' && batch) { e.preventDefault(); commit(); return; }
  const r = e.target.closest && e.target.closest('.mnt-undo__row');
  if (!r || e.metaKey || e.ctrlKey || e.altKey) return;
  const vis = rows(), k = vis.indexOf(r);
  const go = (x) => { if (x) x.querySelector('.mnt-undo__check').focus(); };
  if (e.key === 'ArrowDown') { e.preventDefault(); go(vis[k + 1]); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); go(vis[k - 1]); }
  else if (e.key === 'Home') { e.preventDefault(); go(vis[0]); }
  else if (e.key === 'End') { e.preventDefault(); go(vis[vis.length - 1]); }
  else if (e.key === 'Delete' || e.key === 'Backspace' || e.key.toLowerCase() === 'e') {
    e.preventDefault();
    const sel = $$('.mnt-undo__check:checked', list).map((c) => c.closest('.mnt-undo__row').dataset.id);
    archive(sel.includes(r.dataset.id) ? sel : [r.dataset.id]);
  }
});
toast.addEventListener('pointerenter', () => { hovering = true; syncTimer(); });
toast.addEventListener('pointerleave', () => { hovering = false; syncTimer(); });
toast.addEventListener('focusin', () => { focusIn = true; syncTimer(); });
toast.addEventListener('focusout', (e) => { if (!toast.contains(e.relatedTarget)) { focusIn = false; syncTimer(); } });

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); if (timer) timer.cancel(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  syncTimer();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  syncTimer();
};
document.addEventListener('visibilitychange', onVis);

counts();

