/* Re-theme with --mnt-presence-bg, -fg and -me (your own colour). People colours come from --h. */
.mnt-presence {
  --mnt-presence-bg: oklch(0.215 0.024 168);
  --mnt-presence-fg: oklch(0.95 0.012 150);
  --mnt-presence-me: oklch(0.88 0.16 128);
  --mnt-presence-follow: transparent;

  --mnt-presence-panel: color-mix(in oklch, var(--mnt-presence-fg) 5%, var(--mnt-presence-bg));
  --mnt-presence-line: color-mix(in oklch, var(--mnt-presence-fg) 10%, transparent);
  --mnt-presence-dim: color-mix(in oklch, var(--mnt-presence-fg) 62%, var(--mnt-presence-bg));
  --mnt-presence-faint: color-mix(in oklch, var(--mnt-presence-fg) 40%, var(--mnt-presence-bg));
  --mnt-presence-ease: cubic-bezier(.22, 1, .36, 1);
  --mnt-presence-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  min-width: 0;
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr);
  width: 100%;
  height: 500px;
  padding: 16px 12px 12px;
  border-radius: 18px;
  overflow: hidden;
  overflow: clip;
  color: var(--mnt-presence-fg);
  background:
    radial-gradient(80% 50% at 100% 0%, color-mix(in oklch, var(--mnt-presence-me) 8%, transparent), transparent 70%),
    var(--mnt-presence-bg);
  box-shadow: inset 0 0 0 1px var(--mnt-presence-line);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  &::after {
    content: ""; position: absolute; inset: 0; z-index: 6; border-radius: inherit; pointer-events: none;
    box-shadow: inset 0 0 0 2px var(--mnt-presence-follow), inset 0 0 28px -8px var(--mnt-presence-follow);
    opacity: 0; transition: opacity .4s var(--mnt-presence-ease);
  }
  &[data-follow]::after { opacity: 1; }
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mnt-presence { --mnt-presence-spring: cubic-bezier(.3, 1.3, .5, 1); }
}
:where(.mnt-presence) *, :where(.mnt-presence) *::before, :where(.mnt-presence) *::after { box-sizing: border-box; }
:where(.mnt-presence) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnt-presence) :focus-visible { outline: 2px solid var(--mnt-presence-me); outline-offset: 2px; }
.mnt-presence svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mnt-presence__head { padding: 0 4px; }
.mnt-presence__doc {
  display: flex; align-items: center; gap: 6px; margin: 0;
  font: 500 11px/1.3 ui-monospace, Menlo, monospace; color: var(--mnt-presence-faint);
  & svg { width: 14px; height: 14px; }
}
.mnt-presence__h { margin: 4px 0 0; font-size: clamp(16px, 5.2cqi, 20px); font-weight: 700; letter-spacing: -.02em; line-height: 1.15; text-wrap: balance; }

.mnt-presence__bar { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 4px 0; }
.mnt-presence__pile { display: flex; padding-left: 6px; }
.mnt-presence__who {
  position: relative; margin-left: -6px; border-radius: 50%;
  transition: translate .35s var(--mnt-presence-spring), z-index 0s;
  &:hover, &:focus-visible { translate: 0 -3px; z-index: 2; }
  &[aria-pressed="true"] .mnt-presence__av { box-shadow: 0 0 0 2px var(--mnt-presence-bg), 0 0 0 4px oklch(0.8 0.12 var(--h)); }
  &.is-loud .mnt-presence__av { animation: mnt-presence-glow 1.6s var(--mnt-presence-ease) 2; }
}
.mnt-presence__av {
  position: relative; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%;
  font-size: 10.5px; font-weight: 750; letter-spacing: .02em;
  color: oklch(0.25 0.06 var(--h)); background: oklch(0.8 0.12 var(--h));
  box-shadow: 0 0 0 2px var(--mnt-presence-bg);
  transition: filter .5s, opacity .5s, box-shadow .3s;
  &[data-me] { color: var(--mnt-presence-bg); background: var(--mnt-presence-me); }
  &[data-idle] { filter: saturate(.25) brightness(.8); }
}
.mnt-presence__who .mnt-presence__av::after {
  content: ""; position: absolute; right: -1px; bottom: -1px; width: 9px; height: 9px; border-radius: 50%;
  background: oklch(0.78 0.16 150); box-shadow: 0 0 0 2px var(--mnt-presence-bg);
}
.mnt-presence__who .mnt-presence__av[data-idle]::after { background: var(--mnt-presence-faint); }
.mnt-presence__count {
  margin: 0; font-size: 12px; color: var(--mnt-presence-dim); white-space: nowrap; font-variant-numeric: tabular-nums;
  & b { color: var(--mnt-presence-fg); font-weight: 700; }
}
.mnt-presence__info {
  min-height: 18px; margin: 6px 4px 0; font-size: 11.5px; color: var(--mnt-presence-dim);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  & b { color: var(--mnt-presence-fg); font-weight: 620; }
}

/* ---------- outline ---------- */
.mnt-presence__outline {
  list-style: none; margin: 6px 0 0; padding: 0; min-height: 0; overflow-y: auto; scrollbar-width: none;
  display: grid; align-content: start; gap: 4px;
}
.mnt-presence__sec {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center;
  border-radius: 12px;
  transition: background-color .35s var(--mnt-presence-ease);
  &::before {
    content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 2px;
    background: var(--mnt-presence-me); scale: 1 0; transition: scale .4s var(--mnt-presence-spring);
  }
  &[data-here] { background: var(--mnt-presence-panel); }
  &[data-here]::before { scale: 1 1; }
  &.is-flash { animation: mnt-presence-flash 1.4s var(--mnt-presence-ease); }
}
.mnt-presence__go {
  display: grid; grid-template-columns: 22px minmax(0, 1fr); column-gap: 8px; align-items: baseline;
  padding: 8px 6px 8px 12px; border-radius: 12px; text-align: left; min-width: 0;
  &:hover { background: color-mix(in oklch, var(--mnt-presence-fg) 4%, transparent); }
  &:focus-visible { outline-offset: -2px; }
}
.mnt-presence__num { font: 600 11px/1 ui-monospace, Menlo, monospace; color: var(--mnt-presence-faint); font-variant-numeric: tabular-nums; }
.mnt-presence__name { font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnt-presence__meta {
  grid-column: 2; display: flex; align-items: center; gap: 6px; margin-top: 2px;
  font-size: 11px; color: var(--mnt-presence-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden;
}
.mnt-presence__at {
  display: inline-grid; place-items: center; width: 16px; height: 16px; border-radius: 50%;
  font-size: 10px; font-weight: 800; color: var(--mnt-presence-bg); background: var(--mnt-presence-me);
  transition: scale .4s var(--mnt-presence-spring), opacity .3s;
  &[hidden] { display: none; }
}
@starting-style {
  .mnt-presence__at { scale: 0; opacity: 0; }
}
.mnt-presence__typing {
  display: inline-flex; align-items: center; gap: 5px; color: oklch(0.82 0.1 var(--h));
  & i { display: inline-flex; gap: 2px; }
  & i b { width: 3.5px; height: 3.5px; border-radius: 50%; background: currentColor; animation: mnt-presence-dot 1.1s var(--mnt-presence-ease) infinite; animation-delay: calc(var(--i) * 140ms); }
  &[hidden] { display: none; }
}
.mnt-presence__slot {
  display: flex; flex-direction: row-reverse; justify-content: flex-start; padding: 0 12px 0 10px; min-width: 0;
  & .mnt-presence__av { width: 24px; height: 24px; font-size: 8.5px; margin-left: -7px; }
  & .mnt-presence__av[data-me] { font-size: 7.5px; font-weight: 800; letter-spacing: -.02em; }
  & .mnt-presence__av:last-child { margin-left: 0; }
  & .mnt-presence__av.is-ping::before {
    content: ""; position: absolute; inset: 0; border-radius: 50%;
    box-shadow: 0 0 0 2px oklch(0.8 0.12 var(--h));
    animation: mnt-presence-ripple 1.1s cubic-bezier(0, 0, .2, 1) 3;
  }
}

/* ---------- follow chip and ping ---------- */
.mnt-presence[data-follow] .mnt-presence__count { display: none; }
.mnt-presence__chip {
  margin: 0; white-space: nowrap;
  display: inline-flex; align-items: center; gap: 6px; padding: 4px 6px 4px 9px; border-radius: 99px;
  font-size: 11.5px; font-weight: 650; color: var(--mnt-presence-bg); background: var(--mnt-presence-follow);
  transition: opacity .3s var(--mnt-presence-ease), translate .45s var(--mnt-presence-spring);
  & i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
  & kbd { padding: 1px 4px; border-radius: 4px; font: 600 9.5px/1.3 ui-monospace, Menlo, monospace; background: color-mix(in oklch, var(--mnt-presence-bg) 18%, transparent); }
  &[hidden] { display: none; }
}
@starting-style {
  .mnt-presence__chip { opacity: 0; translate: 0 -8px; }
}
.mnt-presence__ping {
  position: absolute; z-index: 5; left: 12px; right: 12px; bottom: 12px;
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: start; gap: 10px;
  padding: 11px 8px 11px 11px; border-radius: 14px;
  color: oklch(0.22 0.02 168); background: oklch(0.97 0.012 120);
  box-shadow: 0 18px 40px -16px oklch(0 0 0 / .6);
  transition: opacity .35s var(--mnt-presence-ease), translate .5s var(--mnt-presence-spring), scale .5s var(--mnt-presence-spring);
  &[hidden] { display: none; }
  &.is-out { opacity: 0; translate: 0 16px; transition: opacity .25s, translate .3s cubic-bezier(.5, 0, .75, 0); }
}
@starting-style {
  .mnt-presence__ping { opacity: 0; translate: 0 24px; scale: .96; }
}
.mnt-presence__pav {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%;
  font-size: 10.5px; font-weight: 750; color: oklch(0.25 0.06 var(--h)); background: oklch(0.8 0.12 var(--h));
}
.mnt-presence__ptxt p { margin: 0; }
.mnt-presence__pl { font-size: 12.5px; line-height: 1.35; text-wrap: pretty; & b { font-weight: 680; } }
.mnt-presence__pq { margin-top: 3px !important; font-size: 12px; line-height: 1.4; color: oklch(0.42 0.02 168); text-wrap: pretty; }
.mnt-presence__pacts {
  display: flex; gap: 2px;
  & button { display: grid; place-items: center; height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 680; }
  & [data-do="jump"] { color: var(--mnt-presence-fg); background: var(--mnt-presence-bg); }
  & [data-do="jump"]:hover { background: color-mix(in oklch, var(--mnt-presence-bg) 85%, var(--mnt-presence-me)); }
  & [data-do="dismiss"] { width: 28px; padding: 0; color: oklch(0.45 0.02 168); }
  & [data-do="dismiss"]:hover { background: oklch(0.9 0.015 120); }
  & svg { width: 15px; height: 15px; }
}
.mnt-presence__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 320px) {
  .mnt-presence__who .mnt-presence__av { width: 27px; height: 27px; }
  .mnt-presence__chip kbd { display: none; }
  .mnt-presence__slot { padding-right: 8px; }
  .mnt-presence__meta .mnt-presence__words { display: none; }
}

@keyframes mnt-presence-dot { 0%, 60%, 100% { translate: 0 0; opacity: .5; } 30% { translate: 0 -3px; opacity: 1; } }
@keyframes mnt-presence-ripple { from { scale: 1; opacity: 1; } to { scale: 2.6; opacity: 0; } }
@keyframes mnt-presence-glow { 50% { box-shadow: 0 0 0 2px var(--mnt-presence-bg), 0 0 0 6px oklch(0.8 0.12 var(--h) / .45); } }
@keyframes mnt-presence-flash { 0%, 35% { background-color: color-mix(in oklch, var(--mnt-presence-me) 16%, transparent); } }

@media (prefers-reduced-motion: reduce) {
  .mnt-presence__typing i b, .mnt-presence__slot .mnt-presence__av.is-ping::before, .mnt-presence__who.is-loud .mnt-presence__av, .mnt-presence__sec.is-flash { animation: none; }
  .mnt-presence__ping, .mnt-presence__chip, .mnt-presence__who, .mnt-presence__sec::before { transition: opacity .2s linear; }
  @starting-style {
    .mnt-presence__ping { translate: 0 0; scale: 1; }
    .mnt-presence__chip { translate: 0 0; }
  }
}

