const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = CSS.supports('transition-timing-function', 'linear(0, 1)')
  ? 'linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1)'
  : 'cubic-bezier(.3,1.3,.5,1)';
const outline = $('.mnt-presence__outline'), pile = $('.mnt-presence__pile'), info = $('.mnt-presence__info');
const ping = $('.mnt-presence__ping'), chip = $('.mnt-presence__chip'), sr = $('.mnt-presence__sr');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const say = (t) => { sr.textContent = ''; later(40, () => { sr.textContent = t; }); };

const SECTIONS = [
  ['Summary', '240 words'], ['Goals and non-goals', '410 words'], ['Conflict resolution', '1,180 words · 4 comments'],
  ['Storage format', '860 words'], ['Rollout plan', '530 words'], ['Open questions', '7 items'],
];
const PEOPLE = {
  me: { name: 'You', ini: 'YOU', h: 128, at: 2, idle: false },
  hs: { name: 'Hana Sato', first: 'Hana', ini: 'HS', h: 22, at: 2, idle: false },
  rm: { name: 'Ravi Menon', first: 'Ravi', ini: 'RM', h: 88, at: 3, idle: false, typing: true },
  lf: { name: 'Lucía Ferrer', first: 'Lucía', ini: 'LF', h: 350, at: 0, idle: false },
  tg: { name: 'Theo Grant', first: 'Theo', ini: 'TG', h: 235, at: 4, idle: true },
  na: { name: 'Noor Aziz', first: 'Noor', ini: 'NA', h: 300, at: 2, idle: false },
};
const OTHERS = ['hs', 'rm', 'lf', 'tg', 'na'];
/* one scripted afternoon, replayed in a loop */
const SCRIPT = [
  ['lf', 'move', 1], ['tg', 'wake'], ['tg', 'move', 5],
  ['hs', 'move', 5], ['hs', 'ping', 5, 'mentioned you in', '“@you can we drop the 30-day tombstone limit for pinned notes?”'],
  ['na', 'type', true], ['rm', 'type', false], ['rm', 'move', 2],
  ['lf', 'move', 3], ['tg', 'sleep'], ['na', 'type', false], ['na', 'move', 4],
  ['rm', 'ping', 2, 'replied to your comment in', '“Agreed — LWW per field, not per note. Updated the table.”'],
  ['hs', 'move', 2], ['lf', 'move', 0], ['na', 'move', 2], ['tg', 'wake'], ['tg', 'move', 4], ['rm', 'type', true], ['rm', 'move', 3],
];

let step = 0, onscreen = true, follow = null, pending = null, focusSec = 2, infoFor = null;
const mentions = new Set();

const avHTML = (id, big) => {
  const p = PEOPLE[id];
  return '<span class="mnt-presence__av" data-who="' + id + '"' + (id === 'me' ? ' data-me' : '') + (p.idle ? ' data-idle' : '') +
    ' style="--h:' + p.h + '"' + (big ? '' : ' title="' + p.name + '"') + '>' + (id === 'me' ? 'You' : p.ini) + '</span>';
};

outline.innerHTML = SECTIONS.map((s, i) => '<li class="mnt-presence__sec" data-sec="' + i + '">' +
  '<button class="mnt-presence__go" type="button" tabindex="' + (i === 2 ? 0 : -1) + '"><span class="mnt-presence__num">' + (i + 1) + '</span>' +
  '<span class="mnt-presence__name">' + s[0] + '</span>' +
  '<span class="mnt-presence__meta"><b class="mnt-presence__at" hidden aria-label="mention">@</b><span class="mnt-presence__words">' + s[1] + '</span>' +
  '<span class="mnt-presence__typing" hidden><i aria-hidden="true"><b style="--i:0"></b><b style="--i:1"></b><b style="--i:2"></b></i><span></span></span></span></button>' +
  '<span class="mnt-presence__slot"></span></li>').join('');
pile.innerHTML = OTHERS.map((id, i) => '<button class="mnt-presence__who" type="button" data-who="' + id + '" aria-pressed="false" tabindex="' + (i ? -1 : 0) + '">' + avHTML(id, true) + '</button>').join('');

const secEl = (i) => outline.children[i];
const slotAv = (id) => outline.querySelector('.mnt-presence__slot [data-who="' + id + '"]');

const label = (id) => {
  const p = PEOPLE[id];
  return p.name + ', ' + (p.idle ? 'idle' : p.typing ? 'typing' : 'active') + ' in ' + SECTIONS[p.at][0] + (follow === id ? ', following' : '');
};
const paint = () => {
  outline.querySelectorAll('.mnt-presence__slot').forEach((s, i) => {
    const ids = [...OTHERS, 'me'].filter((id) => PEOPLE[id].at === i);
    ids.forEach((id) => { let a = slotAv(id); if (!a) { const t = document.createElement('template'); t.innerHTML = avHTML(id, false); a = t.content.firstElementChild; } if (a.parentElement !== s) s.append(a); a.toggleAttribute('data-idle', !!PEOPLE[id].idle); });
  });
  SECTIONS.forEach((s, i) => {
    const li = secEl(i), typers = OTHERS.filter((id) => PEOPLE[id].at === i && PEOPLE[id].typing && !PEOPLE[id].idle);
    li.toggleAttribute('data-here', PEOPLE.me.at === i);
    const ty = li.querySelector('.mnt-presence__typing');
    ty.hidden = !typers.length;
    if (typers.length) { ty.style.setProperty('--h', PEOPLE[typers[0]].h); ty.querySelector('span').textContent = PEOPLE[typers[0]].first + (typers.length > 1 ? ' +' + (typers.length - 1) : '') + ' typing'; }
    li.querySelector('.mnt-presence__words').hidden = !!typers.length;
    li.querySelector('.mnt-presence__at').hidden = !mentions.has(i);
    const here = Object.keys(PEOPLE).filter((id) => PEOPLE[id].at === i).map((id) => PEOPLE[id].name);
    li.querySelector('.mnt-presence__go').setAttribute('aria-label', (i + 1) + ', ' + s[0] + (here.length ? ', here: ' + here.join(', ') : '') + (mentions.has(i) ? ', you were mentioned' : ''));
  });
  $$('.mnt-presence__who', pile).forEach((b) => {
    const id = b.dataset.who;
    b.querySelector('.mnt-presence__av').toggleAttribute('data-idle', !!PEOPLE[id].idle);
    b.setAttribute('aria-label', label(id));
    b.setAttribute('aria-pressed', follow === id);
  });
  if (infoFor) writeInfo(infoFor);
  const active = OTHERS.filter((id) => !PEOPLE[id].idle).length;
  $('.mnt-presence__count').innerHTML = '<b>' + OTHERS.length + '</b> here · ' + active + ' active';
};

/* FLIP every slotted avatar across a change; the one that moved takes an arc */
const hop = (mutate, movers) => {
  const before = new Map($$('.mnt-presence__slot .mnt-presence__av', outline).map((a) => [a, a.getBoundingClientRect()]));
  mutate();
  if (RM.matches) return;
  $$('.mnt-presence__slot .mnt-presence__av', outline).forEach((a) => {
    const f = before.get(a);
    if (!f) { a.animate([{ scale: 0, opacity: 0 }, { scale: 1, opacity: 1 }], { duration: 420, easing: SPRING }); return; }
    const n = a.getBoundingClientRect(), dx = f.left - n.left, dy = f.top - n.top;
    if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) return;
    if (movers.includes(a.dataset.who)) {
      const lift = Math.min(36, 12 + Math.abs(dy) * 0.22);
      a.style.zIndex = 3;
      a.animate([
        { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(1)' },
        { transform: 'translate(' + dx * 0.45 + 'px,' + (dy * 0.5 - lift) + 'px) scale(1.28)', offset: 0.45 },
        { transform: 'translate(0,0) scale(1)' },
      ], { duration: 640 + Math.min(260, Math.abs(dy)), easing: 'cubic-bezier(.3,.7,.3,1)' }).onfinish = () => { a.style.zIndex = ''; };
    } else {
      a.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }], { duration: 460, easing: SPRING });
    }
  });
};

const moveMe = (i, why) => {
  if (PEOPLE.me.at === i) return;
  hop(() => { PEOPLE.me.at = i; mentions.delete(i); paint(); }, ['me']);
  const li = secEl(i);
  if (!RM.matches) { li.classList.remove('is-flash'); void li.offsetWidth; li.classList.add('is-flash'); }
  if (why) say(why);
};

const setFollow = (id) => {
  follow = follow === id ? null : id;
  if (follow) {
    root.style.setProperty('--mnt-presence-follow', 'oklch(0.8 0.12 ' + PEOPLE[follow].h + ')');
    root.setAttribute('data-follow', '');
    chip.querySelector('span').textContent = 'Following ' + PEOPLE[follow].first;
    chip.hidden = false;
    later(RM.matches ? 0 : 140, () => { if (follow) moveMe(PEOPLE[follow].at); });
    say('Following ' + PEOPLE[follow].name + '. Press Escape to stop.');
  } else {
    root.removeAttribute('data-follow');
    chip.hidden = true;
    say('Stopped following');
  }
  paint();
};

const showPing = (id, sec, verb, quote) => {
  pending = { id, sec };
  mentions.add(sec);
  const p = PEOPLE[id];
  const pav = $('.mnt-presence__pav');
  pav.style.setProperty('--h', p.h);
  pav.textContent = p.ini;
  $('.mnt-presence__pl').innerHTML = '<b>' + p.name + '</b> ' + verb + ' <b>' + SECTIONS[sec][0] + '</b>';
  $('.mnt-presence__pq').textContent = quote;
  ping.classList.remove('is-out');
  ping.hidden = false;
  const a = slotAv(id);
  if (a && !RM.matches) { a.classList.remove('is-ping'); void a.offsetWidth; a.classList.add('is-ping'); }
  const w = pile.querySelector('[data-who="' + id + '"]');
  if (w && !RM.matches) { w.classList.remove('is-loud'); void w.offsetWidth; w.classList.add('is-loud'); }
  paint();
  say(p.name + ' ' + verb + ' ' + SECTIONS[sec][0] + ': ' + quote);
};
const hidePing = (focusBack) => {
  if (ping.hidden) return;
  const had = ping.contains(document.activeElement);
  ping.classList.add('is-out');
  later(RM.matches ? 0 : 320, () => { ping.hidden = true; ping.classList.remove('is-out'); });
  pending = null;
  if (had || focusBack) secEl(PEOPLE.me.at).querySelector('.mnt-presence__go').focus({ preventScroll: true });
};

const run = ([id, act, a, b, c]) => {
  const p = PEOPLE[id];
  if (act === 'move') {
    if (p.at === a) return;
    const movers = [id];
    hop(() => {
      p.at = a;
      p.idle = false;
      if (follow === id) { PEOPLE.me.at = a; mentions.delete(a); movers.push('me'); }
      paint();
    }, movers);
    if (follow === id) say('Following ' + p.first + ' to ' + SECTIONS[a][0]);
  } else if (act === 'type') { p.typing = a; paint(); }
  else if (act === 'wake') { p.idle = false; paint(); }
  else if (act === 'sleep') { p.idle = true; p.typing = false; paint(); }
  else if (act === 'ping') showPing(id, a, b, c);
};

/* ---------- events ---------- */
outline.addEventListener('click', (e) => {
  const go = e.target.closest('.mnt-presence__go');
  if (!go) return;
  const i = +go.parentElement.dataset.sec;
  outline.querySelectorAll('.mnt-presence__go').forEach((b) => { b.tabIndex = -1; });
  go.tabIndex = 0;
  focusSec = i;
  if (follow) setFollow(follow);
  moveMe(i, 'Moved to ' + SECTIONS[i][0]);
  if (pending && pending.sec === i) hidePing(false);
});
outline.addEventListener('keydown', (e) => {
  const go = e.target.closest('.mnt-presence__go');
  if (!go) return;
  const btns = $$('.mnt-presence__go', outline), k = btns.indexOf(go);
  const to = { ArrowDown: k + 1, ArrowUp: k - 1, Home: 0, End: btns.length - 1 }[e.key];
  if (to === undefined || !btns[to]) return;
  e.preventDefault();
  btns.forEach((b) => { b.tabIndex = -1; });
  btns[to].tabIndex = 0;
  btns[to].focus();
});
pile.addEventListener('click', (e) => { const w = e.target.closest('.mnt-presence__who'); if (w) setFollow(w.dataset.who); });
pile.addEventListener('keydown', (e) => {
  const w = e.target.closest('.mnt-presence__who');
  if (!w) return;
  const ws = $$('.mnt-presence__who', pile), k = ws.indexOf(w);
  const to = { ArrowRight: k + 1, ArrowLeft: k - 1, Home: 0, End: ws.length - 1 }[e.key];
  if (to === undefined || !ws[to]) return;
  e.preventDefault();
  ws.forEach((x) => { x.tabIndex = -1; });
  ws[to].tabIndex = 0;
  ws[to].focus();
});
function writeInfo(id) {
  const p = PEOPLE[id];
  info.innerHTML = '<b>' + p.name + '</b> · ' + (p.idle ? 'idle' : p.typing ? 'typing' : 'active') + ' in ' + SECTIONS[p.at][0] + (follow === id ? ' · following' : ' · click to follow');
}
const showInfo = (e) => {
  const w = e.target.closest && e.target.closest('.mnt-presence__who');
  if (!w) return;
  infoFor = w.dataset.who;
  writeInfo(infoFor);
};
const clearInfo = () => { infoFor = null; info.textContent = ''; };
pile.addEventListener('pointerover', showInfo);
pile.addEventListener('focusin', showInfo);
pile.addEventListener('pointerleave', clearInfo);
pile.addEventListener('focusout', clearInfo);
ping.addEventListener('click', (e) => {
  const b = e.target.closest('[data-do]');
  if (!b || !pending) return;
  if (b.dataset.do === 'jump') {
    const sec = pending.sec;
    if (follow) setFollow(follow);
    moveMe(sec, 'Jumped to ' + SECTIONS[sec][0]);
    hidePing(true);
  } else hidePing(true);
});
root.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  if (follow) { e.preventDefault(); setFollow(follow); }
  else if (pending) { e.preventDefault(); hidePing(true); }
});

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
});
io.observe(root);
const iv = setInterval(() => {
  if (!root.isConnected) { clearInterval(iv); return; }
  if (!onscreen || document.hidden) return;
  run(SCRIPT[step % SCRIPT.length]);
  step++;
}, 2600);

paint();

css:
@property --mnt-pager-a {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
@property --mnt-pager-tone {
  syntax: "<color>";
  inherits: true;
  initial-value: oklch(0.64 0.22 27);
}

/* Re-theme with --mnt-pager-bg, -fg, and the state tones --mnt-pager-alarm / -ack / -ok. */
.mnt-pager {
  --mnt-pager-bg: oklch(0.17 0.012 30);
  --mnt-pager-fg: oklch(0.96 0.008 60);
  --mnt-pager-alarm: oklch(0.64 0.22 27);
  --mnt-pager-ack: oklch(0.8 0.15 75);
  --mnt-pager-ok: oklch(0.76 0.16 152);
  --mnt-pager-tone: var(--mnt-pager-alarm);

  --mnt-pager-panel: color-mix(in oklch, var(--mnt-pager-fg) 6%, var(--mnt-pager-bg));
  --mnt-pager-line: color-mix(in oklch, var(--mnt-pager-fg) 10%, transparent);
  --mnt-pager-dim: color-mix(in oklch, var(--mnt-pager-fg) 60%, var(--mnt-pager-bg));
  --mnt-pager-faint: color-mix(in oklch, var(--mnt-pager-fg) 38%, var(--mnt-pager-bg));
  --mnt-pager-ease: cubic-bezier(.22, 1, .36, 1);
  --mnt-pager-spring: linear(0, 0.06 3%, 0.24 7%, 0.6 14%, 0.86 21%, 1.01 29%, 1.06 35%, 1.05 42%, 1.01 55%, 0.995 70%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  min-width: 0;
  width: 100%;
  min-height: 470px;
  padding: 16px 16px 14px;
  border-radius: 20px;
  overflow: hidden;
  overflow: clip;
  color: var(--mnt-pager-fg);
  background:
    radial-gradient(110% 45% at 50% -8%, color-mix(in oklab, var(--mnt-pager-tone) 24%, transparent), transparent 70%),
    var(--mnt-pager-bg);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  transition: --mnt-pager-tone .9s var(--mnt-pager-ease);
  &::before {
    content: ""; position: absolute; inset: 0; z-index: 5; border-radius: inherit; padding: 1.5px; pointer-events: none;
    background: conic-gradient(from var(--mnt-pager-a), color-mix(in oklab, var(--mnt-pager-tone) 18%, transparent) 0 62%, var(--mnt-pager-tone) 82%, color-mix(in oklab, var(--mnt-pager-tone) 18%, transparent) 100%);
    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
    animation: mnt-pager-sweep 2.2s linear infinite;
  }
  &::after {
    content: ""; position: absolute; inset: -20% -10% auto; height: 60%; z-index: -1; pointer-events: none;
    background: radial-gradient(closest-side, color-mix(in oklab, var(--mnt-pager-tone) 30%, transparent), transparent);
    animation: mnt-pager-throb 1.6s ease-in-out infinite;
  }
}
.mnt-pager[data-state="acked"], .mnt-pager[data-state="escalated"] { --mnt-pager-tone: var(--mnt-pager-ack); }
.mnt-pager[data-state="acked"]::before, .mnt-pager[data-state="escalated"]::before { animation-duration: 6s; }
.mnt-pager:not([data-state="paging"])::after { animation: none; opacity: .5; }
.mnt-pager[data-state="resolved"] { --mnt-pager-tone: var(--mnt-pager-ok); }
.mnt-pager[data-state="resolved"]::before { animation: none; background: color-mix(in oklab, var(--mnt-pager-tone) 45%, transparent); }
.mnt-pager[data-offscreen]::before, .mnt-pager[data-offscreen]::after { animation-play-state: paused; }
@supports not (transition-timing-function: linear(0, 1)) {
  .mnt-pager { --mnt-pager-spring: cubic-bezier(.3, 1.4, .5, 1); }
}
:where(.mnt-pager) *, :where(.mnt-pager) *::before, :where(.mnt-pager) *::after { box-sizing: border-box; }
:where(.mnt-pager) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnt-pager) :focus-visible { outline: 2px solid var(--mnt-pager-fg); outline-offset: 2px; }
.mnt-pager svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mnt-pager__top { display: flex; align-items: center; gap: 8px; }
.mnt-pager__sev {
  padding: 3px 7px; border-radius: 6px; font: 800 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em;
  color: var(--mnt-pager-bg); background: var(--mnt-pager-tone);
}
.mnt-pager__state {
  display: inline-flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase;
  color: var(--mnt-pager-tone); white-space: nowrap;
  & i { position: relative; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
  & i::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: currentColor; animation: mnt-pager-ping 1.2s cubic-bezier(0, 0, .2, 1) infinite; }
}
.mnt-pager:not([data-state="paging"]) .mnt-pager__state i::after { animation: none; opacity: 0; }
.mnt-pager__since {
  margin-left: auto; font-size: 11.5px; color: var(--mnt-pager-dim); white-space: nowrap;
  & time { font: 600 12px/1 ui-monospace, Menlo, monospace; color: var(--mnt-pager-fg); font-variant-numeric: tabular-nums; }
}
.mnt-pager__title {
  margin: 14px 0 0; font: 700 clamp(18px, 6.2cqi, 24px)/1.12 system-ui, -apple-system, "Segoe UI", sans-serif; letter-spacing: -.025em; text-wrap: balance;
  font-variant-numeric: tabular-nums;
}
.mnt-pager__sub {
  margin: 6px 0 0; font-size: 12.5px; color: var(--mnt-pager-dim); text-wrap: pretty; font-variant-numeric: tabular-nums;
  & b { font: 600 11.5px/1 ui-monospace, Menlo, monospace; color: var(--mnt-pager-fg); }
}

.mnt-pager__spark { margin: 14px 0 0; }
.mnt-pager__plot {
  position: relative; height: 72px; container-type: inline-size;
  & svg { display: block; width: 100%; height: 72px; overflow: visible; }
}
.mnt-pager__area { fill: color-mix(in oklab, var(--mnt-pager-tone) 18%, transparent); stroke: none; }
.mnt-pager__line { stroke: var(--mnt-pager-tone); stroke-width: 2; vector-effect: non-scaling-stroke; }
.mnt-pager__th { stroke: var(--mnt-pager-faint); stroke-width: 1; stroke-dasharray: 3 4; vector-effect: non-scaling-stroke; }
.mnt-pager__thl { position: absolute; left: 0; bottom: 12px; font-size: 10px; color: var(--mnt-pager-faint); }
.mnt-pager__dot {
  position: absolute; left: 0; top: 0; width: 9px; height: 9px; border-radius: 50%;
  background: var(--mnt-pager-tone); box-shadow: 0 0 0 3px var(--mnt-pager-bg);
  translate: calc(100cqi - 4.5px) calc(var(--y, 0) * 1px - 4.5px);
  &::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: var(--mnt-pager-tone); animation: mnt-pager-ping 1.2s cubic-bezier(0, 0, .2, 1) infinite; }
}
.mnt-pager:not([data-state="paging"]) .mnt-pager__dot::after { animation: none; opacity: 0; }
.mnt-pager__spark figcaption {
  display: flex; justify-content: space-between; margin-top: 6px;
  font: 500 10px/1 ui-monospace, Menlo, monospace; color: var(--mnt-pager-faint); font-variant-numeric: tabular-nums;
}

/* escalation chain */
.mnt-pager__chain { position: relative; list-style: none; margin: 16px 0 0; padding: 0; display: grid; gap: 10px; }
.mnt-pager__chain::before { content: ""; position: absolute; left: 15px; top: 16px; bottom: 16px; width: 1.5px; background: var(--mnt-pager-line); }
.mnt-pager__chain li {
  position: relative; display: grid; grid-template-columns: 32px minmax(0, 1fr) auto; align-items: center; gap: 10px;
  transition: opacity .4s var(--mnt-pager-ease);
  &[data-s="off"] { opacity: .45; }
}
.mnt-pager__av {
  display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%;
  font-size: 10px; font-weight: 750; letter-spacing: .02em;
  color: var(--mnt-pager-fg); background: var(--mnt-pager-panel); box-shadow: 0 0 0 3px var(--mnt-pager-bg), inset 0 0 0 1px var(--mnt-pager-line);
}
.mnt-pager__chain li[data-s="now"] .mnt-pager__av { color: var(--mnt-pager-bg); background: var(--mnt-pager-tone); box-shadow: 0 0 0 3px var(--mnt-pager-bg), 0 0 0 5px color-mix(in oklab, var(--mnt-pager-tone) 35%, transparent); }
.mnt-pager__chain li[data-s="done"] .mnt-pager__av { color: var(--mnt-pager-bg); background: var(--mnt-pager-fg); }
.mnt-pager__who { min-width: 0; }
.mnt-pager__who b { display: block; font-size: 13px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnt-pager__who span { display: block; font-size: 11.5px; color: var(--mnt-pager-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnt-pager__when {
  display: inline-flex; align-items: center; gap: 6px; font-style: normal; font-size: 11.5px; color: var(--mnt-pager-dim); white-space: nowrap; font-variant-numeric: tabular-nums;
  & time { font: 600 12px/1 ui-monospace, Menlo, monospace; color: var(--mnt-pager-fg); }
  & svg { width: 18px; height: 18px; rotate: -90deg; }
  & .mnt-pager__rt { stroke: var(--mnt-pager-line); stroke-width: 2.5; }
  & .mnt-pager__rf { stroke: var(--mnt-pager-tone); stroke-width: 2.5; stroke-dasharray: 100; stroke-dashoffset: calc(var(--off, 0) * 1px); transition: stroke-dashoffset 1s linear; }
}
.mnt-pager__chain li[data-s="now"] .mnt-pager__when { color: var(--mnt-pager-tone); font-weight: 650; }

/* slide to acknowledge */
.mnt-pager__ctl { display: grid; grid-template-rows: 1fr; margin-top: 18px; }
.mnt-pager__in { min-height: 0; display: grid; }
.mnt-pager__in > * { grid-area: 1 / 1; }
.mnt-pager__slide {
  --x: 0px;
  position: relative; height: 54px; border-radius: 27px; overflow: hidden;
  background: color-mix(in oklab, var(--mnt-pager-tone) 14%, var(--mnt-pager-bg));
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mnt-pager-tone) 35%, transparent);
  touch-action: none; cursor: grab; -webkit-user-select: none; user-select: none;
  transition: opacity .35s var(--mnt-pager-ease), scale .45s var(--mnt-pager-spring), visibility 0s;
  &:focus-visible { outline: 2px solid var(--mnt-pager-tone); outline-offset: 3px; }
  &.is-drag { cursor: grabbing; }
}
.mnt-pager__fill {
  position: absolute; inset: 0; border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in oklab, var(--mnt-pager-tone) 35%, transparent), color-mix(in oklab, var(--mnt-pager-tone) 70%, transparent));
  clip-path: inset(0 calc(100% - var(--x) - 51px) 0 0 round 27px);
  transition: clip-path .55s var(--mnt-pager-spring);
}
.mnt-pager__hint {
  position: absolute; inset: 0; display: grid; place-items: center; padding-left: 40px;
  font-size: 13.5px; font-weight: 650; letter-spacing: .01em;
  color: transparent;
  background: linear-gradient(100deg, var(--mnt-pager-dim) 40%, var(--mnt-pager-fg) 50%, var(--mnt-pager-dim) 60%) 0 0 / 250% 100%;
  -webkit-background-clip: text; background-clip: text;
  animation: mnt-pager-shine 2.4s linear infinite;
  opacity: var(--hint, 1);
  transition: opacity .3s;
}
.mnt-pager__thumb {
  position: absolute; left: 4px; top: 4px; display: grid; place-items: center; width: 46px; height: 46px; border-radius: 50%;
  color: var(--mnt-pager-bg); background: var(--mnt-pager-tone);
  box-shadow: 0 6px 16px -6px color-mix(in oklab, var(--mnt-pager-tone) 80%, transparent);
  translate: var(--x) 0;
  transition: translate .55s var(--mnt-pager-spring), scale .3s var(--mnt-pager-spring);
  & svg { width: 20px; height: 20px; stroke-width: 2.4; animation: mnt-pager-nudge 1.6s var(--mnt-pager-ease) infinite; }
}
.mnt-pager__slide.is-drag :is(.mnt-pager__thumb, .mnt-pager__fill) { transition: none; }
.mnt-pager__slide[data-armed] .mnt-pager__thumb { scale: 1.08; }
.mnt-pager__slide.is-drag .mnt-pager__thumb svg, .mnt-pager__slide[data-armed] .mnt-pager__thumb svg { animation: none; }

.mnt-pager__acts {
  display: flex; flex-wrap: wrap; align-content: center; gap: 8px;
  & button {
    flex: 1 1 auto; display: inline-flex; align-items: center; justify-content: center; gap: 7px;
    min-height: 46px; padding: 0 14px; border-radius: 14px; font-size: 13px; font-weight: 680;
    background: var(--mnt-pager-panel); box-shadow: inset 0 0 0 1px var(--mnt-pager-line);
    transition: background-color .2s, scale .3s var(--mnt-pager-spring), opacity .35s var(--mnt-pager-ease), translate .45s var(--mnt-pager-spring);
  }
  & button:hover { background: color-mix(in oklch, var(--mnt-pager-fg) 12%, var(--mnt-pager-bg)); }
  & button:active { scale: .97; }
  & button.is-main { color: var(--mnt-pager-bg); background: var(--mnt-pager-ok); box-shadow: none; }
  & button.is-main:hover { background: color-mix(in oklab, var(--mnt-pager-ok) 85%, var(--mnt-pager-fg)); }
  & svg { width: 17px; height: 17px; }
}
@starting-style {
  .mnt-pager__acts button { opacity: 0; translate: 0 10px; }
}
.mnt-pager:not([data-state="paging"]) .mnt-pager__slide { opacity: 0; scale: .96; visibility: hidden; pointer-events: none; transition: opacity .3s, scale .3s, visibility 0s .3s; }
.mnt-pager[data-state="paging"] .mnt-pager__acts { visibility: hidden; }
.mnt-pager__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 330px) {
  .mnt-pager__since { font-size: 0; }
  .mnt-pager__since time { font-size: 12px; }
  .mnt-pager__hint { font-size: 12.5px; }
  .mnt-pager__acts button { padding: 0 10px; font-size: 12.5px; }
}

@keyframes mnt-pager-sweep { to { --mnt-pager-a: 360deg; } }
@keyframes mnt-pager-throb { 50% { opacity: .45; } }
@keyframes mnt-pager-ping { 0% { scale: 1; opacity: .8; } 80%, 100% { scale: 2.8; opacity: 0; } }
@keyframes mnt-pager-shine { from { background-position: 100% 0; } to { background-position: -50% 0; } }
@keyframes mnt-pager-nudge { 0%, 60%, 100% { translate: 0 0; } 30% { translate: 3px 0; } }

@media (prefers-reduced-motion: reduce) {
  .mnt-pager { transition: --mnt-pager-tone .2s linear; }
  .mnt-pager::before { animation: none; background: color-mix(in oklab, var(--mnt-pager-tone) 55%, transparent); }
  .mnt-pager::after, .mnt-pager__state i::after, .mnt-pager__dot::after, .mnt-pager__thumb svg { animation: none; }
  .mnt-pager__state i::after, .mnt-pager__dot::after { opacity: 0; }
  .mnt-pager__hint { animation: none; color: var(--mnt-pager-fg); background: none; }
  .mnt-pager__thumb, .mnt-pager__fill { transition: translate .15s linear, clip-path .15s linear; }
  @starting-style {
    .mnt-pager__acts button { translate: 0 0; }
  }
}

