const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const slide = $('.mnt-pager__slide'), thumb = $('.mnt-pager__thumb'), acts = $('.mnt-pager__acts'), chain = $('.mnt-pager__chain');
const sr = $('.mnt-pager__sr');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const say = (t) => { sr.textContent = ''; later(40, () => { sr.textContent = t; }); };

/* the alert: one reading a minute, 08:45 to 09:14, threshold 2% */
const SERIES = [0.4, 0.5, 0.4, 0.3, 0.5, 0.4, 0.6, 0.5, 0.4, 0.5, 0.4, 0.5, 0.6, 0.5, 0.4, 0.5, 0.7, 0.6, 0.5, 0.6, 0.8, 1.1, 1.4, 1.6, 2.4, 3.8, 6.1, 8.9, 11.6, 14.2];
const MAX = 16, Y = (v) => 66 - (v / MAX) * 60;
const pts = SERIES.map((v, i) => [(i / (SERIES.length - 1)) * 300, Y(v)]);
const d = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('');
$('.mnt-pager__line').setAttribute('d', d);
$('.mnt-pager__area').setAttribute('d', d + 'L300 72L0 72Z');
$('.mnt-pager__th').setAttribute('d', 'M0 ' + Y(2).toFixed(1) + 'H300');
$('.mnt-pager__dot').style.setProperty('--y', Y(SERIES[SERIES.length - 1]).toFixed(1));

const PAGED_AT = 9 * 3600 + 14 * 60 + 7;        // 09:14:07
const ESC = 300, ESC2 = 900;                     // secondary at 5 min, manager at 15 min
const START = 12;                                 // the page arrived 12 s before mount
const ICON = {
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  up: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5M6 11l6-6 6 6"/></svg>',
  redo: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 8.5A7.5 7.5 0 1 0 19.5 15"/><path d="M19.5 4v4.5H15"/></svg>',
};
const RING = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle class="mnt-pager__rt" cx="12" cy="12" r="9" pathLength="100"/><circle class="mnt-pager__rf" cx="12" cy="12" r="9" pathLength="100"/></svg>';

let state = 'paging', t0 = performance.now() - START * 1000, ackAt = 0, endAt = 0, onscreen = true, by = '';
const elapsed = () => (performance.now() - t0) / 1000;
const mmss = (s) => { s = Math.max(0, Math.floor(s)); return String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); };
const clock = (s) => { s = Math.floor(PAGED_AT + s); return [Math.floor(s / 3600), Math.floor(s / 60) % 60, s % 60].map((n) => String(n).padStart(2, '0')).join(':'); };
const span = (s) => { s = Math.floor(s); return s < 60 ? s + ' s' : Math.floor(s / 60) + ' min ' + (s % 60) + ' s'; };

const PEOPLE = [['You', 'YOU', 'Primary on-call'], ['Lena Brooks', 'LB', 'Secondary'], ['Omar Reyes', 'OR', 'Engineering manager']];
chain.innerHTML = PEOPLE.map((p) => '<li><span class="mnt-pager__av" aria-hidden="true">' + p[1] + '</span><div class="mnt-pager__who"><b>' + p[0] + '</b><span>' + p[2] + '</span></div><em class="mnt-pager__when"></em></li>').join('');
const rows = $$('li', chain);

let chainKey = '';
const renderChain = () => {
  const e = elapsed(), key = state + '|' + by;
  if (key !== chainKey) {
    chainKey = key;
    const set = (i, st, html) => { rows[i].dataset.s = st; rows[i].querySelector('.mnt-pager__when').innerHTML = html; };
    if (state === 'paging') {
      set(0, 'now', 'Paging now');
      set(1, 'next', RING + 'in <time data-t="' + ESC + '"></time>');
      set(2, 'next', 'in <time data-t="' + ESC2 + '"></time>');
    } else if (state === 'acked') {
      set(0, 'done', 'Acked <time>' + clock(ackAt) + '</time>');
      set(1, 'off', 'Cancelled');
      set(2, 'off', 'Cancelled');
    } else if (state === 'escalated') {
      set(0, by === 'timeout' ? 'off' : 'done', by === 'timeout' ? 'No answer' : 'Handed off');
      set(1, 'now', 'Paging now');
      set(2, 'next', 'in <time data-t="' + ESC2 + '"></time>');
    } else {
      set(0, 'done', 'Resolved <time>' + clock(endAt) + '</time>');
      set(1, 'off', by === 'lena' ? 'Stood down' : 'Cancelled');
      set(2, 'off', 'Cancelled');
    }
  }
  $$('time[data-t]', chain).forEach((t) => { t.textContent = mmss(+t.dataset.t - e); });
  const rf = rows[1].querySelector('.mnt-pager__rf');
  if (rf) rf.style.setProperty('--off', (100 * (1 - Math.max(0, ESC - e) / ESC)).toFixed(2));
};

const renderActs = () => {
  let h = '';
  if (state === 'acked') h = '<button type="button" class="is-main" data-do="resolve">' + ICON.check + 'Resolve</button><button type="button" data-do="escalate">' + ICON.up + 'Escalate to Lena</button>';
  else if (state === 'escalated') h = '<button type="button" class="is-main" data-do="resolve">' + ICON.check + 'Resolve</button><button type="button" data-do="reack">Take it back</button>';
  else if (state === 'resolved') h = '<button type="button" data-do="reopen">' + ICON.redo + 'Reopen INC-2291</button>';
  acts.innerHTML = h;
};

const setState = (s, focus) => {
  state = s;
  root.dataset.state = s;
  const lab = { paging: 'Paging you', acked: 'Acknowledged', escalated: 'Escalated to Lena', resolved: 'Resolved' }[s];
  $('.mnt-pager__state b').textContent = lab;
  $('.mnt-pager__title').textContent = s === 'resolved' ? 'checkout-api 5xx resolved' : 'checkout-api 5xx rate at 14.2%';
  $('.mnt-pager__sub').innerHTML = s === 'resolved'
    ? 'Resolved ' + span(endAt) + ' after the page · eu-central-1 · <b>INC-2291</b>'
    : s === 'acked' ? 'Acknowledged in ' + span(ackAt) + ' · eu-central-1 · <b>INC-2291</b>'
    : 'Above the 2% threshold for 5 min · eu-central-1 · <b>INC-2291</b>';
  slide.inert = s !== 'paging';
  renderActs();
  renderChain();
  if (focus) later(30, () => { const b = s === 'paging' ? slide : acts.querySelector('button'); if (b) b.focus({ preventScroll: true }); });
};

/* ---------- slider ---------- */
let pos = 0, max = 0, drag = null;
const measure = () => { max = Math.max(0, slide.clientWidth - 54); };
const setPos = (p, quiet) => {
  pos = Math.max(0, Math.min(1, p));
  slide.style.setProperty('--x', (pos * max).toFixed(1) + 'px');
  slide.style.setProperty('--hint', Math.max(0, 1 - pos * 1.7).toFixed(3));
  slide.toggleAttribute('data-armed', pos >= 0.9);
  slide.setAttribute('aria-valuenow', Math.round(pos * 100));
  if (!quiet) slide.setAttribute('aria-valuetext', pos >= 0.9 ? 'Release to acknowledge' : Math.round(pos * 100) + '%, keep sliding to acknowledge');
};
const acknowledge = (how) => {
  if (state !== 'paging') return;
  ackAt = elapsed();
  setPos(1, true);
  later(RM.matches ? 0 : 260, () => {
    setState('acked', true);
    setPos(0, true);
    slide.setAttribute('aria-valuetext', 'Acknowledged');
  });
  say('Acknowledged ' + span(ackAt) + ' after the page. Escalation to Lena Brooks cancelled.');
};

slide.addEventListener('pointerdown', (e) => {
  if (state !== 'paging' || e.button !== 0) return;
  measure();
  const r = slide.getBoundingClientRect();
  const onThumb = e.target.closest('.mnt-pager__thumb');
  drag = { id: e.pointerId, x0: e.clientX, p0: onThumb ? pos : pos, left: r.left, t: e.timeStamp, v: 0, last: e.clientX };
  slide.setPointerCapture(e.pointerId);
  slide.classList.add('is-drag');
});
slide.addEventListener('pointermove', (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  const dt = Math.max(1, e.timeStamp - drag.t);
  drag.v = 0.7 * ((e.clientX - drag.last) / dt) + 0.3 * drag.v;
  drag.t = e.timeStamp; drag.last = e.clientX;
  setPos(drag.p0 + (e.clientX - drag.x0) / Math.max(1, max));
});
const release = (e) => {
  if (!drag || e.pointerId !== drag.id) return;
  const v = drag.v;
  drag = null;
  slide.classList.remove('is-drag');
  if (pos >= 0.9 || (pos > 0.6 && v > 0.9)) acknowledge('slide');
  else { setPos(0); slide.setAttribute('aria-valuetext', 'Not acknowledged'); }
};
slide.addEventListener('pointerup', release);
slide.addEventListener('pointercancel', release);
slide.addEventListener('keydown', (e) => {
  if (state !== 'paging') return;
  measure();
  const step = { ArrowRight: 0.1, ArrowUp: 0.1, ArrowLeft: -0.1, ArrowDown: -0.1, PageUp: 0.25, PageDown: -0.25 }[e.key];
  if (step !== undefined) { e.preventDefault(); setPos(pos + step); if (pos >= 1) acknowledge('key'); return; }
  if (e.key === 'End') { e.preventDefault(); acknowledge('key'); return; }
  if (e.key === 'Home') { e.preventDefault(); setPos(0); }
});
slide.addEventListener('blur', () => { if (state === 'paging' && !drag && pos < 1) { setPos(0, true); slide.setAttribute('aria-valuetext', 'Not acknowledged'); } });

acts.addEventListener('click', (e) => {
  const b = e.target.closest('[data-do]');
  if (!b) return;
  const a = b.dataset.do;
  if (a === 'resolve') { by = state === 'escalated' ? 'lena' : 'you'; endAt = elapsed(); setState('resolved', true); say('Resolved INC-2291, ' + span(endAt) + ' after the page.'); }
  else if (a === 'escalate') { by = 'you'; setState('escalated', true); say('Escalated to Lena Brooks, who is being paged now.'); }
  else if (a === 'reack') { ackAt = elapsed(); by = ''; setState('acked', true); say('You took the page back from Lena Brooks.'); }
  else if (a === 'reopen') { t0 = performance.now(); ackAt = 0; endAt = 0; by = ''; setPos(0, true); setState('paging', true); say('INC-2291 reopened. Paging you again.'); }
});

/* wall-clock ticker: correct after a hidden tab, quiet while off screen */
const tick = () => {
  if (state === 'paging' && elapsed() >= ESC) { by = 'timeout'; setState('escalated', false); say('No acknowledgement after 5 minutes. Paging Lena Brooks.'); }
  if (!onscreen || document.hidden) return;
  $('.mnt-pager__since time').textContent = mmss(state === 'resolved' ? endAt : elapsed());
  renderChain();
};
const iv = setInterval(() => {
  if (!root.isConnected) { clearInterval(iv); return; }
  tick();
}, 1000);

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  root.toggleAttribute('data-offscreen', !onscreen);
  if (onscreen) tick();
});
io.observe(root);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  measure();
  setPos(pos, true);
});
ro.observe(slide);

measure();
setState('paging', false);
tick();
